AUTO_HEAL_STATE = {
  "initialized": False,
  "degraded_mode": False,
  "last_failure": None,
  "failure_count": 0,
  "last_self_test": None,
  "watchdog_started": False,
  "watchdog_cycles": 0,
}
AUTO_HEAL_LOCK = threading.Lock()
MARKET_DATA_LOCK = threading.Lock()
MARKET_DATA_CB_THRESHOLD = 3
MARKET_DATA_CB_OPEN_SECONDS = 90
MARKET_DATA_CIRCUIT = {
  "failures": {},
  "open_until": {},
  "last_good_quote": {},
  "last_good_series": {},
  "quote_source": {},
  "series_source": {},
}
JARVIS_AUTONOMY_LOCK = threading.Lock()
JARVIS_AUTONOMY_STATE = {
  "started": False,
  "cycles": 0,
  "last_cycle_at": None,
  "last_action": "idle",
  "last_error": None,
}
CAMERA_PHONE_LOCK = threading.Lock()
CAMERA_PHONE_SESSIONS: dict[str, dict] = {}
CAMERA_PHONE_TTL_SECONDS = 60 * 30
SYSTEM_HEALTH_LOCK = threading.Lock()
SYSTEM_HEALTH_CACHE = {
  "lite": {"generated_at": 0.0, "payload": None},
  "full": {"generated_at": 0.0, "payload": None},
}
SYSTEM_HEALTH_CACHE_TTL_SECONDS = 20


def _camera_phone_cleanup():
  cutoff = datetime.now(timezone.utc) - timedelta(seconds=CAMERA_PHONE_TTL_SECONDS)
  with CAMERA_PHONE_LOCK:
    stale = [token for token, data in CAMERA_PHONE_SESSIONS.items() if data.get("created_at") and data.get("created_at") < cutoff]
    for token in stale:
      CAMERA_PHONE_SESSIONS.pop(token, None)


def _camera_phone_candidate_urls(token: str, req) -> list[str]:
  path = f"/jarvis-phone-camera/{token}"
  urls = [f"{req.host_url.rstrip('/')}{path}"]

  try:
    host_header = str(req.host or "")
    port = host_header.split(":", 1)[1] if ":" in host_header else ("443" if req.is_secure else "5000")
    host_ip = socket.gethostbyname(socket.gethostname())
    ips = {host_ip}
    for ip in socket.gethostbyname_ex(socket.gethostname())[2]:
      ips.add(ip)
    for ip in sorted(ips):
      if not ip or ip.startswith("127."):
        continue
      scheme = "https" if req.is_secure else "http"
      urls.append(f"{scheme}://{ip}:{port}{path}")
  except Exception:
    pass

  deduped = []
  seen = set()
  for item in urls:
    if item in seen:
      continue
    seen.add(item)
    deduped.append(item)
  return deduped


def _mark_failure(reason: str):
  with AUTO_HEAL_LOCK:
    AUTO_HEAL_STATE["degraded_mode"] = True
    AUTO_HEAL_STATE["failure_count"] = int(AUTO_HEAL_STATE.get("failure_count", 0)) + 1
    AUTO_HEAL_STATE["last_failure"] = {
      "reason": reason,
      "timestamp": datetime.now(timezone.utc).isoformat(),
    }


def _mark_recovered(note: str = "auto-heal recovery"):
  with AUTO_HEAL_LOCK:
    AUTO_HEAL_STATE["degraded_mode"] = False
    AUTO_HEAL_STATE["last_failure"] = {
      "reason": note,
      "timestamp": datetime.now(timezone.utc).isoformat(),
    }


def _market_circuit_open(key: str) -> bool:
  with MARKET_DATA_LOCK:
    return float(MARKET_DATA_CIRCUIT["open_until"].get(key, 0.0)) > monotonic()


def _market_record_success(key: str):
  with MARKET_DATA_LOCK:
    MARKET_DATA_CIRCUIT["failures"][key] = 0
    MARKET_DATA_CIRCUIT["open_until"].pop(key, None)


def _market_record_failure(key: str, reason: str):
  with MARKET_DATA_LOCK:
    count = int(MARKET_DATA_CIRCUIT["failures"].get(key, 0)) + 1
    MARKET_DATA_CIRCUIT["failures"][key] = count
    if count >= MARKET_DATA_CB_THRESHOLD:
      MARKET_DATA_CIRCUIT["open_until"][key] = monotonic() + MARKET_DATA_CB_OPEN_SECONDS
  if int(MARKET_DATA_CIRCUIT["failures"].get(key, 0)) >= MARKET_DATA_CB_THRESHOLD:
    _mark_failure(f"market circuit open for {key}: {reason}")


def _market_get_cached_quote(symbol: str):
  with MARKET_DATA_LOCK:
    return MARKET_DATA_CIRCUIT["last_good_quote"].get(symbol.upper())


def _market_set_cached_quote(symbol: str, price: float, change_pct: float):
  with MARKET_DATA_LOCK:
    MARKET_DATA_CIRCUIT["last_good_quote"][symbol.upper()] = {
      "price": round(float(price), 2),
      "change_pct": round(float(change_pct), 2),
      "timestamp": datetime.now(timezone.utc).isoformat(),
    }


def _market_set_quote_source(symbol: str, source: str):
  with MARKET_DATA_LOCK:
    MARKET_DATA_CIRCUIT["quote_source"][symbol.upper()] = {
      "source": str(source),
      "timestamp": datetime.now(timezone.utc).isoformat(),
    }


def _market_get_quote_source(symbol: str) -> dict:
  with MARKET_DATA_LOCK:
    return dict(MARKET_DATA_CIRCUIT["quote_source"].get(symbol.upper()) or {"source": "unknown"})


def _market_get_cached_series(symbol: str):
  with MARKET_DATA_LOCK:
    return MARKET_DATA_CIRCUIT["last_good_series"].get(symbol.upper())


def _market_set_cached_series(symbol: str, values: list[float]):
  with MARKET_DATA_LOCK:
    MARKET_DATA_CIRCUIT["last_good_series"][symbol.upper()] = {
      "values": [round(float(v), 2) for v in list(values)[-20:]],
      "timestamp": datetime.now(timezone.utc).isoformat(),
    }


def _market_set_series_source(symbol: str, source: str):
  with MARKET_DATA_LOCK:
    MARKET_DATA_CIRCUIT["series_source"][symbol.upper()] = {
      "source": str(source),
      "timestamp": datetime.now(timezone.utc).isoformat(),
    }


def _market_get_series_source(symbol: str) -> dict:
  with MARKET_DATA_LOCK:
    return dict(MARKET_DATA_CIRCUIT["series_source"].get(symbol.upper()) or {"source": "unknown"})


def _market_data_source_status(symbol: str) -> dict:
  return {
    "symbol": symbol.upper(),
    "quote": _market_get_quote_source(symbol),
    "series": _market_get_series_source(symbol),
  }


def _jarvis_explanation(intent: str, action: str, success: bool, symbol: str | None) -> str:
  intent_label = str(intent or "general")
  action_label = str(action or "command processed")
  market = str(symbol or "market")
  if not success:
    return f"JARVIS attempted intent '{intent_label}' for {market}, but the action failed and recovery mode captured the error."
  return f"JARVIS mapped your command to intent '{intent_label}', executed '{action_label}', and generated this response for {market}."


def _jarvis_time_greeting(now: datetime | None = None) -> str:
  current = now or datetime.now()
  hour = current.hour
  if 4 <= hour < 12:
    return "Good morning"
  if 12 <= hour < 18:
    return "Good afternoon"
  return "Good evening"


def _jarvis_effective_intent(request_intent: str, action: str) -> str:
  intent_label = str(request_intent or '').strip().lower()
  if intent_label and intent_label != 'general':
    return intent_label

  action_label = str(action or '').strip().lower()
  action_map = {
    'trade brief generated': 'trade_brief',
    'recommendations generated': 'recommendations',
    'prediction generated': 'price_prediction',
    'risk assessed': 'risk_assessment',
    'trend analysis complete': 'market_trend',
    'chart analyzed': 'analyze_chart',
    'ai insights generated': 'ai_insights',
    'buy signal generated': 'buy_signal',
    'quick trade executed': 'quick_trade',
    'status retrieved': 'system_status',
    'account info retrieved': 'account_info',
    'performance retrieved': 'performance_check',
    'help displayed': 'help',
    'learning checked': 'check_learning',
    'system analysis complete': 'system_update',
    'trade executed': 'start_trade',
    'session stopped': 'stop_trade',
    'autonomous cycle completed': 'autonomous_cycle',
    'autonomy enabled': 'autonomy_enable',
    'autonomy disabled': 'autonomy_disable',
    'autonomy status retrieved': 'autonomy_status',
    'autonomy report generated': 'autonomy_report',
  }
  return action_map.get(action_label, intent_label or 'general')


def _data_dir_writable() -> bool:
  try:
    probe = DATA_DIR / ".jarvis_write_probe"
    probe.write_text("ok", encoding="utf-8")
    probe.unlink(missing_ok=True)
    return True
  except Exception:
    return False


def _dependency_checks() -> dict:
  return {
    "data_dir_exists": DATA_DIR.exists(),
    "data_dir_writable": _data_dir_writable(),
    "jarvis_analytics_loaded": jarvis_analytics is not None,
    "voice_engine_loaded": VOICE_ENGINE is not None,
    "mt5_engine_loaded": MT5_ENGINE is not None,
    "mt4_engine_loaded": MT4_ENGINE is not None,
  }


def _route_presence_check() -> dict:
  required_routes = ["/", "/jarvis-voice", "/jarvis", "/jarvis-ai", "/api/market-summary", "/api/jarvis-command"]
  registered = {rule.rule for rule in app.url_map.iter_rules()}
  missing = [path for path in required_routes if path not in registered]
  return {
    "required_routes": required_routes,
    "missing_routes": missing,
    "all_present": len(missing) == 0,
  }


def run_auto_heal_self_test() -> dict:
  checks = _dependency_checks()
  routes = _route_presence_check()
  healthy = all(bool(v) for v in checks.values()) and bool(routes.get("all_present"))
  report = {
    "ok": healthy,
    "checks": checks,
    "routes": routes,
    "timestamp": datetime.now(timezone.utc).isoformat(),
  }

  with AUTO_HEAL_LOCK:
    AUTO_HEAL_STATE["last_self_test"] = report

  if healthy:
    _mark_recovered("self-test passed")
  else:
    _mark_failure("self-test failed")

  return report


def _auto_heal_watchdog_loop():
  while True:
    try:
      report = run_auto_heal_self_test()
      with AUTO_HEAL_LOCK:
        AUTO_HEAL_STATE["watchdog_cycles"] = int(AUTO_HEAL_STATE.get("watchdog_cycles", 0)) + 1
      if not report.get("ok"):
        logger.warning("Auto-heal watchdog detected degraded state: %s", report)
    except Exception as exc:
      logger.error("Auto-heal watchdog exception: %s", exc)
      _mark_failure(f"watchdog exception: {exc}")
    sleep(30)


def _ensure_auto_heal_started():
  with AUTO_HEAL_LOCK:
    if AUTO_HEAL_STATE.get("watchdog_started"):
      return
    AUTO_HEAL_STATE["watchdog_started"] = True

  # Prevent duplicate watchdog in the reloader parent process.
  if os.environ.get("WERKZEUG_RUN_MAIN") not in (None, "true"):
    return

  run_auto_heal_self_test()
  threading.Thread(target=_auto_heal_watchdog_loop, daemon=True).start()
  logger.info("Auto-heal watchdog started")


def _jarvis_run_autonomy_cycle_once():
  state = load_auto_trader_state()
  autonomy = _jarvis_autonomy_block(state)
  if not autonomy.get("enabled"):
    return

  cycle = _jarvis_autonomous_cycle()
  primary = cycle.get("primary") if isinstance(cycle.get("primary"), dict) else {}
  secondary = cycle.get("secondary") if isinstance(cycle.get("secondary"), dict) else {}

  primary_symbol = str(primary.get("symbol") or "XAUUSD").upper()
  secondary_symbol = str(secondary.get("symbol") or "").upper()
  focus_symbol = primary_symbol

  settings_block = state.get('settings') if isinstance(state.get('settings'), dict) else {}
  asset_settings = settings_block.get('asset_settings') if isinstance(settings_block.get('asset_settings'), dict) else {}

  def _is_auto_enabled(sym: str) -> bool:
    cfg = asset_settings.get(str(sym or '').upper()) if isinstance(asset_settings, dict) else None
    if not isinstance(cfg, dict):
      return False
    return bool(cfg.get('auto_enabled', False))

  primary_enabled = _is_auto_enabled(primary_symbol)
  secondary_enabled = _is_auto_enabled(secondary_symbol)
  if not primary_enabled and secondary_enabled:
    focus_symbol = secondary_symbol
  elif not primary_enabled and not secondary_enabled:
    _jarvis_memory_record(
      state,
      "auto_scan",
      "scan complete, no execution: all per-asset auto modes are disabled",
      symbol=primary_symbol,
    )
    save_auto_trader_state(state)
    return

  symbol_stats = _jarvis_memory_block(state).get("symbol_stats") if isinstance(_jarvis_memory_block(state).get("symbol_stats"), dict) else {}
  primary_bucket = symbol_stats.get(primary_symbol) if isinstance(symbol_stats.get(primary_symbol), dict) else {}
  primary_reject_streak = int(primary_bucket.get("auto_reject_streak", 0) or 0)
  primary_conf = float(primary.get("confidence_pct") or 0)
  secondary_conf = float(secondary.get("confidence_pct") or 0)

  if secondary_symbol and primary_reject_streak >= 3 and secondary_conf >= (primary_conf - 3):
    focus_symbol = secondary_symbol
    _jarvis_memory_record(
      state,
      "auto_rotation",
      f"rotated focus from {primary_symbol} to {secondary_symbol} after reject streak {primary_reject_streak}",
      symbol=secondary_symbol,
    )

  cycle_focus = dict(cycle)
  if focus_symbol == secondary_symbol and secondary_symbol:
    cycle_focus["primary"] = secondary

  autonomy["last_run_at"] = datetime.now(timezone.utc).isoformat()
  autonomy["last_focus_symbol"] = focus_symbol

  should_execute, reason = _autonomy_should_execute(cycle_focus, state)
  if should_execute:
    dynamic_profile = _jarvis_dynamic_execution_profile(cycle_focus, state, focus_symbol)
    autonomy_payload = {
      "symbol": focus_symbol,
      "lot_size": dynamic_profile.get("lot_size"),
      "risk_percent": dynamic_profile.get("risk_percent"),
    }
    with app.test_request_context('/api/auto-trade/execute', method='POST', json=autonomy_payload):
      # In-process call: 'internal' is set here, never taken from a request body (execution safety 1).
      response = _logged_execute(autonomy_payload, internal_auto_execute=True, source='autonomy')
      response_obj = response[0] if isinstance(response, tuple) else response
      payload = response_obj.get_json(silent=True) or {}
      status = str(payload.get("status") or "ok")
      msg = str(payload.get("message") or "autonomous trade attempted")
      trade_record = payload.get("trade") if isinstance(payload.get("trade"), dict) else {}
      executed_now = status == "ok" and bool(trade_record)
      if executed_now:
        autonomy["last_execution_at"] = datetime.now(timezone.utc).isoformat()
      _jarvis_memory_record(
        state,
        "auto_execute" if executed_now else "auto_scan",
        f"{status}: {msg}; lot={dynamic_profile.get('lot_size')} risk={dynamic_profile.get('risk_percent')} ({dynamic_profile.get('rationale')})",
        symbol=focus_symbol,
      )
      if executed_now:
        _jarvis_memory_record_execution_result(state, focus_symbol, trade_record)
      _jarvis_set_symbol_reject_streak(state, focus_symbol, executed=executed_now)
      with JARVIS_AUTONOMY_LOCK:
        JARVIS_AUTONOMY_STATE["last_action"] = f"executed {focus_symbol}" if executed_now else f"scan only ({status})"
  else:
    threshold = autonomy.get("last_dynamic_min_confidence_pct")
    profile = autonomy.get("last_policy_profile")
    _jarvis_memory_record(
      state,
      "auto_scan",
      f"scan complete, no execution: {reason}; profile={profile}; dynamic_threshold={threshold}",
      symbol=focus_symbol,
    )
    _jarvis_set_symbol_reject_streak(state, focus_symbol, executed=False)
    with JARVIS_AUTONOMY_LOCK:
      JARVIS_AUTONOMY_STATE["last_action"] = f"scan only ({reason})"

  save_auto_trader_state(state)


def _jarvis_autonomy_loop():
  while True:
    wait_seconds = 180
    try:
      state = load_auto_trader_state()
      autonomy = _jarvis_autonomy_block(state)
      wait_seconds = max(60, int(autonomy.get("scan_interval_sec") or 180))

      if autonomy.get("enabled"):
        _jarvis_run_autonomy_cycle_once()
        with JARVIS_AUTONOMY_LOCK:
          JARVIS_AUTONOMY_STATE["cycles"] = int(JARVIS_AUTONOMY_STATE.get("cycles", 0)) + 1
          JARVIS_AUTONOMY_STATE["last_cycle_at"] = datetime.now(timezone.utc).isoformat()
          JARVIS_AUTONOMY_STATE["last_error"] = None
    except Exception as exc:
      logger.error("Jarvis autonomy loop error: %s", exc)
      with JARVIS_AUTONOMY_LOCK:
        JARVIS_AUTONOMY_STATE["last_error"] = str(exc)
        JARVIS_AUTONOMY_STATE["last_action"] = "error"
    sleep(wait_seconds)


def _ensure_jarvis_autonomy_started():
  with JARVIS_AUTONOMY_LOCK:
    if JARVIS_AUTONOMY_STATE.get("started"):
      return
    JARVIS_AUTONOMY_STATE["started"] = True

  if os.environ.get("WERKZEUG_RUN_MAIN") not in (None, "true"):
    return

  threading.Thread(target=_jarvis_autonomy_loop, daemon=True).start()
  logger.info("Jarvis autonomy scheduler started")


def _ensure_market_scheduler_started():
  """Resume the market scheduler on boot when its saved state says enabled.

  start() was only ever reachable through POST /api/jarvis/market-scheduler/start,
  so after any restart the scheduler stayed idle indefinitely even with
  'enabled': true persisted - which is why scheduled analysis silently stopped.
  """
  if os.environ.get("WERKZEUG_RUN_MAIN") not in (None, "true"):
    return
  try:
    scheduler = get_market_scheduler()
    status = scheduler.get_status() if hasattr(scheduler, 'get_status') else {}
    state = status.get('scheduler', status) if isinstance(status, dict) else {}
    if state.get('enabled') and not state.get('is_running'):
      scheduler.start()
      logger.info("Market scheduler resumed from saved state")
  except Exception as exc:
    logger.error("Market scheduler autostart failed: %s", exc)


@app.before_request
def _auto_heal_bootstrap():
  if not AUTO_HEAL_STATE.get("initialized"):
    AUTO_HEAL_STATE["initialized"] = True
    _ensure_auto_heal_started()
    _ensure_jarvis_autonomy_started()
    _ensure_market_scheduler_started()


@app.after_request
def disable_dynamic_cache(response):
  path = str(request.path or '')
  if (
    path == '/'
    or path == '/jarvis-voice'
    or path == '/jarvis'
    or path == '/jarvis-ai'
    or path.startswith('/api/jarvis')
    or path.startswith('/jarvis_')
    or path == '/static/jarvis_ai_voice.js'
  ):
    response.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
    response.headers['Pragma'] = 'no-cache'
    response.headers['Expires'] = '0'

  response.headers['X-JARVIS-Degraded'] = '1' if AUTO_HEAL_STATE.get('degraded_mode') else '0'

  if path == '/api/jarvis-command' and response.mimetype == 'application/json':
    try:
      payload = response.get_json(silent=True)
      if isinstance(payload, dict):
        req_payload = request.get_json(silent=True) or {}
        req_intent = str(req_payload.get('intent') or '').strip().lower() or 'general'
        transcript = f"{req_payload.get('command', '')} {req_payload.get('transcript', '')}".lower()
        inferred_symbol = 'BTCUSD' if ('btc' in transcript or 'bitcoin' in transcript) else 'XAUUSD'
        action = str(payload.get('action') or 'Command Processed')
        success = bool(payload.get('success'))
        effective_intent = _jarvis_effective_intent(req_intent, action)

        if effective_intent == 'general':
          if any(phrase in transcript for phrase in [
            'open trade',
            'open a trade',
            'open position',
            'open a position',
            'open order',
            'place trade',
            'place an order',
            'can you open',
            'prepare trade',
            'prepare the trade',
          ]):
            effective_intent = 'start_trade'
          elif any(word in transcript for word in ['approve trade', 'confirm trade', 'yes', 'yeah', 'yep', 'approve', 'confirm']):
            effective_intent = 'approval_approve'

        payload.setdefault('intent', effective_intent)
        payload.setdefault('symbol', inferred_symbol)
        if 'confidence' not in payload:
          if effective_intent in {'start_trade', 'approval_approve', 'approval_reject', 'recommendations', 'analyze_chart', 'market_trend', 'price_prediction', 'risk_assessment', 'quick_trade', 'buy_signal'}:
            base_confidence = 0.88 if success else 0.78
          elif effective_intent in {'help', 'system_status', 'account_info'}:
            base_confidence = 0.74 if success else 0.68
          else:
            base_confidence = 0.82 if success else 0.55
          payload['confidence'] = round(base_confidence, 2)
        payload.setdefault('explanation', _jarvis_explanation(payload.get('intent'), action, success, payload.get('symbol')))
        payload.setdefault('timestamp', datetime.now(timezone.utc).isoformat())

        response.set_data(json.dumps(payload))
    except Exception:
      pass

  return response


@app.errorhandler(Exception)
def handle_unexpected_error(error):
  if isinstance(error, HTTPException):
    return error

  error_id = f"ERR-{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S%f')}"
  trace = traceback.format_exc(limit=8)
  logger.error("Unhandled exception %s on %s %s: %s\n%s", error_id, request.method, request.path, error, trace)
  _mark_failure(f"unhandled exception on {request.path}: {error}")

  if request.path.startswith('/api/'):
    return jsonify({
      'status': 'error',
      'error_id': error_id,
      'message': 'JARVIS API temporary failure. Auto-heal is active.',
      'degraded_mode': bool(AUTO_HEAL_STATE.get('degraded_mode')),
      'timestamp': datetime.now(timezone.utc).isoformat(),
    }), 500

  return render_template_string(
    """
    <!doctype html>
    <html><head><meta charset=\"utf-8\"><title>JARVIS Recovery Mode</title></head>
    <body style=\"font-family:Segoe UI,Arial,sans-serif;padding:24px;background:#0f172a;color:#e2e8f0\">
      <h1>JARVIS Recovery Mode</h1>
      <p>A temporary issue was detected and auto-heal is running.</p>
      <p>Error ID: <strong>{{ error_id }}</strong></p>
      <p><a href=\"/\" style=\"color:#38bdf8\">Return to dashboard</a></p>
    </body></html>
    """,
    error_id=error_id,
  ), 500


