@app.context_processor
def inject_main_nav():
  from markupsafe import Markup, escape
  current = request.path
  if current == '/test':
    current = '/signals'
  groups = []
  for group_label, group_links in MAIN_NAV_GROUPS:
    links = []
    for href, label in group_links:
      attrs = " class='active' aria-current='page'" if href == current else ""
      links.append(f"<a href='{href}'{attrs}>{escape(label)}</a>")
    groups.append(
      f"<span class='nav-group'><span class='nav-group-label'>{escape(group_label)}</span>{''.join(links)}</span>"
    )
  return {'main_nav': Markup(_MAIN_NAV_STYLE + ''.join(groups))}


# Pages outside the main templates (JARVIS dashboards, brain pages, voice tools,
# templates/*.html) had their own link sets or none at all, so moving between
# pages meant hunting for a way back. Every HTML page that does not already carry
# the grouped nav gets it inserted right after <body>.
_NAV_INJECT_SKIP_PREFIXES = ('/api/', '/static/', '/data/', '/jarvis-phone-camera', '/healthz', '/readyz')


@app.before_request
def _serve_full_pages_for_nav():
  # File-served pages (voice test, auto-voice listener) answered a browser's
  # "has it changed?" with 304, so the browser kept its copy from before the nav
  # existed and the nav never appeared. Page requests always get the full page;
  # /static, /api and /data keep normal conditional caching.
  if request.method == 'GET' and not request.path.startswith(_NAV_INJECT_SKIP_PREFIXES):
    request.environ.pop('HTTP_IF_NONE_MATCH', None)
    request.environ.pop('HTTP_IF_MODIFIED_SINCE', None)


@app.after_request
def _inject_main_nav_everywhere(response):
  try:
    if (
      response.status_code != 200
      or response.mimetype != 'text/html'
      or request.path.startswith(_NAV_INJECT_SKIP_PREFIXES)
    ):
      return response
    if response.direct_passthrough:
      # Pages served with send_from_directory (voice test, auto-voice listener)
      # stream a file handle; buffer the HTML so the nav can be inserted too.
      response.direct_passthrough = False
    body = response.get_data(as_text=True)
    if 'nav-group-label' in body:
      return response
    import re as _re
    match = _re.search(r'<body[^>]*>', body, _re.IGNORECASE)
    if not match:
      return response
    nav_html = str(inject_main_nav()['main_nav'])
    # Some pages centre their content with a flex-row <body>; there the bar became
    # a side-by-side item next to the page. Give it a full row of its own. These
    # body rules have no effect on pages whose body is not a flex container.
    bar = (
      "<style>body{flex-wrap:wrap;align-content:flex-start;}"
      ".main-nav-injected{width:100%;flex:0 0 auto;align-self:flex-start;box-sizing:border-box;}</style>"
      "<div class='nav main-nav-injected' style='position:sticky;top:0;z-index:9999;"
      "background:rgba(6,11,26,0.96);border-bottom:1px solid rgba(56,189,248,0.4);"
      "box-shadow:0 8px 24px rgba(0,0,0,0.35);margin:0;'>" + nav_html + "</div>"
    )
    response.set_data(body[:match.end()] + bar + body[match.end():])
    # The page is now different from the file on disk; do not let a browser cache
    # it under the file's validators.
    response.headers.pop('ETag', None)
    response.headers.pop('Last-Modified', None)
    response.headers['Cache-Control'] = 'no-cache'
  except Exception:
    logging.getLogger(__name__).exception("main nav injection failed")
  return response


