def save_signals(signals: list[dict]):
    # Write-then-replace so a crash mid-write cannot leave a truncated history.
    tmp_path = SIGNALS_PATH.with_name(SIGNALS_PATH.name + ".tmp")
    tmp_path.write_text(json.dumps(signals, indent=2), encoding="utf-8")
    os.replace(tmp_path, SIGNALS_PATH)


SIGNALS_ARCHIVE_PATH = SIGNALS_PATH.with_name("signals_archive.jsonl")
SIGNAL_HISTORY_MAX_RECORDS = 1000
SIGNAL_HISTORY_REPEAT_SECONDS = 3600
_SIGNAL_HISTORY_VOLATILE_KEYS = ("risk_guardrails", "learning_health")
_signal_history_lock = threading.Lock()


def record_signal_history(payload: list[dict]) -> int:
  """Append freshly built live signals to the signal history.

  Nothing used to write new signals: /api/signals re-saved the ten records it
  had just read, so the history froze on 28 June. A row is written when a
  symbol's side changes, or when a BUY/SELL is still showing an hour after the
  last row for that symbol (the model runs on hourly bars). A continuing HOLD
  is not repeated. Rows beyond the cap move to signals_archive.jsonl instead
  of being dropped, so no history is lost.
  """
  if not payload:
    return 0
  added = 0
  with _signal_history_lock:
    try:
      history = load_signals()
    except ValueError:
      history = []
    if not isinstance(history, list):
      history = []
    last_by_symbol = {}
    for item in history:
      symbol = str(item.get("symbol") or "").upper()
      if symbol:
        last_by_symbol[symbol] = item
    now = datetime.now(timezone.utc)
    for item in payload:
      symbol = str(item.get("symbol") or "").upper()
      side = str(item.get("signal") or "").upper()
      if not symbol or not side:
        continue
      last = last_by_symbol.get(symbol)
      if last is not None and str(last.get("signal") or "").upper() == side:
        if side == "HOLD":
          continue
        try:
          last_at = datetime.strptime(str(last.get("generated_at")), "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
          if (now - last_at).total_seconds() < SIGNAL_HISTORY_REPEAT_SECONDS:
            continue
        except ValueError:
          pass
      record = {key: value for key, value in item.items() if key not in _SIGNAL_HISTORY_VOLATILE_KEYS}
      history.append(record)
      last_by_symbol[symbol] = record
      added += 1
    if not added:
      return 0
    overflow = history[:-SIGNAL_HISTORY_MAX_RECORDS]
    if overflow:
      with SIGNALS_ARCHIVE_PATH.open("a", encoding="utf-8") as handle:
        for old in overflow:
          handle.write(json.dumps(old) + "\n")
      history = history[-SIGNAL_HISTORY_MAX_RECORDS:]
    save_signals(history)
  return added


