def _clamp_int_arg(value, default: int, low: int, high: int) -> int:
  """Parse a user-supplied integer and clamp it, falling back on junk input.

  Query strings reach these endpoints from the browser and from hand-typed URLs,
  so a bare int() here turns '?limit=abc' into a 500 instead of a served page.
  """
  try:
    parsed = int(float(str(value).strip()))
  except (TypeError, ValueError):
    parsed = default
  return int(max(low, min(high, parsed)))


def _clamp_float_arg(value, default: float, low: float, high: float) -> float:
  """Parse a user-supplied float and clamp it, falling back on junk input."""
  try:
    parsed = float(str(value).strip())
  except (TypeError, ValueError):
    parsed = default
  if parsed != parsed:  # NaN
    parsed = default
  return float(max(low, min(high, parsed)))


AUTO_TRADER_STATE_LOCK = threading.RLock()


def _atomic_write_json(path: Path, payload) -> None:
  """Write JSON so a crash mid-write can never truncate the live file.

  Writes to a sibling temp file, flushes to disk, keeps the previous good copy
  as <name>.bak, then renames into place (os.replace is atomic on Windows and
  POSIX). Without this, an interrupted write leaves a half-written state file
  that parses as invalid JSON and costs the whole trade history.
  """
  text = json.dumps(payload, indent=2)
  tmp_path = path.with_suffix(path.suffix + ".tmp")
  with open(tmp_path, "w", encoding="utf-8") as handle:
    handle.write(text)
    handle.flush()
    os.fsync(handle.fileno())
  if path.exists():
    try:
      backup = path.with_suffix(path.suffix + ".bak")
      os.replace(path, backup)
    except OSError:
      pass
  os.replace(tmp_path, path)


def _read_state_json(path: Path):
  """Return parsed JSON dict from path, or None when missing/unreadable."""
  if not path.exists():
    return None
  try:
    parsed = json.loads(path.read_text(encoding="utf-8"))
  except (ValueError, OSError):
    return None
  return parsed if isinstance(parsed, dict) else None


def load_auto_trader_state() -> dict:
  raw = _read_state_json(AUTO_TRADER_STATE_PATH)
  if raw is None and AUTO_TRADER_STATE_PATH.exists():
    # The live file exists but is corrupt. Quarantine it and recover the last
    # good snapshot rather than silently handing back an empty state, which
    # the next save would then persist over the real trade history.
    backup_path = AUTO_TRADER_STATE_PATH.with_suffix(AUTO_TRADER_STATE_PATH.suffix + ".bak")
    recovered = _read_state_json(backup_path)
    try:
      stamp = datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S")
      quarantine = AUTO_TRADER_STATE_PATH.with_suffix(f".corrupt-{stamp}.json")
      os.replace(AUTO_TRADER_STATE_PATH, quarantine)
      logger.error("auto_trader_state.json was corrupt; quarantined at %s", quarantine)
    except OSError:
      logger.error("auto_trader_state.json was corrupt and could not be quarantined")
    if recovered is not None:
      logger.warning("Recovered auto trader state from %s", backup_path)
      raw = recovered
  if raw is not None:
    try:
      if isinstance(raw, dict):
        jarvis = raw.get("jarvis") if isinstance(raw.get("jarvis"), dict) else {}
        memory = jarvis.get("memory") if isinstance(jarvis.get("memory"), dict) else {}
        autonomy = jarvis.get("autonomy") if isinstance(jarvis.get("autonomy"), dict) else {}
        return {
          "session": raw.get("session") if isinstance(raw.get("session"), dict) else None,
          "trades": raw.get("trades") if isinstance(raw.get("trades"), list) else [],
          "settings": raw.get("settings") if isinstance(raw.get("settings"), dict) else {},
          "jarvis": {
            "memory": {
              "events": memory.get("events") if isinstance(memory.get("events"), list) else [],
              "symbol_stats": memory.get("symbol_stats") if isinstance(memory.get("symbol_stats"), dict) else {},
            },
            "autonomy": {
              "enabled": bool(autonomy.get("enabled", False)),
              "auto_execute": bool(autonomy.get("auto_execute", False)),
              "scan_interval_sec": int(autonomy.get("scan_interval_sec", 180) or 180),
              "min_confidence_pct": float(autonomy.get("min_confidence_pct", 68.0) or 68.0),
              "cooldown_sec": int(autonomy.get("cooldown_sec", 240) or 240),
              "last_run_at": autonomy.get("last_run_at"),
              "last_execution_at": autonomy.get("last_execution_at"),
              "last_focus_symbol": str(autonomy.get("last_focus_symbol") or "XAUUSD").upper(),
              "last_dynamic_min_confidence_pct": float(autonomy.get("last_dynamic_min_confidence_pct", autonomy.get("min_confidence_pct", 68.0)) or 68.0),
              "last_dynamic_cooldown_sec": int(autonomy.get("last_dynamic_cooldown_sec", autonomy.get("cooldown_sec", 240)) or 240),
              "last_policy_profile": str(autonomy.get("last_policy_profile") or "default"),
              "last_policy_basis": str(autonomy.get("last_policy_basis") or "default"),
            },
            "approval": {
              "require_user_approval": bool((jarvis.get("approval") or {}).get("require_user_approval", True)),
              "allowed_symbols": [
                str(item or "").upper()
                for item in (((jarvis.get("approval") or {}).get("allowed_symbols")) or ["XAUUSD", "BTCUSD"])
                if str(item or "").strip()
              ],
              "pending_requests": (
                (jarvis.get("approval") or {}).get("pending_requests")
                if isinstance((jarvis.get("approval") or {}).get("pending_requests"), list)
                else []
              ),
              "last_decision_at": (jarvis.get("approval") or {}).get("last_decision_at"),
              "last_decision": (jarvis.get("approval") or {}).get("last_decision"),
            },
          },
        }
    except ValueError:
      pass
  return {
    "session": None,
    "trades": [],
    "settings": {},
    "jarvis": {
      "memory": {"events": [], "symbol_stats": {}},
      "autonomy": {
        "enabled": False,
        "auto_execute": False,
        "scan_interval_sec": 180,
        "min_confidence_pct": 68.0,
        "cooldown_sec": 240,
        "last_run_at": None,
        "last_execution_at": None,
        "last_focus_symbol": "XAUUSD",
        "last_dynamic_min_confidence_pct": 68.0,
        "last_dynamic_cooldown_sec": 240,
        "last_policy_profile": "default",
        "last_policy_basis": "default",
      },
      "approval": {
        "require_user_approval": True,
        "allowed_symbols": ["XAUUSD", "BTCUSD"],
        "pending_requests": [],
        "last_decision_at": None,
        "last_decision": None,
      },
    },
  }


