def _cache_is_valid(cache_entry: dict[str, object]) -> bool:
  return bool(cache_entry) and float(cache_entry.get("expires_at", 0.0)) > monotonic()


def _get_cached_signal_payload():
  if _cache_is_valid(_signal_payload_cache):
    return _signal_payload_cache["value"]
  payload = _build_signal_payload_uncached()
  _signal_payload_cache["value"] = payload
  _signal_payload_cache["expires_at"] = monotonic() + LIVE_CACHE_TTL_SECONDS
  return payload


def _set_cached_signal_payload(payload):
  _signal_payload_cache["value"] = payload
  _signal_payload_cache["expires_at"] = monotonic() + LIVE_CACHE_TTL_SECONDS


def _get_cached_live_series(symbol: str):
  symbol = symbol.upper()
  cache_entry = _live_series_cache.get(symbol, {})
  if _cache_is_valid(cache_entry):
    return cache_entry["value"]
  values = _build_live_series_uncached(symbol)
  _live_series_cache[symbol] = {
    "value": values,
    "expires_at": monotonic() + LIVE_CACHE_TTL_SECONDS,
  }
  return values


