def _history_timestamp(entry: dict):
    raw_value = entry.get("entry_time") or entry.get("generated_at") or entry.get("received_at") or entry.get("trained_at")
    if not raw_value:
        return None
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
        try:
            return datetime.strptime(str(raw_value), fmt).replace(tzinfo=timezone.utc)
        except ValueError:
            continue
    return None


def _empty_performance_bucket():
  return {
    "count": 0,
    "wins": 0,
    "losses": 0,
    "no_result": 0,
    "win_rate": 0,
    "avg_profit_pct": 0,
    "total_return_pct": 0,
    "best_trade_pct": 0,
    "worst_trade_pct": 0,
  }


def _summarize_performance(entries: list[dict], window_hours: int):
  cutoff = datetime.now(timezone.utc) - timedelta(hours=window_hours)
  window_entries = []
  for entry in entries:
    timestamp = _history_timestamp(entry)
    if timestamp is None:
      continue
    if timestamp >= cutoff:
      window_entries.append(entry)

  if not window_entries:
    return _empty_performance_bucket()

  wins = sum(1 for entry in window_entries if entry.get("status") in {"TP1", "TP2", "TP3"})
  losses = sum(1 for entry in window_entries if entry.get("status") == "SL")
  no_result = sum(1 for entry in window_entries if entry.get("status") == "none")
  total_count = len(window_entries)
  # Only closed trades carry a realized return; open marks stay out of the maths.
  decided = [
    entry for entry in window_entries
    if entry.get("status") in {"TP1", "TP2", "TP3", "SL"} and entry.get("profit_pct") is not None
  ]
  profit_values = [float(entry.get("profit_pct", 0) or 0) for entry in decided]
  total_return_pct = 0.0
  if profit_values:
    compounded = 1.0
    for value in profit_values:
      compounded *= (1.0 + value / 100.0)
    total_return_pct = (compounded - 1.0) * 100.0
  return {
    "count": total_count,
    "wins": wins,
    "losses": losses,
    "no_result": no_result,
    # Undecided trades are excluded so the rate reflects settled results only.
    "win_rate": round(wins / max(1, wins + losses) * 100, 1),
    "avg_profit_pct": round(sum(profit_values) / max(1, len(profit_values)), 2) if profit_values else 0,
    "total_return_pct": round(total_return_pct, 2),
    "best_trade_pct": round(max(profit_values), 2) if profit_values else 0,
    "worst_trade_pct": round(min(profit_values), 2) if profit_values else 0,
  }


def _season_bucket(entries: list[dict], label: str):
  if not entries:
    return {
      "label": label,
      "count": 0,
      "wins": 0,
      "losses": 0,
      "win_rate": 0,
      "avg_profit_pct": 0,
      "total_return_pct": 0,
    }

  profit_values = [float(entry.get("profit_pct", 0) or 0) for entry in entries if entry.get("profit_pct") is not None]
  wins = sum(1 for entry in entries if entry.get("status") in {"TP1", "TP2", "TP3"})
  losses = sum(1 for entry in entries if entry.get("status") == "SL")
  return {
    "label": label,
    "count": len(entries),
    "wins": wins,
    "losses": losses,
    "win_rate": round(wins / max(1, len(entries)) * 100, 1),
    "avg_profit_pct": round(sum(profit_values) / max(1, len(profit_values)), 2) if profit_values else 0,
    "total_return_pct": round(sum(profit_values), 2) if profit_values else 0,
  }


def _summarize_seasonality(entries: list[dict]):
  session_buckets = {
    "Asia": [],
    "London": [],
    "NewYork": [],
    "London/NY Overlap": [],
  }
  weekday_buckets = {i: [] for i in range(7)}
  month_buckets = {i: [] for i in range(1, 13)}

  for entry in entries:
    timestamp = _history_timestamp(entry)
    if timestamp is None:
      continue
    hour = timestamp.hour

    if 0 <= hour <= 8:
      session_buckets["Asia"].append(entry)
    if 7 <= hour <= 16:
      session_buckets["London"].append(entry)
    if 12 <= hour <= 21:
      session_buckets["NewYork"].append(entry)
    if 12 <= hour <= 16:
      session_buckets["London/NY Overlap"].append(entry)

    weekday_buckets[timestamp.weekday()].append(entry)
    month_buckets[timestamp.month].append(entry)

  weekday_names = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
  month_names = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

  return {
    "session": [_season_bucket(values, label) for label, values in session_buckets.items()],
    "weekday": [_season_bucket(weekday_buckets[idx], weekday_names[idx]) for idx in range(7)],
    "month": [_season_bucket(month_buckets[idx + 1], month_names[idx]) for idx in range(12)],
  }


def _normalize_price_frame(symbol: str):
  symbol = symbol.upper()
  frame = fetch_real_data(symbol, period="90d", interval="1h")
  if frame.empty:
    frame = generate_synthetic_data(symbol, n=720)
  return frame


def _frame_timestamp_value(frame, index: int):
  if "datetime" in getattr(frame, "columns", []):
    value = frame["datetime"].iloc[index]
  else:
    value = frame.index[index]
  if hasattr(value, "to_pydatetime"):
    value = value.to_pydatetime()
  if isinstance(value, str):
    try:
      value = datetime.fromisoformat(value)
    except ValueError:
      return None
  if value.tzinfo is None:
    value = value.replace(tzinfo=timezone.utc)
  return value.astimezone(timezone.utc)


def _price_at_timestamp(frame, timestamp: datetime):
  if frame is None or getattr(frame, "empty", True):
    return None
  target = timestamp.astimezone(timezone.utc) if timestamp.tzinfo else timestamp.replace(tzinfo=timezone.utc)
  nearest_index = None
  nearest_delta = None
  for idx in range(len(frame)):
    current = _frame_timestamp_value(frame, idx)
    if current is None:
      continue
    delta = abs((current - target).total_seconds())
    if nearest_delta is None or delta < nearest_delta:
      nearest_delta = delta
      nearest_index = idx
  if nearest_index is None:
    return None
  try:
    return float(frame["close"].iloc[nearest_index])
  except Exception:
    return None


def _latest_close(frame):
  if frame is None or getattr(frame, "empty", True):
    return None
  try:
    return float(frame["close"].iloc[-1])
  except Exception:
    return None


def _frame_index_at_timestamp(frame, timestamp: datetime):
  """Index of the bar nearest the given timestamp, used as the entry bar."""
  if frame is None or getattr(frame, "empty", True):
    return None
  target = timestamp.astimezone(timezone.utc) if timestamp.tzinfo else timestamp.replace(tzinfo=timezone.utc)
  nearest_index = None
  nearest_delta = None
  for idx in range(len(frame)):
    current = _frame_timestamp_value(frame, idx)
    if current is None:
      continue
    delta = abs((current - target).total_seconds())
    if nearest_delta is None or delta < nearest_delta:
      nearest_delta = delta
      nearest_index = idx
  return nearest_index


def _signal_trade_levels(signal: dict, frame, entry_index: int, entry_price: float):
  """Resolve entry direction, stop and target for a recorded signal.

  Signals recorded after this change persist their plan levels. Older records
  predate that, so their levels are reconstructed from average bar range at the
  entry bar using the same 1.2x stop / 2.4x target geometry build_live_plan uses.
  """
  side = str(signal.get("signal", "")).upper()
  direction = 1 if side == "BUY" else -1
  stop = signal.get("stop_loss")
  target = signal.get("take_profit_1")
  if stop is not None and target is not None:
    try:
      return direction, float(stop), float(target)
    except (TypeError, ValueError):
      pass
  atr = None
  try:
    window = frame.iloc[max(0, entry_index - 14):entry_index + 1]
    spread = float((window["high"] - window["low"]).mean())
    atr = spread if spread == spread and spread > 0 else None
  except Exception:
    atr = None
  if not atr:
    atr = max(0.5, abs(entry_price) * 0.004)
  return direction, entry_price - direction * atr * 1.2, entry_price + direction * atr * 2.4


def evaluate_signal_outcome(signal: dict, frame=None):
  """Resolve a recorded signal into a real WIN / LOSS / OPEN result.

  The result is path dependent: bars after the signal are walked in order and
  whichever of the stop or the target is touched first decides the trade. A
  signal with neither level touched stays undecided and carries only an
  unrealized mark, so open trades are never counted as wins or as losses.
  """
  symbol = str(signal.get("symbol", "")).upper()
  timestamp = _history_timestamp(signal)
  if not symbol or timestamp is None:
    return None
  # A HOLD never opened a position, so it has no outcome to settle.
  if not _is_tradeable_side(signal.get("signal")):
    return None
  if frame is None:
    frame = _normalize_price_frame(symbol)
  entry_index = _frame_index_at_timestamp(frame, timestamp)
  if entry_index is None:
    return None
  try:
    entry_price = float(frame["close"].iloc[entry_index])
  except Exception:
    return None
  if entry_price <= 0:
    return None

  direction, stop, target = _signal_trade_levels(signal, frame, entry_index, entry_price)
  status = "none"
  exit_price = None
  exit_index = len(frame) - 1
  for idx in range(entry_index + 1, len(frame)):
    try:
      high = float(frame["high"].iloc[idx])
      low = float(frame["low"].iloc[idx])
    except Exception:
      continue
    hit_stop = low <= stop if direction == 1 else high >= stop
    hit_target = high >= target if direction == 1 else low <= target
    if hit_stop:
      # Stop resolves first when a single bar spans both levels.
      status, exit_price, exit_index = "SL", stop, idx
      break
    if hit_target:
      status, exit_price, exit_index = "TP1", target, idx
      break
  if exit_price is None:
    exit_price = _latest_close(frame) or entry_price

  profit_pct = round(((exit_price - entry_price) / entry_price) * 100 * direction, 2)
  exit_time = _frame_timestamp_value(frame, exit_index)
  return {
    "symbol": symbol,
    "entry_time": signal.get("generated_at") or timestamp.strftime("%Y-%m-%d %H:%M:%S"),
    "entry_price": round(entry_price, 4),
    "stop_loss": round(stop, 4),
    "take_profit": round(target, 4),
    "status": status,
    "profit_pct": profit_pct,
    "resolved": status in {"TP1", "SL"},
    "exit_time": exit_time.strftime("%Y-%m-%d %H:%M:%S") if exit_time else None,
  }


# Thresholds live in src/signal_engine.py (config "live"); these names stay for existing callers.
SIGNAL_BUY_THRESHOLD = ENGINE_SIGNAL_CONFIGS["live"]["buy_threshold"]
SIGNAL_SELL_THRESHOLD = ENGINE_SIGNAL_CONFIGS["live"]["sell_threshold"]


def _classify_signal(probability: float) -> str:
  """Map an ensemble probability to BUY / SELL / HOLD.

  The band between the two thresholds is genuine uncertainty: the model has no
  directional edge there, so it must not be reported as a tradeable side.
  Thin wrapper over src.signal_engine.classify_probability (live config), the rule the backtests use too.
  """
  return engine_classify_probability(probability, "live")


def _is_tradeable_side(side: str) -> bool:
  return str(side or "").upper() in {"BUY", "SELL"}


def _is_legacy_misclassified(signal: dict) -> bool:
  """True for rows the old "BUY if >= 0.55 else SELL" rule mislabelled.

  Their stored side is directional but their own ensemble probability sits in
  the HOLD band, so they were never real trade signals. History, Analytics and
  the performance summary all use this one check so they agree.
  """
  if not isinstance(signal, dict):
    return False
  side = str(signal.get("signal") or "").upper()
  probability = signal.get("ensemble_probability")
  if side not in {"BUY", "SELL"} or probability is None:
    return False
  return _classify_signal(probability) != side


def _safe_signal_evaluation(signal: dict):
  """evaluate_signal_outcome guarded for render paths that must never fail."""
  try:
    return evaluate_signal_outcome(signal)
  except Exception:
    return None


def _build_signal_performance_results():
  signals = load_signals()
  if not signals:
    return []
  price_frames: dict[str, object] = {}
  results = []
  for signal in signals:
    symbol = str(signal.get("symbol", "")).upper()
    if not symbol:
      continue
    # Mislabelled legacy rows were never trades; counting them produced the
    # "yearly 8 wins / 2 losses" shown on the Dashboard.
    if _is_legacy_misclassified(signal):
      continue
    frame = price_frames.get(symbol)
    if frame is None:
      frame = _normalize_price_frame(symbol)
      price_frames[symbol] = frame
    result = evaluate_signal_outcome(signal, frame)
    if result is not None:
      results.append(result)
  return results


def build_performance_summary():
  signal_results = _build_signal_performance_results()
  if signal_results:
    sim_results = signal_results
    source = "recorded signals"
  else:
    sim_results = []
    for symbol in ["XAUUSD", "BTCUSD"]:
      summary = build_shadow_simulation(symbol, entries=12, horizon=24)
      sim_results.extend(summary.get("results", []))
    # Say so when the numbers are simulated rather than recorded signal outcomes.
    source = "shadow simulation (no recorded directional signals yet)"
  windows = {
    "hours": 1,
    "daily": 24,
    "weekly": 24 * 7,
    "monthly": 24 * 30,
    "yearly": 24 * 365,
  }
  summary = {}
  for label, hours in windows.items():
    summary[label] = _summarize_performance(sim_results, hours)
  summary["seasonality"] = _summarize_seasonality(sim_results)
  summary["source"] = source
  summary["legacy_rows_excluded"] = True
  summary["generated_at"] = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
  save_cached_performance_summary(summary)
  return summary


PERFORMANCE_SUMMARY_MAX_AGE_SECONDS = 900


def _performance_summary_age_seconds(summary: dict) -> float:
  try:
    generated = datetime.strptime(str(summary.get("generated_at")), "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    return (datetime.now(timezone.utc) - generated).total_seconds()
  except (TypeError, ValueError):
    return float("inf")


_performance_summary_cache = {"value": None, "ready": False, "warming": False}


def warm_performance_summary_cache():
  if _performance_summary_cache["warming"]:
    return
  _performance_summary_cache["warming"] = True

  def _worker():
    try:
      _performance_summary_cache["value"] = build_performance_summary()
      _performance_summary_cache["ready"] = True
    finally:
      _performance_summary_cache["warming"] = False

  threading.Thread(target=_worker, daemon=True).start()


def get_performance_summary_fast():
  cached = _performance_summary_cache["value"] or load_cached_performance_summary()
  # Summaries written before legacy rows were excluded counted ten mislabelled
  # June rows as trades (the "8 wins / 2 losses"); never serve those again.
  if cached is not None and ("seasonality" not in cached or not cached.get("legacy_rows_excluded")):
    cached = None
  if cached is not None:
    _performance_summary_cache["value"] = cached
    _performance_summary_cache["ready"] = True
    # The cache used to live forever once written. Serve it, and refresh it in
    # the background when it is older than the limit.
    if _performance_summary_age_seconds(cached) > PERFORMANCE_SUMMARY_MAX_AGE_SECONDS:
      warm_performance_summary_cache()
    return cached
  summary = build_performance_summary()
  _performance_summary_cache["value"] = summary
  _performance_summary_cache["ready"] = True
  return summary


def get_model_status(symbol: str):
    metrics = load_metrics(symbol) or {}
    lstm_metrics = load_lstm_metrics(symbol) or {}
    history = load_daily_history(symbol)
    # Runs flagged test_polluted in learning_decisions.json (tests trained into the live models/, 15-16 Sep 2026) did
    # not produce the model that is loaded, so "last trained" must skip them instead of showing a test run's time.
    try:
        decisions = json.loads((DATA_DIR / "learning_decisions.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        decisions = []
    polluted_times = {row.get("trained_at") for row in decisions if isinstance(row, dict) and row.get("test_polluted")} \
        if isinstance(decisions, list) else set()
    history = [row for row in history if isinstance(row, dict) and row.get("trained_at") not in polluted_times]
    last_entry = history[-1] if history else {}
    return {
        'symbol': symbol,
        'model_loaded': bool(metrics),
        'accuracy': metrics.get('accuracy'),
        'classification_report': metrics.get('classification_report'),
        'lstm_accuracy': lstm_metrics.get('accuracy'),
        'lstm_loss': lstm_metrics.get('loss'),
        'lstm_precision': lstm_metrics.get('precision'),
        'lstm_recall': lstm_metrics.get('recall'),
        'lstm_f1_score': lstm_metrics.get('f1_score'),
        'lstm_last_trained_at': lstm_metrics.get('trained_at'),
        'rf_precision': metrics.get('precision'),
        'rf_recall': metrics.get('recall'),
        'rf_f1': metrics.get('f1'),
        'rf_roc_auc': metrics.get('roc_auc'),
        'rf_brier_score': metrics.get('brier_score'),
        'rf_ece_10': metrics.get('ece_10'),
        'rf_calibration_enabled': metrics.get('calibration_enabled'),
        'rf_calibration_method': metrics.get('calibration_method'),
        'cv_accuracy_mean': metrics.get('cv_accuracy_mean'),
        'cv_accuracy_std': metrics.get('cv_accuracy_std'),
        'cv_gap': metrics.get('cv_gap'),
        'last_trained_at': last_entry.get('trained_at'),
        'last_status': last_entry.get('status'),
        'rows': last_entry.get('rows'),
    }


def compute_strategy_quality(symbol: str, current_signal: str | None = None, accuracy: float | None = None):
    if current_signal is None:
        current_signal = get_internal_signal_map().get(symbol)
    # Dashboard test alerts never count towards the grade.
    alerts = [alert for alert in load_tradingview_alerts() if alert.get('symbol') == symbol and alert.get('source') != 'dashboard-test']
    if alerts:
        aligned = sum(1 for alert in alerts if alert.get('side') == current_signal)
        alignment_ratio = aligned / len(alerts)
    else:
        alignment_ratio = 0.5
    if accuracy is None:
        accuracy = load_metrics(symbol).get('accuracy') if load_metrics(symbol) else 0.5
    score = round((accuracy * 0.6) + (alignment_ratio * 0.4), 2)
    if score >= 0.8:
        grade = 'A'
    elif score >= 0.7:
        grade = 'B'
    elif score >= 0.6:
        grade = 'C'
    else:
        grade = 'D'
    return {
        'alignment_ratio': round(alignment_ratio, 2),
        'score': score,
        'grade': grade,
        'alert_count': len(alerts),
    }


def normalize_symbol(value: str) -> str:
    if not value:
        return ""
    value = value.upper()
    if value in ["GC=F"]:
        return "XAUUSD"
    if value in ["BTC-USD"]:
        return "BTCUSD"
    return value.replace("-USD", "USD").replace("=X", "")


def parse_tradingview_alert(payload: dict):
    text = str(payload.get("message") or payload.get("alert") or payload.get("text") or payload)
    symbol = normalize_symbol(str(payload.get("symbol") or payload.get("ticker") or ""))
    if not symbol:
        found = re.search(r"\b(XAUUSD|BTCUSD|BTC-USD|GC=F|BTCUSD=X|XAUUSD=X)\b", text, re.IGNORECASE)
        if found:
            symbol = normalize_symbol(found.group(1))

    side = str(payload.get("side") or payload.get("action") or "").upper().strip()
    side = {"LONG": "BUY", "SHORT": "SELL"}.get(side, side)
    if side not in {"BUY", "SELL"}:
        # A missing or unreadable side used to default to BUY, so a malformed alert read as a long.
        says_buy = re.search(r"\b(BUY|LONG)\b", text, re.I)
        says_sell = re.search(r"\b(SELL|SHORT)\b", text, re.I)
        side = "BUY" if says_buy and not says_sell else "SELL" if says_sell and not says_buy else "UNKNOWN"

    def parse_number(patterns):
        for pattern in patterns:
            match = re.search(pattern, text, re.IGNORECASE)
            if match:
                try:
                    return float(match.group(1))
                except ValueError:
                    continue
        return None

    entry = payload.get("entry") or payload.get("price") or parse_number([r"entry[:\s]*([0-9]+\.?[0-9]*)", r"trigger[:\s]*([0-9]+\.?[0-9]*)"])
    sl = payload.get("stop_loss") or payload.get("sl") or parse_number([r"stop[_\s]*loss[:\s]*([0-9]+\.?[0-9]*)", r"sl[:\s]*([0-9]+\.?[0-9]*)"])
    tp1 = payload.get("tp1") or payload.get("take_profit_1") or parse_number([r"tp1[:\s]*([0-9]+\.?[0-9]*)", r"take[_\s]*profit\s*1[:\s]*([0-9]+\.?[0-9]*)"])
    tp2 = payload.get("tp2") or payload.get("take_profit_2") or parse_number([r"tp2[:\s]*([0-9]+\.?[0-9]*)", r"take[_\s]*profit\s*2[:\s]*([0-9]+\.?[0-9]*)"])
    tp3 = payload.get("tp3") or payload.get("take_profit_3") or parse_number([r"tp3[:\s]*([0-9]+\.?[0-9]*)", r"take[_\s]*profit\s*3[:\s]*([0-9]+\.?[0-9]*)"])
    tp = payload.get("take_profit") or payload.get("tp") or parse_number([r"take[_\s]*profit[:\s]*([0-9]+\.?[0-9]*)", r"tp[:\s]*([0-9]+\.?[0-9]*)"])

    return {
        "symbol": symbol,
        "side": side,
        "entry": float(entry) if entry is not None else None,
        "stop_loss": float(sl) if sl is not None else None,
        "take_profit": float(tp) if tp is not None else None,
        "take_profit_1": float(tp1) if tp1 is not None else None,
        "take_profit_2": float(tp2) if tp2 is not None else None,
        "take_profit_3": float(tp3) if tp3 is not None else None,
        "confidence": float(payload.get("confidence") or payload.get("strength") or 0.7),
        "source": payload.get("source", "tradingview"),
        "text": text,
        "received_at": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S"),
    }


def cast_number(value):
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def get_internal_signal_map():
    signals = build_signal_payload()
    return {item['symbol']: item['signal'] for item in signals}


def build_tradingview_plan(alert: dict, internal_signals: dict | None = None):
    plan = alert.copy()
    entry = cast_number(plan.get('entry'))
    sl = cast_number(plan.get('stop_loss'))
    tp = cast_number(plan.get('take_profit'))
    tp1 = cast_number(plan.get('take_profit_1'))
    tp2 = cast_number(plan.get('take_profit_2'))
    tp3 = cast_number(plan.get('take_profit_3'))
    primary_tp = tp1 or tp or tp2 or tp3
    rr = None
    if entry is not None and sl is not None and primary_tp is not None and entry != sl:
        if plan.get('side') == 'BUY':
            rr = (primary_tp - entry) / (entry - sl)
        else:
            rr = (entry - primary_tp) / (sl - entry)
    if plan.get('side') not in ('BUY', 'SELL'):
        rr = None
    plan['risk_reward'] = round(rr, 2) if rr is not None else None
    if rr is None:
        plan['grade'] = 'No side' if plan.get('side') not in ('BUY', 'SELL') else 'Incomplete'
    elif rr >= 3.0:
        plan['grade'] = 'A'
    elif rr >= 2.0:
        plan['grade'] = 'B'
    elif rr >= 1.5:
        plan['grade'] = 'C'
    else:
        plan['grade'] = 'D'
    internal_side = internal_signals.get(plan.get('symbol')) if internal_signals else None
    if plan.get('side') not in ('BUY', 'SELL'):
        # An alert with no tradable side did not disagree with the model: there was nothing to compare. Calling that
        # "Divergent" reads as a verdict the evidence does not support.
        plan['alignment'] = 'No side to compare'
        plan['notes'] = f"The alert carried no BUY or SELL side." + (f" System bias: {internal_side}." if internal_side else '')
    elif internal_side:
        plan['alignment'] = 'Aligned' if internal_side == plan.get('side') else 'Divergent'
        plan['notes'] = f"System bias: {internal_side}."
    else:
        plan['alignment'] = 'Unknown'
        plan['notes'] = 'No internal signal available.'
    plan['confidence'] = round(min(1.0, max(0.0, float(plan.get('confidence') or 0.7))), 2)
    return plan


