YAHOO_TICKERS = {
    "XAUUSD": ["GC=F"],
    "BTCUSD": ["BTC-USD"],
}


def fetch_broker_quote(symbol: str):
  """Live mid price from the MT4 DWX-ZeroMQ bridge, else MT5.

  The broker feed is preferred over Yahoo because it prices the instrument the
  account actually trades. Yahoo proxies XAUUSD with the GC=F gold future,
  which carries a basis against broker spot, so entries and stops derived from
  it do not line up with fills. Returns None when no bridge is connected.
  """
  symbol = symbol.upper()
  for engine, label in ((MT4_ENGINE, 'mt4-bridge'), (MT5_ENGINE, 'mt5-bridge')):
    try:
      if not bool(engine.status().get('connected')):
        continue
      quote = engine.check_symbol(symbol)
      bid = quote.get('bid')
      ask = quote.get('ask')
      if bid is None or ask is None:
        continue
      mid = (float(bid) + float(ask)) / 2.0
      if mid <= 0:
        continue
      return round(mid, 4), label
    except Exception:
      continue
  return None, None


def fetch_yahoo_quote(symbol: str):
  symbol = symbol.upper()
  cache_key = f"quote:{symbol}"
  cached = _market_get_cached_quote(symbol)

  # Broker price wins when a terminal bridge is live.
  broker_price, broker_label = fetch_broker_quote(symbol)
  if broker_price is not None:
    previous = (cached or {}).get('price')
    change = round(((broker_price - previous) / previous * 100), 2) if previous else 0.0
    _market_set_cached_quote(symbol, broker_price, change)
    _market_record_success(cache_key)
    _market_set_quote_source(symbol, broker_label)
    return broker_price, change

  if _market_circuit_open(cache_key):
    if cached:
      _market_set_quote_source(symbol, 'cached-circuit-open')
      return cached.get('price'), cached.get('change_pct')
    _market_set_quote_source(symbol, 'unavailable-circuit-open')
    return None, None

  tickers = YAHOO_TICKERS.get(symbol, [symbol])
  last_reason = None
  for ticker in tickers:
    try:
      ticker_obj = yf.Ticker(ticker)
      history = ticker_obj.history(period="1d", interval="1m")
      if history is None or history.empty:
        continue
      clean_close = history['Close'].dropna()
      if clean_close.empty:
        continue

      last_price = clean_close.iloc[-1]
      prev_price = clean_close.iloc[-2] if len(clean_close) > 1 else last_price
      change_pct = ((last_price - prev_price) / prev_price * 100) if prev_price != 0 else 0.0
      price = round(float(last_price), 2)
      change = round(float(change_pct), 2)

      _market_set_cached_quote(symbol, price, change)
      _market_record_success(cache_key)
      _market_set_quote_source(symbol, 'live-yahoo')
      return price, change
    except Exception as exc:
      last_reason = str(exc)
      continue

  _market_record_failure(cache_key, last_reason or 'quote feed unavailable')
  if cached:
    _market_set_quote_source(symbol, 'cached-after-failure')
    return cached.get('price'), cached.get('change_pct')

  _market_set_quote_source(symbol, 'synthetic-fallback')
  return None, None


def fetch_intraday_prices_from_yahoo(symbol: str, interval: str = "5m", period: str = "1d"):
    symbol = symbol.upper()
    tickers = YAHOO_TICKERS.get(symbol, [symbol])
    for ticker in tickers:
        try:
            ticker_obj = yf.Ticker(ticker)
            history = ticker_obj.history(period=period, interval=interval)
            if history is None or history.empty:
                # try a wider window when 1d 5m is unavailable
                history = ticker_obj.history(period="5d", interval="15m")
            if history is None or history.empty:
                history = ticker_obj.history(period="1mo", interval="1d")
            if history is None or history.empty:
                continue
            close = history['Close'].dropna()
            if close.empty:
                continue
            return [round(float(x), 2) for x in close.tolist()]
        except Exception:
            continue
    return []


def fetch_daily_prices_from_yahoo(symbol: str, periods: int = 20):
    values = fetch_intraday_prices_from_yahoo(symbol, interval="1d", period="1mo")
    if values:
        return values[-periods:]
    return []


def build_live_series(symbol: str):
    symbol = symbol.upper()
    values = fetch_intraday_prices_from_yahoo(symbol, interval="5m", period="1d")
    if not values:
        values = fetch_daily_prices_from_yahoo(symbol, periods=20)
    if not values:
        base = 2000.0 if symbol == "XAUUSD" else 50000.0
        values = []
        for i in range(20):
            drift = 0.0008 * (i - 10) + (0.0004 if symbol == "BTCUSD" else 0.0002)
            base *= (1 + drift)
            values.append(round(base, 2))
    return values[-20:]


def build_chart_svg(symbol: str):
    values = build_live_series(symbol)
    width = 600
    height = 160
    max_val = max(values)
    min_val = min(values)
    points = []
    for idx, value in enumerate(values):
        x = 20 + idx * (width - 40) / (len(values) - 1)
        y = height - 20 - ((value - min_val) / max(1, (max_val - min_val))) * (height - 40)
        points.append((x, y))
    polyline = " ".join(f"{x:.1f},{y:.1f}" for x, y in points)
    return f"<svg viewBox='0 0 {width} {height}'><rect width='{width}' height='{height}' fill='transparent'></rect><polyline fill='none' stroke='#7dd3fc' stroke-width='3' points='{polyline}'></polyline></svg>"


def build_chart_insights(symbol: str):
    symbol = symbol.upper()
    values = build_live_series(symbol)
    if not values:
        return {
            'symbol': symbol,
            'error': 'No chart data available',
            'status': 'empty',
        }
    latest = values[-1]
    prior = values[-5] if len(values) >= 5 else values[0]
    momentum = round((latest - values[0]) / values[0] * 100, 2) if values[0] else 0.0
    trend = 'uptrend' if latest > prior else 'downtrend' if latest < prior else 'flat'
    
    support = round(min(values), 2)
    resistance = round(max(values), 2)
    average = round(sum(values) / len(values), 2)
    signals = build_signal_payload()
    current_signal = next((item for item in signals if item['symbol'] == symbol), None)
    return {
        'symbol': symbol,
        'latest_price': latest,
        'trend': trend,
        'momentum_pct': momentum,
        'support': support,
        'resistance': resistance,
        'average': average,
        'signal': current_signal['signal'] if current_signal else 'UNKNOWN',
        'confidence': current_signal['confidence'] if current_signal else None,
        'summary': f"{symbol} is in a {trend} with latest price {latest:.2f}, support ~{support:.2f}, resistance ~{resistance:.2f}.",
    }


def _model_evidence(internal: dict | None) -> dict:
    """The numbers behind a live signal, straight from the enriched record: the blended probability, each model's
    own probability, the thresholds it was compared with, how far it sits from the nearer one, and the age of the bar
    it was computed on. Nothing is rounded into a verdict here - the page shows the same values the engine used."""
    from src.signal_engine import get_config

    config = get_config("live")
    buy, sell = config["buy_threshold"], config["sell_threshold"]
    if not internal:
        return {"available": False, "reason": "no live signal record for this symbol",
                "buy_threshold": buy, "sell_threshold": sell}
    probability = internal.get("ensemble_probability")
    distance = None
    if probability is not None:
        distance = round(min(abs(float(probability) - buy), abs(float(probability) - sell)), 4)
    return {"available": True, "ensemble_probability": probability, "rf_probability": internal.get("rf_probability"),
            "lstm_probability": internal.get("lstm_probability"), "buy_threshold": buy, "sell_threshold": sell,
            "distance_to_nearer_threshold": distance,
            "signal_bar_time": internal.get("signal_bar_time"),
            "signal_bar_age_minutes": internal.get("signal_bar_age_minutes"),
            "model_accuracy": internal.get("model_accuracy"), "lstm_accuracy": internal.get("lstm_accuracy")}


def build_live_plan(symbol: str):
    symbol = symbol.upper()
    signals = build_signal_payload()
    internal = next((item for item in signals if item['symbol'] == symbol), None)
    current_price, _ = fetch_yahoo_quote(symbol)
    if current_price is None:
        series = build_live_series(symbol)
        current_price = float(series[-1]) if series else 0.0
    data = fetch_real_data(symbol, period="30d", interval="1h")
    features = build_features(data) if not data.empty else None
    latest_vol = float(features['volatility_5d'].iloc[-1]) if features is not None and not features.empty else 0.01
    atr = max(0.5, latest_vol * current_price)
    signal = internal['signal'] if internal else 'HOLD'
    entry = round(current_price, 2)
    if not _is_tradeable_side(signal):
      # No directional edge: publish the context without inventing levels,
      # so a neutral reading cannot be shown or executed as a short.
      return {
        'symbol': symbol,
        'signal': 'HOLD',
        'entry': entry,
        'stop_loss': None,
        'take_profit_1': None,
        'take_profit_2': None,
        'take_profit_3': None,
        'confidence': round(float(internal['confidence']), 2) if internal else 0.5,
        'grade': '-',
        'risk_reward': None,
        'chart_range_min': round(float(entry - atr * 3), 4),
        'chart_range_max': round(float(entry + atr * 3), 4),
        'model_bias': internal['bias'] if internal else 'Neutral',
        'reason': internal['reason'] if internal else 'Model probability sits in the neutral band; standing aside.',
        'evidence': _model_evidence(internal),
        'generated_at': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
      }
    direction = 1 if signal == 'BUY' else -1
    sl = round(entry - direction * atr * 1.2, 2)
    tp1 = round(entry + direction * atr * 2.4, 2)
    tp2 = round(entry + direction * atr * 3.6, 2)
    tp3 = round(entry + direction * atr * 4.8, 2)
    rr = None
    if entry and sl and tp1 and entry != sl:
        rr = round((tp1 - entry) / abs(entry - sl), 2) if signal == 'BUY' else round((entry - tp1) / abs(sl - entry), 2)
    grade = 'A' if rr and rr >= 3 else 'B' if rr and rr >= 2 else 'C' if rr and rr >= 1.5 else 'D'
    confidence = internal['confidence'] if internal else 0.65
    if data is not None and not data.empty and 'high' in data.columns and 'low' in data.columns:
      chart_range_max = float(data['high'].tail(500).max())
      chart_range_min = float(data['low'].tail(500).min())
    else:
      chart_range_max = float(max(entry, sl, tp1, tp2, tp3) + atr * 2)
      chart_range_min = float(min(entry, sl, tp1, tp2, tp3) - atr * 2)
    if chart_range_max <= chart_range_min:
      chart_range_max = chart_range_min + max(1.0, abs(entry) * 0.01)

    plan = {
        'symbol': symbol,
        'signal': signal,
        'entry': entry,
        'stop_loss': sl,
        'take_profit_1': tp1,
        'take_profit_2': tp2,
        'take_profit_3': tp3,
        'confidence': round(float(confidence), 2),
        'grade': grade,
        'risk_reward': rr,
        'chart_range_min': round(chart_range_min, 4),
        'chart_range_max': round(chart_range_max, 4),
        'model_bias': internal['bias'] if internal else None,
        'evidence': _model_evidence(internal),
        'reason': internal['reason'] if internal else 'Live model entry plan generated from current signal.',
        'generated_at': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
    }
    return plan


def _jarvis_market_regime(features, data) -> dict:
    if features is None or getattr(features, 'empty', True):
      return {
        'name': 'transition',
        'bias': 'neutral',
        'volatility': 0.0,
        'range_pct_20': 0.0,
        'trend_delta': 0.0,
      }

    latest = features.iloc[-1]
    trend_5 = float(latest.get('trend_5', 0) or 0)
    trend_20 = float(latest.get('trend_20', 0) or 0)
    rsi_14 = float(latest.get('rsi_14', 50) or 50)
    volatility = float(latest.get('volatility_5d', 0) or 0)
    trend_delta = abs(trend_5 - trend_20)

    try:
      hi = float(data['high'].tail(20).max())
      lo = float(data['low'].tail(20).min())
      cl = float(data['close'].iloc[-1])
      range_pct_20 = ((hi - lo) / max(1e-9, abs(cl)))
    except Exception:
      range_pct_20 = 0.0

    if volatility >= 0.03 or range_pct_20 >= 0.05:
      regime = 'high-volatility'
    elif trend_delta >= 0.03 and (rsi_14 >= 55 or rsi_14 <= 45):
      regime = 'trending'
    elif volatility <= 0.008 and trend_delta <= 0.01:
      regime = 'low-volatility-range'
    elif range_pct_20 >= 0.025 and trend_delta <= 0.015:
      regime = 'ranging'
    else:
      regime = 'transition'

    if trend_5 > trend_20:
      bias = 'bullish'
    elif trend_5 < trend_20:
      bias = 'bearish'
    else:
      bias = 'neutral'

    return {
      'name': regime,
      'bias': bias,
      'volatility': round(volatility, 4),
      'range_pct_20': round(range_pct_20, 4),
      'trend_delta': round(trend_delta, 4),
    }


def _jarvis_multi_timeframe_confluence(symbol: str) -> dict:
    tf_profiles = {
      '15m': {'interval': '15m', 'period': '10d', 'weight': 0.25},
      '1h': {'interval': '1h', 'period': '30d', 'weight': 0.35},
      '4h': {'interval': '4h', 'period': '90d', 'weight': 0.40},
    }
    snapshots = {}
    bull = 0.0
    bear = 0.0
    strength_sum = 0.0

    for tf, cfg in tf_profiles.items():
      frame = fetch_real_data(symbol, period=cfg['period'], interval=cfg['interval'])
      if frame is None or frame.empty:
        frame = generate_synthetic_data(symbol, n=300)
      features = build_features(frame)
      if features is None or features.empty:
        snapshots[tf] = {'trend': 'neutral', 'rsi': 50.0, 'volatility': 0.0, 'signal': 'HOLD'}
        continue

      latest = features.iloc[-1]
      t5 = float(latest.get('trend_5', 0) or 0)
      t20 = float(latest.get('trend_20', 0) or 0)
      rsi = float(latest.get('rsi_14', 50) or 50)
      vol = float(latest.get('volatility_5d', 0) or 0)
      spread = abs(t5 - t20)

      if t5 > t20:
        trend = 'bullish'
        bull += cfg['weight']
      elif t5 < t20:
        trend = 'bearish'
        bear += cfg['weight']
      else:
        trend = 'neutral'
        bull += cfg['weight'] * 0.5
        bear += cfg['weight'] * 0.5

      strength_sum += min(1.0, spread * 12.0) * cfg['weight']
      snapshots[tf] = {
        'trend': trend,
        'rsi': round(rsi, 1),
        'volatility': round(vol * 100, 2),
        'signal': 'BUY' if trend == 'bullish' else 'SELL' if trend == 'bearish' else 'HOLD',
      }

    gap = abs(bull - bear)
    dominant = max(bull, bear)
    score = 45.0 + (dominant * 35.0) + (gap * 20.0) + (strength_sum * 10.0)
    score = round(max(0.0, min(100.0, score)), 1)

    if bull > bear + 0.08:
      signal = 'BUY'
      alignment = 'bullish-aligned'
    elif bear > bull + 0.08:
      signal = 'SELL'
      alignment = 'bearish-aligned'
    else:
      signal = 'HOLD'
      alignment = 'mixed'

    return {
      'score': score,
      'alignment': alignment,
      'signal': signal,
      'quality': 'high' if score >= 75 else 'medium' if score >= 60 else 'low',
      'timeframes': snapshots,
    }


def _jarvis_probabilistic_outlook(plan: dict, confluence: dict, regime: dict) -> dict:
    base_conf = float(plan.get('confidence') or 0.55)
    rr = float(plan.get('risk_reward') or 1.0)
    conf_score = float(confluence.get('score') or 50.0) / 100.0
    regime_name = str(regime.get('name') or 'transition')

    regime_shift = {
      'trending': 0.06,
      'ranging': -0.03,
      'high-volatility': -0.06,
      'low-volatility-range': -0.02,
      'transition': 0.0,
    }.get(regime_name, 0.0)

    tp1_prob = 0.35 + (base_conf * 0.35) + (conf_score * 0.25) + ((rr - 1.0) * 0.08) + regime_shift
    tp1_prob = max(0.1, min(0.95, tp1_prob))

    sl_prob = (1.0 - tp1_prob) + (0.08 if regime_name == 'high-volatility' else 0.0)
    sl_prob = max(0.05, min(0.9, sl_prob))

    expected_value_r = round((tp1_prob * rr) - ((1.0 - tp1_prob) * 1.0), 2)
    confidence_band = 'high' if tp1_prob >= 0.7 else 'medium' if tp1_prob >= 0.55 else 'low'

    return {
      'tp1_hit_probability': round(tp1_prob, 3),
      'stop_loss_probability': round(sl_prob, 3),
      'expected_value_r': expected_value_r,
      'confidence_band': confidence_band,
    }


def _jarvis_confidence_calibration(symbol: str, timeframe: str, base_confidence: float) -> dict:
    results = [r for r in _build_signal_performance_results() if str(r.get('symbol') or '').upper() == str(symbol or '').upper()]
    sample = len(results)
    wins = sum(1 for item in results if str(item.get('status') or '').upper() in {'TP1', 'TP2', 'TP3'})
    losses = sum(1 for item in results if str(item.get('status') or '').upper() == 'SL')
    win_rate = (wins / max(1, wins + losses)) if (wins + losses) > 0 else 0.5

    trust = min(1.0, sample / 30.0)
    edge = (win_rate - 0.5)
    tf_weight = {'15m': 0.85, '1h': 1.0, '4h': 1.08, '1d': 1.12}.get(str(timeframe or '1h').lower(), 1.0)
    adjustment = edge * 0.35 * trust * tf_weight

    calibrated = max(0.35, min(0.95, float(base_confidence or 0.55) + adjustment))
    return {
      'base_confidence': round(float(base_confidence or 0.55), 3),
      'calibrated_confidence': round(calibrated, 3),
      'sample_size': sample,
      'historical_win_rate': round(win_rate, 3),
      'trust': round(trust, 3),
      'adjustment': round(adjustment, 3),
    }


def _jarvis_event_risk_gate(data, features, timeframe: str, confluence: dict, regime: dict) -> dict:
    risk_score = 0.0
    notes = []

    try:
      ranges = ((data['high'] - data['low']) / data['close'].replace(0, np.nan)).dropna().tail(24)
      recent = float(ranges.iloc[-1]) if not ranges.empty else 0.0
      avg_rng = float(ranges.mean()) if not ranges.empty else 0.0
      if avg_rng > 0 and recent >= (avg_rng * 1.8):
        risk_score += 0.35
        notes.append('range shock detected')
    except Exception:
      pass

    try:
      if 'volume' in data.columns:
        vols = data['volume'].dropna().tail(24)
        last_vol = float(vols.iloc[-1]) if not vols.empty else 0.0
        avg_vol = float(vols.mean()) if not vols.empty else 0.0
        if avg_vol > 0 and last_vol >= (avg_vol * 2.0):
          risk_score += 0.20
          notes.append('volume spike detected')
    except Exception:
      pass

    now_utc = datetime.now(timezone.utc)
    minute = now_utc.minute
    tf = str(timeframe or '1h').lower()
    if tf in {'15m', '1h'} and minute in {0, 30}:
      risk_score += 0.15
      notes.append('potential event window around clock boundary')

    if str(regime.get('name') or '') == 'high-volatility':
      risk_score += 0.20
      notes.append('high-volatility regime')

    confluence_score = float(confluence.get('score') or 50.0)
    if confluence_score < 60:
      risk_score += 0.10
      notes.append('weak confluence')

    risk_score = max(0.0, min(1.0, risk_score))
    if risk_score >= 0.70:
      level = 'high'
    elif risk_score >= 0.45:
      level = 'medium'
    else:
      level = 'low'

    allow_trade = True
    return {
      'risk_score': round(risk_score, 3),
      'risk_level': level,
      'allow_trade': allow_trade,
      'gate_action': 'open',
      'risk_multiplier': 1.0,
      'learning_mode_active': True,
      'learning_capture': True,
      'notes': notes,
    }


def _jarvis_entry_zone_and_invalidation(plan: dict, timeframe: str, regime: dict) -> dict:
    entry = cast_number(plan.get('entry'))
    sl = cast_number(plan.get('stop_loss'))
    signal = str(plan.get('signal') or 'BUY').upper()
    if entry is None or sl is None:
      return {
        'entry_zone': {'low': None, 'high': None},
        'invalidation_band': {'low': None, 'high': None},
      }

    risk_dist = abs(entry - sl)
    tf = str(timeframe or '1h').lower()
    zone_mul = {'15m': 0.28, '1h': 0.34, '4h': 0.42, '1d': 0.55}.get(tf, 0.34)
    if str(regime.get('name') or '') == 'high-volatility':
      zone_mul *= 1.25
    zone_half = max(0.01, risk_dist * zone_mul)

    entry_zone = {
      'low': round(entry - zone_half, 4),
      'high': round(entry + zone_half, 4),
    }

    band_half = max(0.01, risk_dist * 0.18)
    invalidation_band = {
      'low': round(sl - band_half, 4),
      'high': round(sl + band_half, 4),
    }

    return {
      'signal': signal,
      'entry_zone': entry_zone,
      'invalidation_band': invalidation_band,
      'zone_width': round(zone_half * 2.0, 4),
      'stop_distance': round(risk_dist, 4),
    }


def build_screenshot_entry_explanation(symbol: str, notes: str = ""):
    symbol = symbol.upper()
    plan = build_live_plan(symbol)
    insights = build_chart_insights(symbol)
    direction = "long" if plan.get("signal") == "BUY" else "short"

    setup_lines = [
      f"Symbol: {symbol}",
      f"Signal: {plan.get('signal')} ({direction})",
      f"Entry: {plan.get('entry')}",
      f"Stop Loss: {plan.get('stop_loss')}",
      f"Take Profit 1: {plan.get('take_profit_1')}",
      f"Take Profit 2: {plan.get('take_profit_2')}",
      f"Take Profit 3: {plan.get('take_profit_3')}",
      f"Risk/Reward: {plan.get('risk_reward')}",
      f"Model confidence: {plan.get('confidence')}",
      f"Chart trend: {insights.get('trend')}",
      f"Momentum: {insights.get('momentum_pct')}%",
      f"Support/Resistance: {insights.get('support')} / {insights.get('resistance')}",
    ]

    rationale_lines = [
      f"Model rationale: {plan.get('reason')}",
      f"Context summary: {insights.get('summary')}",
      "Execution logic: enter near entry level, invalidate at stop-loss, and scale out at TP1/TP2/TP3.",
    ]

    if notes:
      rationale_lines.append(f"Operator screenshot notes: {notes}")

    full_text = "\n".join(setup_lines + [""] + rationale_lines)
    return {
      "symbol": symbol,
      "plan": plan,
      "insights": insights,
      "setup_lines": setup_lines,
      "rationale_lines": rationale_lines,
      "full_text": full_text,
    }


def build_powerful_strategy_analysis(symbol: str, screenshot_notes: str = "", ocr_text: str = "", parsed_levels: dict | None = None):
    symbol = symbol.upper()
    plan = build_live_plan(symbol)
    insights = build_chart_insights(symbol)
    data = fetch_real_data(symbol, period="30d", interval="1h")
    if data.empty:
      data = generate_synthetic_data(symbol, n=500)
    features = build_features(data)

    latest_row = features.iloc[-1] if not features.empty else None
    volatility = float(latest_row.get("volatility_5d", 0) or 0.0) if latest_row is not None else 0.0
    trend_strength = 0.0
    if latest_row is not None:
      trend_5 = float(latest_row.get("trend_5", 0) or 0)
      trend_20 = float(latest_row.get("trend_20", 0) or 0)
      trend_strength = abs(trend_5 - trend_20)

    ocr_levels = parsed_levels or {}
    level_bonus = 0.0
    if ocr_levels:
      level_bonus += 0.05
    if ocr_levels.get("entry") is not None:
      level_bonus += 0.05
    if ocr_levels.get("sl") is not None:
      level_bonus += 0.03
    if ocr_levels.get("tp1") is not None:
      level_bonus += 0.03

    note_bonus = 0.0
    if screenshot_notes:
      note_bonus = min(0.05, len(screenshot_notes.strip()) / 1200)
    ocr_bonus = 0.0
    if ocr_text:
      ocr_bonus = min(0.05, len(ocr_text.strip()) / 1800)

    base_confidence = float(plan.get("confidence", 0.55) or 0.55)
    combined_confidence = round(min(0.99, max(0.5, base_confidence + level_bonus + note_bonus + ocr_bonus + min(0.05, trend_strength * 0.02))), 2)

    if parsed_levels and parsed_levels.get("entry") is not None:
      entry = round(float(parsed_levels["entry"]), 2)
    else:
      entry = float(plan.get("entry") or 0.0)

    if parsed_levels and parsed_levels.get("sl") is not None:
      stop_loss = round(float(parsed_levels["sl"]), 2)
    else:
      stop_loss = float(plan.get("stop_loss") or 0.0)

    tp1 = round(float(parsed_levels.get("tp1", plan.get("take_profit_1")) or plan.get("take_profit_1") or 0.0), 2)
    tp2 = round(float(parsed_levels.get("tp2", plan.get("take_profit_2")) or plan.get("take_profit_2") or 0.0), 2)
    tp3 = round(float(parsed_levels.get("tp3", plan.get("take_profit_3")) or plan.get("take_profit_3") or 0.0), 2)

    if entry and stop_loss and tp1 and entry != stop_loss:
      if plan.get("signal") == "BUY":
        rr = round((tp1 - entry) / abs(entry - stop_loss), 2)
      else:
        rr = round((entry - tp1) / abs(stop_loss - entry), 2)
    else:
      rr = plan.get("risk_reward")

    target_pip_min = int(plan.get("target_pip_min", 30) or 30)
    target_pip_max = int(plan.get("target_pip_max", 2000) or 2000)
    expected_move_pips = float(plan.get("expected_move_pips", 0) or 0)
    quality_in_range = bool(plan.get("quality_in_range", True))
    if ocr_levels:
      quality_in_range = quality_in_range and bool(entry) and bool(stop_loss)

    strategy_score = round(min(0.99, max(0.0, (
      float(plan.get("strategy_score", 0.58) or 0.58) * 0.5 +
      min(1.0, trend_strength * 0.1) * 0.2 +
      level_bonus * 0.15 +
      note_bonus * 0.05 +
      ocr_bonus * 0.05 +
      (0.05 if quality_in_range else -0.03)
    ))), 2)

    if strategy_score >= 0.8:
      strategy_grade = "A"
    elif strategy_score >= 0.68:
      strategy_grade = "B"
    elif strategy_score >= 0.55:
      strategy_grade = "C"
    else:
      strategy_grade = "D"

    if strategy_score >= 0.7:
      strategy_rank = "Top"
    elif strategy_score >= 0.6:
      strategy_rank = "Watch"
    else:
      strategy_rank = "Avoid"

    summary_parts = [
      f"Live trend: {insights.get('trend')}",
      f"Live momentum: {insights.get('momentum_pct')}%",
      f"Live support/resistance: {insights.get('support')} / {insights.get('resistance')}",
    ]
    if ocr_text:
      summary_parts.append(f"OCR text used: {ocr_text[:220]}")
    if ocr_levels:
      summary_parts.append(f"OCR levels: {ocr_levels}")
    if screenshot_notes:
      summary_parts.append(f"Notes: {screenshot_notes[:220]}")

    return {
      "symbol": symbol,
      "signal": plan.get("signal"),
      "entry": round(entry, 2) if entry else None,
      "stop_loss": round(stop_loss, 2) if stop_loss else None,
      "take_profit_1": tp1 if tp1 else None,
      "take_profit_2": tp2 if tp2 else None,
      "take_profit_3": tp3 if tp3 else None,
      "confidence": combined_confidence,
      "grade": strategy_grade,
      "risk_reward": rr,
      "strategy_score": strategy_score,
      "strategy_rank": strategy_rank,
      "quality_in_range": quality_in_range,
      "target_pip_min": target_pip_min,
      "target_pip_max": target_pip_max,
      "expected_move_pips": expected_move_pips,
      "live_plan": plan,
      "insights": insights,
      "summary": " | ".join(summary_parts),
      "source_breakdown": {
        "live_data": True,
        "screenshot_text": bool(ocr_text),
        "parsed_levels": bool(ocr_levels),
        "notes": bool(screenshot_notes),
      },
      "generated_at": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S"),
    }


def extract_ocr_from_screenshot(image_path: Path):
    try:
      from PIL import Image
      pytesseract = importlib.import_module("pytesseract")
    except Exception as exc:
      return {
        "status": "unavailable",
        "message": f"OCR dependency missing: {exc}",
        "text": "",
        "parsed_levels": {},
      }

    try:
      with Image.open(str(image_path)) as img:
        text = pytesseract.image_to_string(img)
    except Exception as exc:
      return {
        "status": "failed",
        "message": f"OCR failed: {exc}",
        "text": "",
        "parsed_levels": {},
      }

    cleaned = "\n".join(line.strip() for line in str(text).splitlines() if line.strip())
    patterns = {
      "entry": [r"entry\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)", r"buy\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)", r"sell\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)"],
      "sl": [r"\bsl\b\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)", r"stop\s*loss\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)"],
      "tp1": [r"\btp1\b\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)", r"take\s*profit\s*1\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)"],
      "tp2": [r"\btp2\b\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)", r"take\s*profit\s*2\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)"],
      "tp3": [r"\btp3\b\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)", r"take\s*profit\s*3\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)"],
    }

    parsed_levels = {}
    for key, regexes in patterns.items():
      value = None
      for regex in regexes:
        match = re.search(regex, cleaned, flags=re.IGNORECASE)
        if match:
          try:
            value = float(match.group(1))
            break
          except Exception:
            continue
      if value is not None:
        parsed_levels[key] = value

    return {
      "status": "ok",
      "message": "OCR extracted text from screenshot",
      "text": cleaned,
      "parsed_levels": parsed_levels,
    }


def build_signal_candle_svg(symbol: str, plan: dict, bars: int = 32, width: int = 760, height: int = 420):
    symbol = symbol.upper()
    data = fetch_real_data(symbol, period="7d", interval="1h")
    if data.empty:
        data = generate_synthetic_data(symbol, n=bars)
    df = data.tail(bars).copy()
    if df.empty:
        return "<div>No chart data</div>"
    values = df[['open', 'high', 'low', 'close']].to_dict('records')
    max_val = max(row['high'] for row in values)
    min_val = min(row['low'] for row in values)
    pad = max((max_val - min_val) * 0.08, 1.0)
    max_val += pad
    min_val -= pad
    plot_height = height - 80
    plot_width = width - 80
    x_offset = 60
    y_offset = 40
    bar_width = plot_width / len(values)
    svg_parts = [
        f"<svg viewBox='0 0 {width} {height}' style='width:100%;height:auto;display:block;font-family:Arial;'>",
        f"<rect x='0' y='0' width='{width}' height='{height}' rx='18' ry='18' fill='#020617' stroke='#334155' stroke-width='1.5' />",
        f"<rect x='{x_offset - 10}' y='{y_offset - 12}' width='{plot_width + 20}' height='{plot_height + 24}' rx='14' ry='14' fill='none' stroke='#334155' stroke-width='1' />",
    ]
    for line in range(5):
        y = y_offset + (plot_height / 4) * line
        price = max_val - (max_val - min_val) * (line / 4)
        svg_parts.append(f"<line x1='{x_offset}' y1='{y:.1f}' x2='{x_offset + plot_width}' y2='{y:.1f}' stroke='#172f44' stroke-width='1' />")
        svg_parts.append(f"<text x='12' y='{(y + 4):.1f}' fill='#64748b' font-size='10'>{price:.2f}</text>")
    for idx, row in enumerate(values):
        x = x_offset + idx * bar_width
        wick_x = x + bar_width / 2
        open_y = y_offset + plot_height * (max_val - row['open']) / (max_val - min_val)
        close_y = y_offset + plot_height * (max_val - row['close']) / (max_val - min_val)
        high_y = y_offset + plot_height * (max_val - row['high']) / (max_val - min_val)
        low_y = y_offset + plot_height * (max_val - row['low']) / (max_val - min_val)
        color = '#22c55e' if row['close'] >= row['open'] else '#f87171'
        body_top = min(open_y, close_y)
        body_height = max(abs(close_y - open_y), 3)
        wick_height = max(abs(high_y - low_y), 1)
        svg_parts.append(f"<line x1='{wick_x:.1f}' y1='{high_y:.1f}' x2='{wick_x:.1f}' y2='{low_y:.1f}' stroke='{color}' stroke-width='1.5' />")
        svg_parts.append(f"<rect x='{(x + bar_width * 0.2):.1f}' y='{body_top:.1f}' width='{max(bar_width * 0.6, 3):.1f}' height='{body_height:.1f}' rx='1.5' ry='1.5' fill='{color}' />")
    plan_lines = [
        ('Entry', plan.get('entry'), '#22c55e'),
        ('SL', plan.get('stop_loss'), '#f87171'),
        ('TP1', plan.get('take_profit_1'), '#38bdf8'),
        ('TP2', plan.get('take_profit_2'), '#a78bfa'),
        ('TP3', plan.get('take_profit_3'), '#fb923c'),
    ]
    for label, value, color in plan_lines:
        if value is None:
            continue
        y = y_offset + plot_height * (max_val - value) / (max_val - min_val)
        svg_parts.append(f"<line x1='{x_offset}' y1='{y:.1f}' x2='{x_offset + plot_width}' y2='{y:.1f}' stroke='{color}' stroke-width='1.8' stroke-dasharray='6 4' />")
        svg_parts.append(f"<text x='{(x_offset + plot_width + 8):.1f}' y='{(y + 4):.1f}' fill='{color}' font-size='10'>{label}</text>")
    svg_parts.append(f"<text x='{x_offset}' y='22' fill='#f8fafc' font-size='13' font-weight='bold'>{symbol} {plan.get('signal', '')} Chart</text>")
    svg_parts.append(f"<text x='{x_offset}' y='{height - 8}' fill='#94a3b8' font-size='10'>Last updated: {datetime.now(timezone.utc).strftime('%H:%M:%S UTC')}</text>")
    svg_parts.append('</svg>')
    return ''.join(svg_parts)


def build_live_plan_with_chart(symbol: str):
    plan = build_live_plan(symbol)
    plan['chart_svg'] = build_signal_candle_svg(symbol, plan)
    return plan

@app.route('/api/live-plan/<symbol>')
def live_plan_api(symbol: str):
    return jsonify(build_live_plan(symbol.upper()))


def _build_soft_risk_guardrails(state: dict, symbol: str, confidence: float, ensemble_probability: float) -> dict:
    controls = _auto_trade_control_block(state)
    trades = state.get('trades') if isinstance(state.get('trades'), list) else []
    session = state.get('session') if isinstance(state.get('session'), dict) else {}

    max_risk = float(controls.get('max_risk_per_trade_pct', 2.0) or 2.0)
    max_open_trades = int(controls.get('max_open_trades', 8) or 8)
    open_trades = len([
        t for t in trades
        if str(t.get('status') or '').lower() in {'open', 'sent', 'executed'}
    ])

    conviction = max(0.0, min(1.0, abs(float(ensemble_probability or 0.5) - 0.5) * 2.0))
    recommended_risk = round(max(0.1, min(max_risk, max_risk * (0.45 + 0.55 * conviction))), 2)

    warnings = []
    if open_trades >= max_open_trades:
        warnings.append(f"Open trade count already at configured limit ({open_trades}/{max_open_trades}).")
    elif open_trades >= max(1, max_open_trades - 1):
        warnings.append(f"Open trade count near limit ({open_trades}/{max_open_trades}).")

    starting_balance = float(session.get('starting_balance') or 0.0)
    current_balance = float(session.get('current_balance') or starting_balance or 0.0)
    daily_loss_limit_pct = float(session.get('daily_loss_limit_pct') or 0.0)
    if starting_balance > 0 and daily_loss_limit_pct > 0:
        drawdown_pct = ((starting_balance - current_balance) / starting_balance) * 100.0
        if drawdown_pct >= daily_loss_limit_pct:
            warnings.append(f"Daily drawdown guardrail reached ({drawdown_pct:.2f}% >= {daily_loss_limit_pct:.2f}%).")
        elif drawdown_pct >= daily_loss_limit_pct * 0.8:
            warnings.append(f"Daily drawdown near guardrail ({drawdown_pct:.2f}% of {daily_loss_limit_pct:.2f}%).")

    if float(confidence or 0.0) < 0.58:
        warnings.append("Confidence is below preferred execution zone (<58%).")

    return {
        "symbol": symbol,
        "status": "warn" if warnings else "ok",
        "advisory_only": True,
        "max_risk_per_trade_pct": round(max_risk, 2),
        "recommended_risk_pct": recommended_risk,
        "max_open_trades": max_open_trades,
        "open_trades": open_trades,
        "warnings": warnings,
    }


def build_signal_payload():
  cached = _get_cached_signal_payload()
  if cached is not None:
    return cached
  payload = [_enrich_signal_record(signal) for signal in _build_signal_payload_uncached()]
  _set_cached_signal_payload(payload)
  return payload


def _signal_bar_time_text(signal_time):
    """UTC text of the bar the live signal was predicted on, or None."""
    import pandas as pd
    if signal_time is None:
        return None
    try:
        return pd.Timestamp(signal_time).tz_convert("UTC").strftime("%Y-%m-%d %H:%M:%S")
    except (TypeError, ValueError):
        return None


def _signal_bar_age_minutes(signal_time, now):
    """Minutes between the signal bar's open time and ``now`` (a closed 1h bar is 60-120 min old)."""
    import pandas as pd
    if signal_time is None:
        return None
    try:
        return round((pd.Timestamp(now) - pd.Timestamp(signal_time).tz_convert("UTC")).total_seconds() / 60.0, 1)
    except (TypeError, ValueError):
        return None


def _build_signal_payload_uncached():
    auto_state = load_auto_trader_state()
    payload = []
    for symbol in ["XAUUSD", "BTCUSD"]:
        data = fetch_real_data(symbol, period="120d", interval="1h")
        if data.empty:
            data = generate_synthetic_data(symbol, n=500)
        # Execution safety item 4: predict on the newest CLOSED 1h bar. The forming bar is dropped, and inference
        # features keep the last 3 rows that build_features used to discard for their unknown look-ahead target.
        from src.paper_trader import drop_forming_bars
        signal_now = datetime.now(timezone.utc)
        closed_data = drop_forming_bars(data, 60, signal_now)
        if closed_data is not None and not closed_data.empty:
            data = closed_data
        features = build_inference_features(data)
        clf = load_model(symbol)
        metrics = load_metrics(symbol) or {"accuracy": 0.5}
        lstm_metrics = load_lstm_metrics(symbol) or {}
        lstm_trader = None
        try:
            lstm_trader = LSTMTrader(symbol)
        except Exception:
            lstm_trader = None
        if clf is None:
            clf, metrics = train_model(data, symbol)
        latest = features.iloc[-1:]
        # One engine for live and backtests (src/signal_engine.py, config "live"): RF + LSTM blend, 0.55 / 0.45
        # bands with a neutral HOLD zone. The old rule "BUY if >= 0.55 else SELL" turned every probability below
        # the buy threshold - including a dead-neutral 0.50 - into a short.
        engine_result = engine_live_signal(data, {"rf": clf, "lstm": lstm_trader, "feature_columns": FEATURE_COLUMNS},
                                           features=features)
        rf_probability = float(engine_result["rf_probability"])
        lstm_probability = engine_result["lstm_probability"]
        ensemble_probability = float(engine_result["probability"])
        signal = engine_result["signal"]
        model_accuracy = metrics.get("accuracy", 0.5)
        lstm_accuracy = lstm_metrics.get("accuracy") if lstm_metrics.get("accuracy") is not None else model_accuracy
        confidence = round(min(0.99, max(0.55, (model_accuracy * 0.55 + lstm_accuracy * 0.35 + ensemble_probability * 0.1))), 2)
        profile = get_adaptive_pip_profile(
          symbol,
          volatility_pct=float(latest.iloc[-1].get("volatility_5d", 0) or 0.0),
          hour_utc=datetime.now(timezone.utc).hour,
        )
        pip_size = float(profile["pip_size"])
        min_pips = float(profile["min_pips"])
        max_pips = float(profile["max_pips"])
        latest_row = features.iloc[-1]
        expected_move_price = abs(float(latest_row.get("volatility_5d", 0) or 0.0) * float(latest_row.get("close", 0) or 0.0) * 3.0)
        expected_move_pips = round(expected_move_price / max(1e-9, pip_size), 1)
        quality_in_range = min_pips <= expected_move_pips <= max_pips
        if not quality_in_range:
          confidence = round(max(0.51, confidence - 0.07), 2)
        bias = "Bullish" if signal == "BUY" else "Bearish" if signal == "SELL" else "Neutral"
        reason = (
          f"Ensemble RF+LSTM model signal with RF {rf_probability:.3f} and LSTM {f'{lstm_probability:.3f}' if lstm_probability is not None else 'n/a'}"
          f" | target {int(min_pips)}-{int(max_pips)} pips | expected {expected_move_pips} pips"
        )
        strategy = _build_strategy_profile(symbol, data, features, signal, confidence, ensemble_probability)
        guardrails = _build_soft_risk_guardrails(auto_state, symbol, confidence, ensemble_probability)
        payload.append(
            {
                "symbol": symbol,
                "signal": signal,
                "confidence": confidence,
                "bias": bias,
                "reason": reason,
            "quality_in_range": quality_in_range,
            "target_pip_min": min_pips,
            "target_pip_max": max_pips,
            "expected_move_pips": expected_move_pips,
            **strategy,
                "model_accuracy": model_accuracy,
                "lstm_accuracy": lstm_accuracy,
                "rf_probability": round(rf_probability, 4),
                "lstm_probability": round(lstm_probability, 4) if lstm_probability is not None else None,
                "ensemble_probability": round(ensemble_probability, 4),
                "risk_guardrails": guardrails,
                "learning_health": {
                    "rf_calibration_enabled": bool(metrics.get("calibration_enabled", False)),
                    "rf_ece_10": metrics.get("ece_10"),
                    "rf_brier_score": metrics.get("brier_score"),
                    "cv_accuracy_mean": metrics.get("cv_accuracy_mean"),
                    "cv_accuracy_std": metrics.get("cv_accuracy_std"),
                    "lstm_precision": lstm_metrics.get("precision"),
                    "lstm_recall": lstm_metrics.get("recall"),
                    "lstm_f1_score": lstm_metrics.get("f1_score"),
                },
                "signal_bar_time": _signal_bar_time_text(engine_result.get("signal_time")),
                "signal_bar_age_minutes": _signal_bar_age_minutes(engine_result.get("signal_time"), signal_now),
                "generated_at": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S"),
            }
        )
    try:
        record_signal_history(payload)
    except Exception:
        logging.getLogger(__name__).exception("signal history write failed")
    return payload


def _strategy_timing_score(hour_utc: int) -> float:
  if 6 <= hour_utc <= 10:
    return 0.95
  if 12 <= hour_utc <= 16:
    return 0.9
  if 18 <= hour_utc <= 21:
    return 0.72
  return 0.55


def _strategy_fvg_score(row, signal_side: str) -> float:
  fvg_up = float(row.get("fvg_up", 0) or 0)
  fvg_down = float(row.get("fvg_down", 0) or 0)
  pullback = float(row.get("pullback", 0) or 0)
  reversal = float(row.get("reversal", 0) or 0)
  if signal_side == "BUY":
    base = 0.5 + (0.2 if fvg_up > 0 else -0.05) + (0.1 if pullback > 0 else 0) + (0.05 if reversal > 0 else 0)
  else:
    base = 0.5 + (0.2 if fvg_down > 0 else -0.05) + (0.1 if pullback > 0 else 0) + (0.05 if reversal > 0 else 0)
  return round(max(0.0, min(1.0, base)), 2)


def _build_strategy_profile(symbol: str, data, features, signal_side: str, confidence: float, ensemble_probability: float):
  latest_row = features.iloc[-1]
  trend_5 = float(latest_row.get("trend_5", 0) or 0)
  trend_20 = float(latest_row.get("trend_20", 0) or 0)
  rsi_14 = float(latest_row.get("rsi_14", 50) or 50)
  signal_side = str(signal_side or "SELL").upper()
  hour_utc = datetime.now(timezone.utc).hour

  if signal_side == "BUY":
    ict_raw = 0.5 + (0.2 if trend_5 >= trend_20 else -0.1) + (0.15 if rsi_14 >= 55 else -0.05)
  else:
    ict_raw = 0.5 + (0.2 if trend_5 <= trend_20 else -0.1) + (0.15 if rsi_14 <= 45 else -0.05)
  ict_score = round(max(0.0, min(1.0, ict_raw)), 2)

  crt_score = round(_strategy_timing_score(hour_utc), 2)
  fvg_score = _strategy_fvg_score(latest_row, signal_side)

  strategy_score = round((ict_score * 0.45) + (crt_score * 0.25) + (fvg_score * 0.3), 2)
  if strategy_score >= 0.8:
    strategy_grade = "A"
  elif strategy_score >= 0.68:
    strategy_grade = "B"
  elif strategy_score >= 0.55:
    strategy_grade = "C"
  else:
    strategy_grade = "D"

  strategy_label = "ICT + CRT + FVG"
  if strategy_score >= 0.7:
    strategy_rank = "Top"
  elif strategy_score >= 0.6:
    strategy_rank = "Watch"
  else:
    strategy_rank = "Avoid"

  strategy_reason = f"ICT {ict_score:.2f} | CRT {crt_score:.2f} | FVG {fvg_score:.2f} | signal {signal_side}"
  return {
    "strategy_label": strategy_label,
    "strategy_score": strategy_score,
    "strategy_grade": strategy_grade,
    "strategy_rank": strategy_rank,
    "strategy_reason": strategy_reason,
    "ict_score": ict_score,
    "crt_score": crt_score,
    "fvg_score": fvg_score,
  }


def _enrich_signal_record(signal: dict):
  generated_at = signal.get("generated_at")
  recorded_at = generated_at or ""
  record_day = ""
  record_month = ""
  record_year = ""
  record_time = ""

  parsed_time = None
  if generated_at:
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
      try:
        parsed_time = datetime.strptime(str(generated_at), fmt).replace(tzinfo=timezone.utc)
        break
      except ValueError:
        continue
  if parsed_time is not None:
    record_day = parsed_time.strftime("%d")
    record_month = parsed_time.strftime("%b")
    record_year = parsed_time.strftime("%Y")
    record_time = parsed_time.strftime("%H:%M:%S UTC")

  outcome = "OPEN"
  outcome_profit_pct = None
  outcome_time = recorded_at
  signal_side = str(signal.get("signal", "")).upper()
  confidence = float(signal.get("confidence", 0) or 0)
  if signal_side:
    # Settled from the price path (stop vs target, whichever is touched first),
    # never from the confidence score. Trades still running report as OPEN.
    evaluation = _safe_signal_evaluation(signal)
    if evaluation is not None:
      outcome_profit_pct = evaluation.get("profit_pct")
      status = evaluation.get("status")
      outcome = "WIN" if status in {"TP1", "TP2", "TP3"} else "LOSS" if status == "SL" else "OPEN"
      outcome_time = evaluation.get("exit_time") or recorded_at

  strategy_label = signal.get("strategy_label") or "ICT + CRT + FVG"
  strategy_score = signal.get("strategy_score")
  if strategy_score is None:
    strategy_score = round(min(0.95, max(0.35, confidence * 0.9 + (0.08 if outcome == "WIN" else -0.05))), 2)
  strategy_grade = signal.get("strategy_grade")
  if not strategy_grade:
    if strategy_score >= 0.8:
      strategy_grade = "A"
    elif strategy_score >= 0.68:
      strategy_grade = "B"
    elif strategy_score >= 0.55:
      strategy_grade = "C"
    else:
      strategy_grade = "D"
  strategy_rank = signal.get("strategy_rank") or ("Top" if strategy_score >= 0.7 else "Watch" if strategy_score >= 0.6 else "Avoid")
  strategy_reason = signal.get("strategy_reason") or f"Fallback score from signal confidence {confidence:.2f}"
  target_pip_min = float(signal.get("target_pip_min", 30) or 30)
  target_pip_max = float(signal.get("target_pip_max", 2000) or 2000)
  expected_move_pips = float(signal.get("expected_move_pips", round(confidence * target_pip_min, 1)) or round(confidence * target_pip_min, 1))
  quality_in_range = bool(signal.get("quality_in_range", target_pip_min <= expected_move_pips <= target_pip_max))
  ict_score = signal.get("ict_score")
  if ict_score is None:
    ict_score = round(max(0.0, min(1.0, strategy_score * 0.95)), 2)
  crt_score = signal.get("crt_score")
  if crt_score is None:
    crt_score = round(max(0.0, min(1.0, strategy_score * 0.85 + 0.05)), 2)
  fvg_score = signal.get("fvg_score")
  if fvg_score is None:
    fvg_score = round(max(0.0, min(1.0, strategy_score * 0.9)), 2)

  outcome_day = ""
  outcome_month = ""
  outcome_year = ""
  outcome_clock = ""
  if outcome_time:
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
      try:
        outcome_dt = datetime.strptime(str(outcome_time), fmt).replace(tzinfo=timezone.utc)
        outcome_day = outcome_dt.strftime("%d")
        outcome_month = outcome_dt.strftime("%b")
        outcome_year = outcome_dt.strftime("%Y")
        outcome_clock = outcome_dt.strftime("%H:%M:%S UTC")
        break
      except ValueError:
        continue

  # Rows written by the old "BUY if >= 0.55 else SELL" rule carry a side their
  # own probability does not support. Flag them rather than rewrite history.
  legacy_misclassified = _is_legacy_misclassified(signal)

  enriched = dict(signal)
  enriched.update({
    "legacy_misclassified": legacy_misclassified,
    "recorded_at": recorded_at,
    "record_day": record_day,
    "record_month": record_month,
    "record_year": record_year,
    "record_time": record_time,
    "outcome": outcome,
    "outcome_profit_pct": outcome_profit_pct,
    "outcome_time": outcome_time,
    "outcome_day": outcome_day,
    "outcome_month": outcome_month,
    "outcome_year": outcome_year,
    "outcome_clock": outcome_clock,
    "strategy_label": strategy_label,
    "strategy_score": strategy_score,
    "strategy_grade": strategy_grade,
    "strategy_rank": strategy_rank,
    "strategy_reason": strategy_reason,
    "target_pip_min": target_pip_min,
    "target_pip_max": target_pip_max,
    "expected_move_pips": expected_move_pips,
    "quality_in_range": quality_in_range,
    "ict_score": ict_score,
    "crt_score": crt_score,
    "fvg_score": fvg_score,
  })
  return enriched


def build_quality_monitor(signals: list[dict]):
  if not signals:
    return {
      "count": 0,
      "in_range_count": 0,
      "out_range_count": 0,
      "out_range_ratio": 0,
      "in_range_win_rate": 0,
      "out_range_win_rate": 0,
      "recommend_retrain": False,
      "recommended_symbols": [],
      "reasons": ["No signal history yet"],
      "thresholds": QUALITY_THRESHOLDS,
      "by_symbol": {},
    }

  total = len(signals)
  in_range = [item for item in signals if item.get("quality_in_range")]
  out_range = [item for item in signals if not item.get("quality_in_range")]

  def _win_rate(bucket: list[dict]):
    if not bucket:
      return 0.0
    wins = sum(1 for item in bucket if item.get("outcome") == "WIN")
    return round(wins / len(bucket) * 100, 1)

  in_range_win_rate = _win_rate(in_range)
  out_range_win_rate = _win_rate(out_range)
  out_range_ratio = round(len(out_range) / max(1, total) * 100, 1)

  by_symbol = {}
  recommended_symbols = []
  reasons = []
  symbols = sorted({str(item.get("symbol", "")).upper() for item in signals if item.get("symbol")})
  for symbol in symbols:
    bucket = [item for item in signals if str(item.get("symbol", "")).upper() == symbol]
    bucket_in = [item for item in bucket if item.get("quality_in_range")]
    bucket_out = [item for item in bucket if not item.get("quality_in_range")]
    bucket_out_ratio = round(len(bucket_out) / max(1, len(bucket)) * 100, 1)
    bucket_in_win_rate = _win_rate(bucket_in)
    bucket_out_win_rate = _win_rate(bucket_out)
    thresholds = QUALITY_THRESHOLDS.get(symbol, QUALITY_THRESHOLDS["default"])
    symbol_reasons = []
    if bucket_out_ratio >= thresholds["max_out_range_ratio"]:
      symbol_reasons.append(f"out-range {bucket_out_ratio}% >= {thresholds['max_out_range_ratio']}%")
    if bucket_in and bucket_in_win_rate < thresholds["min_in_range_win_rate"]:
      symbol_reasons.append(f"in-range win rate {bucket_in_win_rate}% < {thresholds['min_in_range_win_rate']}%")
    symbol_recommend = bool(symbol_reasons)
    if symbol_recommend:
      recommended_symbols.append(symbol)
      reasons.append(f"{symbol}: {'; '.join(symbol_reasons)}")
    by_symbol[symbol] = {
      "count": len(bucket),
      "in_range_count": len(bucket_in),
      "out_range_count": len(bucket_out),
      "out_range_ratio": bucket_out_ratio,
      "in_range_win_rate": bucket_in_win_rate,
      "out_range_win_rate": bucket_out_win_rate,
      "recommend_retrain": symbol_recommend,
      "reasons": symbol_reasons or ["within thresholds"],
      "thresholds": {
        "max_out_range_ratio": thresholds["max_out_range_ratio"],
        "min_in_range_win_rate": thresholds["min_in_range_win_rate"],
      },
    }

  if not reasons:
    reasons.append("Signal quality is within configured thresholds")

  recommend_retrain = bool(recommended_symbols)
  return {
    "count": total,
    "in_range_count": len(in_range),
    "out_range_count": len(out_range),
    "out_range_ratio": out_range_ratio,
    "in_range_win_rate": in_range_win_rate,
    "out_range_win_rate": out_range_win_rate,
    "recommend_retrain": bool(recommend_retrain),
    "recommended_symbols": recommended_symbols,
    "reasons": reasons,
    "thresholds": QUALITY_THRESHOLDS,
    "by_symbol": by_symbol,
  }


def build_live_series(symbol: str):
    return _get_cached_live_series(symbol)


def _build_live_series_uncached(symbol: str):
  symbol = symbol.upper()
  cache_key = f"series:{symbol}"
  cached = _market_get_cached_series(symbol)

  if _market_circuit_open(cache_key) and cached:
    _market_set_series_source(symbol, 'cached-circuit-open')
    return cached.get('values', [])

  values = fetch_intraday_prices_from_yahoo(symbol, interval="5m", period="1d")
  if values:
    _market_set_series_source(symbol, 'live-yahoo-intraday')
  else:
    values = fetch_daily_prices_from_yahoo(symbol, periods=20)
    if values:
      _market_set_series_source(symbol, 'live-yahoo-daily')

  if not values:
    _market_record_failure(cache_key, 'series feed unavailable')
    if cached and cached.get('values'):
      _market_set_series_source(symbol, 'cached-after-failure')
      return cached.get('values', [])

    base = 2000.0 if symbol == "XAUUSD" else 50000.0
    values = []
    for i in range(20):
      drift = 0.0008 * (i - 10) + (0.0004 if symbol == "BTCUSD" else 0.0002)
      base *= (1 + drift)
      values.append(round(base, 2))
    _market_set_series_source(symbol, 'synthetic-fallback')

  values = values[-20:]
  _market_set_cached_series(symbol, values)
  _market_record_success(cache_key)
  return values


def compute_ensemble_probability(symbol: str, data, features, idx: int):
    clf = load_model(symbol)
    rf_probability = 0.5
    try:
        if clf is not None and hasattr(clf, "predict_proba"):
            rf_probability = float(clf.predict_proba(features.iloc[[idx]][FEATURE_COLUMNS])[0, 1])
        elif clf is not None:
            rf_probability = float(clf.predict(features.iloc[[idx]][FEATURE_COLUMNS])[0])
    except Exception:
        rf_probability = 0.5

    lstm_probability = None
    try:
        trader = LSTMTrader(symbol)
        original_index = features.index[idx]
        slice_data = data.loc[:original_index]
        lstm_probability = trader.predict(slice_data)
    except Exception:
        lstm_probability = None

    # Same blend as the live signal (src/signal_engine.py, config "live").
    from src.signal_engine import blend_probabilities as engine_blend_probabilities

    ensemble_probability = round(engine_blend_probabilities(rf_probability, lstm_probability, "live"), 4)
    if lstm_probability is not None:
        return ensemble_probability, round(rf_probability, 4), round(lstm_probability, 4)
    return ensemble_probability, round(rf_probability, 4), None


def build_shadow_simulation(symbol: str, entries: int = 6, horizon: int = 24):
    symbol = symbol.upper()
    data = fetch_real_data(symbol, period="120d", interval="1h")
    if data.empty:
        return {"symbol": symbol, "error": "no_data", "results": []}
    features = build_features(data)
    if features.empty:
        return {"symbol": symbol, "error": "no_features", "results": []}
    results = []
    start_idx = max(0, len(features) - entries - 1)
    for idx in range(start_idx, len(features) - 1):
        row = features.iloc[idx]
        entry_price = float(row["close"])
        direction = 1 if row.get("return_1d", 0.0) >= 0 else -1
        ensemble_probability, rf_probability, lstm_probability = compute_ensemble_probability(symbol, data, features, idx)
        signal = _classify_signal(ensemble_probability)
        if not _is_tradeable_side(signal):
            # Neutral readings are stood aside rather than simulated as shorts.
            continue
        direction = 1 if signal == "BUY" else -1
        vol5 = float(row.get("volatility_5d") or 0.01)
        atr = max(0.5, vol5 * entry_price)
        sl = round(entry_price - direction * atr * 1.2, 2)
        tp1 = round(entry_price + direction * atr * 2.4, 2)
        tp2 = round(entry_price + direction * atr * 3.6, 2)
        tp3 = round(entry_price + direction * atr * 4.8, 2)
        result = {
            "symbol": symbol,
            "entry_time": row["datetime"].strftime("%Y-%m-%d %H:%M:%S") if hasattr(row["datetime"], "strftime") else str(row["datetime"]),
            "signal": signal,
            "entry_price": entry_price,
            "sl": sl,
            "tp1": tp1,
            "tp2": tp2,
            "tp3": tp3,
            "rf_probability": rf_probability,
            "lstm_probability": lstm_probability,
            "ensemble_probability": ensemble_probability,
            "status": "none",
            "hit_price": None,
            "profit_pct": None,
            "bars": 0,
        }
        future = data.loc[features.index[idx] + 1: features.index[idx] + horizon]
        for bar_index, bar in future.iterrows():
            low = float(bar["low"])
            high = float(bar["high"])
            result["bars"] += 1
            if direction == 1:
                if low <= sl:
                    result["status"] = "SL"
                    result["hit_price"] = sl
                    result["profit_pct"] = round((sl - entry_price) / entry_price * 100, 2)
                    break
                if high >= tp1:
                    result["status"] = "TP1"
                    result["hit_price"] = tp1
                    result["profit_pct"] = round((tp1 - entry_price) / entry_price * 100, 2)
                    break
                if high >= tp2:
                    result["status"] = "TP2"
                    result["hit_price"] = tp2
                    result["profit_pct"] = round((tp2 - entry_price) / entry_price * 100, 2)
                    break
                if high >= tp3:
                    result["status"] = "TP3"
                    result["hit_price"] = tp3
                    result["profit_pct"] = round((tp3 - entry_price) / entry_price * 100, 2)
                    break
            else:
                if high >= sl:
                    result["status"] = "SL"
                    result["hit_price"] = sl
                    result["profit_pct"] = round((entry_price - sl) / entry_price * 100, 2)
                    break
                if low <= tp1:
                    result["status"] = "TP1"
                    result["hit_price"] = tp1
                    result["profit_pct"] = round((entry_price - tp1) / entry_price * 100, 2)
                    break
                if low <= tp2:
                    result["status"] = "TP2"
                    result["hit_price"] = tp2
                    result["profit_pct"] = round((entry_price - tp2) / entry_price * 100, 2)
                    break
                if low <= tp3:
                    result["status"] = "TP3"
                    result["hit_price"] = tp3
                    result["profit_pct"] = round((entry_price - tp3) / entry_price * 100, 2)
                    break
        if result["status"] == "none":
            last_close = float(future["close"].iloc[-1]) if not future.empty else entry_price
            result["profit_pct"] = round((last_close - entry_price) / entry_price * 100 * direction, 2)
        results.append(result)
    win_count = sum(1 for item in results if item["status"] and item["status"] != "SL" and item["status"] != "none")
    loss_count = sum(1 for item in results if item["status"] == "SL")
    no_result_count = sum(1 for item in results if item["status"] == "none")
    profit_values = [item["profit_pct"] for item in results if item["profit_pct"] is not None]
    avg_profit_pct = round(sum(profit_values) / len(profit_values), 2) if profit_values else 0.0
    avg_win_pct = round(sum(item["profit_pct"] for item in results if item["status"] not in ("SL", "none")) / max(1, win_count), 2) if win_count else 0.0
    avg_loss_pct = round(sum(item["profit_pct"] for item in results if item["status"] == "SL") / max(1, loss_count), 2) if loss_count else 0.0
    total_return_pct = round(sum(profit_values), 2) if profit_values else 0.0
    return {
        "symbol": symbol,
        "results": results,
        "win_count": win_count,
        "loss_count": loss_count,
        "no_result_count": no_result_count,
        "win_rate": round(win_count / max(1, len(results)) * 100, 2),
        "tested_entries": len(results),
        "avg_profit_pct": avg_profit_pct,
        "avg_win_pct": avg_win_pct,
        "avg_loss_pct": avg_loss_pct,
        "total_return_pct": total_return_pct,
    }


