# SwingTrendPullback EA tab (src/ea_monitor.py): the MT5 expert exports its status and deals to
# Common\Files\SwingTrendPullback; every read merges its trades into data/ea/swing_trend_pullback/trades.json.
# Read-only: nothing here sends orders or changes the expert.
_swing_ea_cache = {'value': None, 'expires_at': 0.0}


@app.route('/api/ea/swing-trend-pullback')
def swing_trend_pullback_ea_api():
  if (_swing_ea_cache['value'] is not None and monotonic() < _swing_ea_cache['expires_at']
      and str(request.args.get('refresh') or '') != '1'):
    return jsonify(_swing_ea_cache['value'])
  try:
    from src import ea_monitor
    value = ea_monitor.build_summary(store_path=os.path.join(_APP_DIR, str(ea_monitor.STORE_PATH)))
  except Exception as exc:
    return jsonify({'available': False, 'places_orders': False, 'reason': f'EA monitor unavailable: {exc}'})
  _swing_ea_cache.update(value=value, expires_at=monotonic() + 10)
  return jsonify(value)


