@app.route('/api/auto-trade/status')
def auto_trade_status_api():
  state = load_auto_trader_state()
  approval = _jarvis_approval_block(state)
  _jarvis_prune_approval_requests(approval)
  include_full = str(request.args.get('full', '0') or '0').strip().lower() in {'1', 'true', 'yes'}
  include_prices = str(request.args.get('include_prices', '0') or '0').strip().lower() in {'1', 'true', 'yes'}
  max_trades = _clamp_int_arg(request.args.get('limit'), default=120, low=20, high=500)
  mt5_status = MT5_ENGINE.status()
  mt4_status = MT4_ENGINE.status()
  mt5_account = MT5_ENGINE.account_info() if mt5_status.get('connected') else {
    'status': mt5_status,
    'account': None,
    'summary': {
      'open_positions': 0,
      'open_positions_detail': [],
      'closed_trades': 0,
      'wins': 0,
      'losses': 0,
      'win_rate': 0.0,
      'net_profit': 0.0,
    },
  }
  mt4_account = MT4_ENGINE.account_info() if mt4_status.get('connected') else {
    'balance': 0,
    'equity': 0,
    'margin_used': 0,
    'margin_free': 0,
    'margin_level': 0,
    'connected': False,
    'message': 'MT4 not connected',
  }
  
  # Add current prices to open trades only when explicitly requested.
  # This avoids expensive market fetches on every UI poll.
  trades = state.get('trades', [])
  if include_prices:
    refreshed = 0
    for trade in reversed(trades):
      if refreshed >= 15:
        break
      if trade.get('status') == 'open':
        try:
          series = build_live_series(trade.get('symbol', 'XAUUSD'))
          if series:
            trade['current_price'] = float(series[-1])
            refreshed += 1
        except Exception:
          continue

  # Keep status payload lightweight for frequent UI polling.
  payload_trades = trades[-max_trades:]
  if not include_full:
    compact = []
    for trade in payload_trades:
      item = dict(trade) if isinstance(trade, dict) else {}
      mt5 = item.get('mt5') if isinstance(item.get('mt5'), dict) else None
      mt4 = item.get('mt4') if isinstance(item.get('mt4'), dict) else None
      if mt5:
        item['mt5'] = {
          'executed': bool(mt5.get('executed')),
          'ok': bool(mt5.get('ok', mt5.get('executed'))),
          'message': mt5.get('message'),
          'status': mt5.get('status') if isinstance(mt5.get('status'), dict) else None,
        }
      if mt4:
        item['mt4'] = {
          'executed': bool(mt4.get('executed')),
          'message': mt4.get('message'),
          'ticket': mt4.get('ticket'),
        }
      compact.append(item)
    payload_trades = compact
  
  return jsonify({
    'session': state.get('session'),
    'trades': payload_trades,
    'settings': state.get('settings') if isinstance(state.get('settings'), dict) else {},
    'summary': summarize_auto_trader_state(state),
    'approval': approval,
    'mt5': mt5_status,
    'mt4': mt4_status,
    'mt5_account': mt5_account,
    'mt4_account': mt4_account,
  })


@app.route('/api/auto-trade/settings', methods=['GET', 'POST'])
def auto_trade_settings_api():
  state = load_auto_trader_state()
  if request.method == 'GET':
    return jsonify({
      'status': 'ok',
      'settings': state.get('settings') if isinstance(state.get('settings'), dict) else {},
    })

  payload = request.get_json(silent=True) or request.form.to_dict() or {}
  incoming = payload.get('settings') if isinstance(payload.get('settings'), dict) else payload

  current = state.get('settings') if isinstance(state.get('settings'), dict) else {}
  ui = incoming.get('ui') if isinstance(incoming.get('ui'), dict) else {}
  asset = incoming.get('asset_settings') if isinstance(incoming.get('asset_settings'), dict) else {}
  controls = incoming.get('trade_controls') if isinstance(incoming.get('trade_controls'), dict) else {}

  merged_ui = dict(current.get('ui') if isinstance(current.get('ui'), dict) else {})
  merged_ui.update(ui)

  merged_asset = dict(current.get('asset_settings') if isinstance(current.get('asset_settings'), dict) else {})
  for symbol, settings in asset.items():
    key = str(symbol or '').upper().strip()
    if not key:
      continue
    if isinstance(settings, dict):
      merged_asset[key] = {
        'auto_enabled': bool(settings.get('auto_enabled', False)),
        'confidence_threshold': float(settings.get('confidence_threshold', 0.60) or 0.60),
      }

  merged_controls = dict(current.get('trade_controls') if isinstance(current.get('trade_controls'), dict) else {})
  if controls:
    merged_controls['block_new_trades'] = bool(controls.get('block_new_trades', merged_controls.get('block_new_trades', False)))
    try:
      merged_controls['max_open_trades'] = int(max(1, min(50, int(controls.get('max_open_trades', merged_controls.get('max_open_trades', 8)) or 8))))
    except Exception:
      merged_controls['max_open_trades'] = int(merged_controls.get('max_open_trades', 8) or 8)
    try:
      merged_controls['max_risk_per_trade_pct'] = float(max(0.1, min(5.0, float(controls.get('max_risk_per_trade_pct', merged_controls.get('max_risk_per_trade_pct', 2.0)) or 2.0))))
    except Exception:
      merged_controls['max_risk_per_trade_pct'] = float(merged_controls.get('max_risk_per_trade_pct', 2.0) or 2.0)
    merged_controls['allow_buy'] = bool(controls.get('allow_buy', merged_controls.get('allow_buy', True)))
    merged_controls['allow_sell'] = bool(controls.get('allow_sell', merged_controls.get('allow_sell', True)))

  state['settings'] = {
    'ui': merged_ui,
    'asset_settings': merged_asset,
    'trade_controls': merged_controls,
    'updated_at': datetime.now(timezone.utc).isoformat(),
  }
  save_auto_trader_state(state)
  return jsonify({'status': 'saved', 'settings': state['settings']})


@app.route('/api/auto-trade/start-session', methods=['POST'])
def auto_trade_start_session_api():
  payload = request.get_json(silent=True) or request.form.to_dict() or {}
  platform = str(payload.get('platform', 'mt5') or 'mt5').strip().lower()
  mode = str(payload.get('mode', 'demo') or 'demo').strip().lower()
  if platform not in {'mt4', 'mt5'}:
    return jsonify({'error': 'platform must be mt4 or mt5'}), 400
  if mode not in {'demo', 'mt5_live', 'mt4_live'}:
    return jsonify({'error': 'mode must be demo, mt5_live, or mt4_live'}), 400
  if platform == 'mt4' and mode == 'mt5_live':
    return jsonify({'error': 'mode mt5_live is not valid for MT4 platform'}), 400
  if platform == 'mt5' and mode == 'mt4_live':
    return jsonify({'error': 'mode mt4_live is not valid for MT5 platform'}), 400

  if mode == 'mt5_live':
    mt5_status = MT5_ENGINE.status()
    if not bool(mt5_status.get('connected')):
      return jsonify({
        'error': 'MT5 live bridge is not connected. Check MT5 terminal, credentials, and API bridge.',
        'bridge': mt5_status,
      }), 503
  if mode == 'mt4_live':
    mt4_status = MT4_ENGINE.status()
    if not bool(mt4_status.get('connected')):
      return jsonify({
        'error': 'MT4 live bridge is not connected. Check DWX-ZeroMQ EA and bridge port settings.',
        'bridge': mt4_status,
      }), 503

  starting_balance = max(100.0, float(payload.get('starting_balance') or 10000.0))
  risk_percent = _clamp_float_arg(payload.get('risk_percent') or 1.0, default=1.0, low=0.1, high=5.0)
  lot_size = _clamp_float_arg(payload.get('lot_size') or 0.01, default=0.01, low=0.01, high=5.0)

  state = load_auto_trader_state()
  ui_settings = state.get('settings', {}).get('ui') if isinstance(state.get('settings'), dict) else {}
  state['session'] = {
    'platform': platform,
    'mode': mode,
    'starting_balance': round(starting_balance, 2),
    'current_balance': round(starting_balance, 2),
    'risk_percent': round(risk_percent, 2),
    'lot_size': round(lot_size, 3),
    'daily_loss_limit_pct': float(payload.get('daily_loss_limit_pct') or ui_settings.get('daily_loss_limit_pct') or 5.0),
    'max_trades_per_day': int(payload.get('max_trades_per_day') or ui_settings.get('max_trades_per_day') or 10),
    'trailing_stop_enabled': bool(payload.get('trailing_stop_enabled', ui_settings.get('trailing_stop_enabled', True))),
    'tp_pips': int(payload.get('tp_pips') or ui_settings.get('tp_pips') or 100),
    'sl_pips': int(payload.get('sl_pips') or ui_settings.get('sl_pips') or 50),
    'partial_tp_enabled': bool(payload.get('partial_tp_enabled', ui_settings.get('partial_tp_enabled', True))),
    'started_at': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
    'active': True,
  }
  save_auto_trader_state(state)
  return jsonify({
    'status': 'started',
    'session': state['session'],
    'summary': summarize_auto_trader_state(state),
  })


@app.route('/api/auto-trade/analyze', methods=['POST'])
def auto_trade_analyze_api():
  report = build_ai_profitability_report()
