@app.route('/api/auto-trade/recommend', methods=['POST'])
def auto_trade_recommend_api():
  payload = request.get_json(silent=True) or request.form.to_dict() or {}
  state = load_auto_trader_state()
  session = state.get('session') if isinstance(state.get('session'), dict) else None

  symbol = str(payload.get('symbol', 'XAUUSD') or 'XAUUSD').strip().upper()
  timeframe = str(payload.get('timeframe', '15m') or '15m').strip().lower()
  execution_mode = str(payload.get('execution_mode') or (session.get('mode') if isinstance(session, dict) else None) or 'demo').strip().lower()
  request_approval = bool(payload.get('request_approval', False))

  risk_percent = _clamp_float_arg(payload.get('risk_percent') or ((session or {}).get('risk_percent') if isinstance(session, dict) else None) or 1.0, default=1.0, low=0.1, high=5.0)
  lot_size = _clamp_float_arg(payload.get('lot_size') or ((session or {}).get('lot_size') if isinstance(session, dict) else None) or 0.01, default=0.01, low=0.01, high=5.0)

  tz_offset_raw = payload.get('tz_offset_min')
  tz_offset_min = None
  if tz_offset_raw is not None:
    try:
      tz_offset_min = int(str(tz_offset_raw).strip())
    except Exception:
      tz_offset_min = None

  report = _jarvis_trade_readiness_report(symbol, timeframe=timeframe, tz_offset_min=tz_offset_min)
  recommendation = report.get('recommendation') if isinstance(report.get('recommendation'), dict) else {}
  action = str(recommendation.get('action') or 'WAIT').upper()

  approval = _jarvis_approval_block(state)
  _jarvis_prune_approval_requests(approval)
  # This endpoint only creates approval requests; it never places an order. The whitelist decides whether the symbol
  # may be traded at all, so a symbol outside it gets no request here and is refused outright by the execute path
  # (execution safety 1b).
  recommend_allowed_symbols = set(approval.get('allowed_symbols') or ['XAUUSD', 'BTCUSD'])
  approval_needed = bool(
    approval.get('require_user_approval', True)
    and symbol in recommend_allowed_symbols
    and action in {'BUY', 'SELL'}
  )

  pending_request = None
  if request_approval and (not session or not session.get('active')):
    return jsonify({'error': 'start an auto-trade session first for approval workflow'}), 400

  if request_approval and approval_needed:
    pending_request = _jarvis_enqueue_approval_request(
      state,
      symbol=symbol,
      side=action,
      readiness=report,
      execution_mode=execution_mode,
      risk_percent=risk_percent,
      lot_size=lot_size,
    )
    save_auto_trader_state(state)

  return jsonify({
    'status': 'ok',
    'recommendation': report,
    'voice_briefing': _jarvis_professional_trade_briefing(report, ask_for_approval=True),
    'requires_user_approval': approval_needed,
    'pending_request': pending_request,
    'session': session,
    'timestamp': datetime.now(timezone.utc).isoformat(),
  })


@app.route('/api/auto-trade/approve', methods=['POST'])
def auto_trade_approve_api():
  payload = request.get_json(silent=True) or request.form.to_dict() or {}
  decision = str(payload.get('decision') or payload.get('action') or 'approve').strip().lower()
  symbol = str(payload.get('symbol') or '').strip().upper() or None
  state = load_auto_trader_state()
  approval = _jarvis_approval_block(state)
  _jarvis_prune_approval_requests(approval)

  request_id = str(payload.get('request_id') or '').strip()
  req = _jarvis_find_approval_request(approval, request_id) if request_id else _jarvis_find_latest_pending_request(approval, symbol=symbol)
  if not req:
    return jsonify({'error': 'no pending approval request found'}), 404

  if decision in {'reject', 'deny', 'cancel'}:
    req['status'] = 'rejected'
    req['decision'] = 'rejected'
  else:
    req['status'] = 'approved'
    req['decision'] = 'approved'
    req['approved_at'] = datetime.now(timezone.utc).isoformat()
    req['expires_at'] = (datetime.now(timezone.utc) + timedelta(minutes=5)).isoformat()

  approval['last_decision'] = req.get('decision')
  approval['last_decision_at'] = datetime.now(timezone.utc).isoformat()
  save_auto_trader_state(state)

  return jsonify({
    'status': 'ok',
    'request': req,
    'approval': approval,
    'message': f"Request {req.get('request_id')} marked as {req.get('status')}.",
  })


@app.route('/api/jarvis/approvals/config', methods=['GET', 'POST'])
def jarvis_approvals_config_api():
  state = load_auto_trader_state()
  approval = _jarvis_approval_block(state)

  if request.method == 'GET':
    return jsonify({'status': 'ok', 'approval': approval})

  payload = request.get_json(silent=True) or request.form.to_dict() or {}
  if 'require_user_approval' in payload:
    approval['require_user_approval'] = bool(payload.get('require_user_approval'))

  if isinstance(payload.get('allowed_symbols'), list):
    allowed = [str(item or '').upper().strip() for item in payload.get('allowed_symbols') if str(item or '').strip()]
    approval['allowed_symbols'] = allowed or ['XAUUSD', 'BTCUSD']

  save_auto_trader_state(state)
  return jsonify({'status': 'saved', 'approval': approval})


def _log_execution_rejection(source: str, symbol: str, http_status: int, body: dict) -> None:
  """Every refused execution is written to data/execution_rejections.jsonl with its reason (execution safety 1)."""
  from src import execution_guard
  body = body if isinstance(body, dict) else {}
  reason = body.get('error') or body.get('reason') or body.get('message') or body.get('status') or 'rejected'
  execution_guard.log_rejection({
    'source': source, 'symbol': symbol, 'http_status': int(http_status), 'reason': str(reason),
    'status': body.get('status'), 'checks': body.get('checks'),
  })
  logger.warning('auto-trade execution rejected [%s] %s %s: %s', source, symbol, http_status, reason)


def _logged_execute(payload: dict, internal_auto_execute: bool, source: str):
  """Run the execution core and log any rejection. 'internal' is decided by the caller in-process, never by a request."""
  payload = {k: v for k, v in dict(payload or {}).items() if k != 'internal_auto_execute'}
  symbol = str(payload.get('symbol') or 'XAUUSD').strip().upper()
  response = _auto_trade_execute_core(payload, internal_auto_execute=internal_auto_execute)
  obj = response[0] if isinstance(response, tuple) else response
  code = response[1] if isinstance(response, tuple) and len(response) > 1 else getattr(obj, 'status_code', 200)
  if int(code) >= 400:
    try:
      body = obj.get_json(silent=True) or {}
    except Exception:
      body = {}
    _log_execution_rejection(source, symbol, int(code), body)
  return response


@app.route('/api/auto-trade/execute', methods=['POST'])
def auto_trade_execute_api():
  """HTTP entry. Requires the control secret (X-Control-Secret, data/control_api.json); a request body can never
  mark itself as the internal autonomy call - 'internal_auto_execute' from any request is ignored."""
  from src import execution_guard
  payload = request.get_json(silent=True) or request.form.to_dict() or {}
  if not execution_guard.secret_matches(request.headers.get(execution_guard.SECRET_HEADER),
                                        execution_guard.load_or_create_secret()):
    body = {'status': 'rejected', 'error': f'missing or wrong control secret ({execution_guard.SECRET_HEADER})'}
    _log_execution_rejection('http', str(payload.get('symbol') or 'XAUUSD').upper(), 403, body)
    return jsonify(body), 403
  return _logged_execute(payload, internal_auto_execute=False, source='http')


def _auto_trade_execute_core(payload: dict, internal_auto_execute: bool = False):
  payload = payload if isinstance(payload, dict) else {}
  state = load_auto_trader_state()
  session = state.get('session') if isinstance(state.get('session'), dict) else None
  if not session or not session.get('active'):
    return jsonify({'error': 'start an auto-trade session first'}), 400

  symbol = str(payload.get('symbol', 'XAUUSD') or 'XAUUSD').strip().upper()
  execution_mode = str(payload.get('execution_mode') or session.get('mode') or 'demo').strip().lower()
  platform = str(session.get('platform') or 'mt5').strip().lower()
  risk_percent = _clamp_float_arg(payload.get('risk_percent') or session.get('risk_percent') or 1.0, default=1.0, low=0.1, high=5.0)
  lot_size = _clamp_float_arg(payload.get('lot_size') or session.get('lot_size') or 0.01, default=0.01, low=0.01, high=5.0)
  # internal_auto_execute is now a parameter set by in-process callers (autonomy loop); it is never read from payload.

  # Validate execution mode
  if execution_mode not in {'demo', 'mt5', 'mt5_live', 'mt4', 'mt4_live'}:
    execution_mode = 'demo'

  if platform == 'mt4' and execution_mode in {'mt5', 'mt5_live'}:
    return jsonify({'error': 'Execution mode MT5 is not valid when session platform is MT4.'}), 400
  if platform == 'mt5' and execution_mode in {'mt4', 'mt4_live'}:
    return jsonify({'error': 'Execution mode MT4 is not valid when session platform is MT5.'}), 400

  if execution_mode in {'mt5', 'mt5_live'}:
    mt5_status = MT5_ENGINE.status()
    if not bool(mt5_status.get('connected')):
      return jsonify({
        'error': 'MT5 bridge not connected. Switch to demo mode or reconnect MT5.',
        'bridge': mt5_status,
      }), 503
  if execution_mode in {'mt4', 'mt4_live'}:
    mt4_status = MT4_ENGINE.status()
    if not bool(mt4_status.get('connected')):
      return jsonify({
        'error': 'MT4 bridge not connected. Switch to demo mode or reconnect MT4 bridge.',
        'bridge': mt4_status,
      }), 503

  signals = build_signal_payload()
  signal_entry = next((item for item in signals if str(item.get('symbol', '')).upper() == symbol), None)
  side = str(signal_entry.get('signal') if signal_entry else '').upper()
  # Refuse rather than default. This previously fell back to 'BUY', so any
  # non-directional reading was executed as a long on a live account.
  if not _is_tradeable_side(side):
    return jsonify({
      'error': 'No tradeable signal for this symbol right now.',
      'symbol': symbol,
      'signal': side or 'UNKNOWN',
      'detail': 'The model is in its neutral band, so no order was placed.',
    }), 409
  confidence = float(signal_entry.get('confidence') if signal_entry else 0.55)

  timeframe = str(payload.get('timeframe', '15m') or '15m').strip().lower()
  tz_offset_raw = payload.get('tz_offset_min')
  tz_offset_min = None
  if tz_offset_raw is not None:
    try:
      tz_offset_min = int(str(tz_offset_raw).strip())
    except Exception:
      tz_offset_min = None

  readiness = _jarvis_trade_readiness_report(symbol, timeframe=timeframe, tz_offset_min=tz_offset_min)
  recommendation = readiness.get('recommendation') if isinstance(readiness.get('recommendation'), dict) else {}
  recommended_action = str(recommendation.get('action') or side or 'WAIT').upper()
  if recommended_action in {'BUY', 'SELL'}:
    side = recommended_action

  controls = _auto_trade_control_block(state)
  if bool(controls.get('block_new_trades', False)):
    return jsonify({
      'status': 'blocked',
      'error': 'Trade control lock is active. New trades are blocked until unlocked.',
    }), 403

  if side == 'BUY' and not bool(controls.get('allow_buy', True)):
    return jsonify({
      'status': 'blocked',
      'error': 'BUY trades are currently blocked by trade controls.',
    }), 400
  if side == 'SELL' and not bool(controls.get('allow_sell', True)):
    return jsonify({
      'status': 'blocked',
      'error': 'SELL trades are currently blocked by trade controls.',
    }), 400

  max_risk = float(controls.get('max_risk_per_trade_pct', 2.0) or 2.0)
  if float(risk_percent) > max_risk:
    return jsonify({
      'status': 'blocked',
      'error': f'risk_percent {risk_percent:.2f}% exceeds hard cap {max_risk:.2f}%.',
    }), 400

  trades = state.get('trades') if isinstance(state.get('trades'), list) else []
  open_trades_count = len([
    t for t in trades
    if str(t.get('status') or '').lower() in {'open', 'sent', 'executed'}
  ])
  max_open_trades = int(controls.get('max_open_trades', 8) or 8)
  if open_trades_count >= max_open_trades:
    return jsonify({
      'status': 'blocked',
      'error': f'Open trade limit reached ({open_trades_count}/{max_open_trades}). Close a trade before opening a new one.',
    }), 400

  max_trades_per_day = int(session.get('max_trades_per_day') or 10)
  today_key = datetime.now(timezone.utc).strftime('%Y-%m-%d')
  today_count = len([
    t for t in trades
    if str(t.get('executed_at') or '').startswith(today_key)
  ])
  if today_count >= max_trades_per_day:
    return jsonify({
      'status': 'blocked',
      'error': f'Max trades/day limit reached ({today_count}/{max_trades_per_day}).',
    }), 400

  starting_balance = float(session.get('starting_balance') or 0.0)
  current_balance = float(session.get('current_balance') or starting_balance or 0.0)
  daily_loss_limit_pct = float(session.get('daily_loss_limit_pct') or 0.0)
  if starting_balance > 0 and daily_loss_limit_pct > 0:
    drawdown_pct = ((starting_balance - current_balance) / starting_balance) * 100.0
    if drawdown_pct >= daily_loss_limit_pct:
      return jsonify({
        'status': 'blocked',
        'error': f'Daily loss guardrail triggered ({drawdown_pct:.2f}% >= {daily_loss_limit_pct:.2f}%).',
      }), 400

  if recommended_action == 'WAIT':
    return jsonify({
      'status': 'blocked',
      'error': f"{symbol} is not a quality entry now. Wait for a better setup.",
      'recommendation': readiness,
    }), 400

  approval = _jarvis_approval_block(state)
  _jarvis_prune_approval_requests(approval)
  allowed_symbols = set(approval.get('allowed_symbols') or ['XAUUSD', 'BTCUSD'])
  # Execution safety 1b: allowed_symbols is the whitelist of what may be traded at all (the TradingView intake reads
  # it the same way). It used to sit inside approval_required, so a symbol outside the list skipped the approval gate
  # completely and went straight to the order. Such a symbol is now refused, for internal callers too.
  if symbol not in allowed_symbols:
    return jsonify({
      'status': 'blocked',
      'error': f"{symbol} is not in the approved symbol list ({', '.join(sorted(allowed_symbols)) or 'none'}).",
      'allowed_symbols': sorted(allowed_symbols),
    }), 403
  approval_required = bool(approval.get('require_user_approval', True) and not internal_auto_execute)

  if approval_required:
    request_id = str(payload.get('approval_request_id') or payload.get('request_id') or '').strip()
    req = _jarvis_find_approval_request(approval, request_id)
    if not req:
      pending_req = _jarvis_enqueue_approval_request(
        state,
        symbol=symbol,
        side=side,
        readiness=readiness,
        execution_mode=execution_mode,
        risk_percent=risk_percent,
        lot_size=lot_size,
      )
      save_auto_trader_state(state)
      return jsonify({
        'status': 'approval_required',
        'message': f"Approval needed before opening a new {symbol} trade.",
        'requires_user_approval': True,
        'pending_request': pending_req,
        'recommendation': readiness,
      }), 202

    req_status = str(req.get('status') or 'pending')
    expires_at = _safe_parse_iso(req.get('expires_at'))
    if req_status != 'approved':
      save_auto_trader_state(state)
      return jsonify({
        'status': 'approval_required',
        'error': f"Request {request_id} is {req_status}. Approve it first.",
        'request': req,
        'recommendation': readiness,
      }), 400
    if expires_at and expires_at < datetime.now(timezone.utc):
      req['status'] = 'expired'
      save_auto_trader_state(state)
      return jsonify({
        'status': 'approval_required',
        'error': f"Request {request_id} expired. Request a new recommendation.",
        'request': req,
        'recommendation': readiness,
      }), 400

  plan = build_live_plan(symbol)

  # Pre-order checks (execution safety 1): fresh closed broker bar, spread vs stop, news window. Missing data rejects.
  from src import execution_guard, economic_calendar
  guard_now = datetime.now(timezone.utc)
  try:
    guard_bars, guard_source = get_bars(symbol, '1h', 60)
  except Exception as exc:
    guard_bars, guard_source = None, f'error: {exc}'
  # Execution safety 2: entry, stop and targets from the broker that fills the order, never from Yahoo.
  if platform == 'mt4' and execution_mode in {'mt4', 'mt4_live'}:
    mt4_symbol = MT4_ENGINE.check_symbol(symbol) if MT4_ENGINE is not None else {'valid': False, 'reason': 'MT4 engine unavailable'}
    guard_quote = {'ok': bool(mt4_symbol.get('valid')), 'bid': mt4_symbol.get('bid'), 'ask': mt4_symbol.get('ask'),
                   'message': mt4_symbol.get('reason')}
    guard_quote_source = f'mt4:{symbol}'
    # The MT4 bridge serves quotes but no bars, so an MT4-only ATR is not available: levels are refused, not mixed.
    level_bars, level_bars_source = None, 'mt4 bridge has no bars'
  else:
    guard_quote = MT5_ENGINE.quote(symbol) if MT5_ENGINE is not None else {'ok': False, 'message': 'MT5 engine unavailable'}
    guard_quote_source = f'mt5:{symbol}'
    level_bars, level_bars_source = guard_bars, guard_source
  broker_levels = execution_guard.broker_trade_levels(
    symbol=symbol, side=side, quote=guard_quote, quote_source=guard_quote_source,
    bars=level_bars, bars_source=level_bars_source,
  )
  if not broker_levels.get('available') or not execution_guard.levels_share_source(broker_levels):
    return jsonify({
      'status': 'blocked',
      'error': 'No broker-priced entry/stop/target: ' + str(broker_levels.get('reason') or 'entry, stop and targets are not from one broker feed'),
      'levels': broker_levels,
    }), 409
  # Execution safety 3: an approved request executes only its exact symbol, side and broker price band.
  approval_request_id = str(payload.get('approval_request_id') or payload.get('request_id') or '').strip()
  if approval_request_id:
    approved_req = _jarvis_find_approval_request(approval, approval_request_id)
    match = execution_guard.approval_matches(approved_req, symbol=symbol, side=side, broker_entry=broker_levels['entry'],
                                             price_source=broker_levels.get('price_source'))
    if not match['ok']:
      if approved_req:
        approved_req['last_mismatch'] = {'at': datetime.now(timezone.utc).isoformat(), 'reason': match['reason'],
                                         'side_now': side, 'broker_entry_now': broker_levels['entry']}
        save_auto_trader_state(state)
      return jsonify({
        'status': 'blocked',
        'error': f"Approval {approval_request_id} does not match this order: {match['reason']}",
        'approval_request_id': approval_request_id,
      }), 409
  try:
    guard_calendar = economic_calendar.load_calendar(guard_now)
  except Exception as exc:
    guard_calendar = {'available': False, 'reason': str(exc)}
  guard_stop_distance = abs(float(broker_levels['entry']) - float(broker_levels['stop_loss']))
  pre_order = execution_guard.pre_order_checks(
    symbol=symbol, now=guard_now, bars=guard_bars, bars_source=guard_source, quote=guard_quote,
    stop_distance=guard_stop_distance, calendar=guard_calendar,
  )
  if not pre_order['ok']:
    return jsonify({
      'status': 'blocked',
      'error': 'Pre-order checks failed: ' + '; '.join(pre_order['reasons']),
      'checks': pre_order['checks'],
    }), 409

  trade_record = {
    'symbol': symbol,
    'side': side,
    'confidence': round(confidence, 3),
    'execution_mode': execution_mode,
    'status': 'queued',
    'executed_at': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
    'entry': broker_levels['entry'],
    'stop_loss': broker_levels['stop_loss'],
    'take_profit': broker_levels['take_profit_1'],
    'price_sources': broker_levels['sources'],
    'display_plan_entry': plan.get('entry'),   # the dashboard plan (Yahoo-based) kept for comparison only
    'risk_percent': round(risk_percent, 2),
    'lot_size': round(lot_size, 3),
    'pnl_pct': None,
    'notes': f"AI signal execution | quality {readiness.get('entry_quality', {}).get('grade', '--')} ({readiness.get('entry_quality', {}).get('score', '--')})",
  }

  http_status = 200

  # Route to appropriate trading engine based on platform
  if platform == 'mt4' and execution_mode in {'mt4', 'mt4_live'}:
    mt4_order = MT4_ENGINE.place_market_order(
      symbol=symbol,
      side=side,
      volume=lot_size,
      stop_loss=float(broker_levels['stop_loss']),
      take_profit=float(broker_levels['take_profit_1']),
      comment='AI Auto Trader',
    )
    trade_record['mt4'] = mt4_order
    trade_record['status'] = 'open' if mt4_order.get('executed') else 'failed'
    trade_record['entry'] = mt4_order.get('entry')
    trade_record['ticket'] = mt4_order.get('ticket')
    trade_record['outcome_source'] = 'broker_fill' if mt4_order.get('executed') else 'broker_rejected'
    message = mt4_order.get('message') or 'MT4 order attempted'
    if not mt4_order.get('executed'):
      http_status = 502
  elif platform == 'mt5' and execution_mode in {'mt5', 'mt5_live'}:
    mt5_order = MT5_ENGINE.place_market_order(
      symbol=symbol,
      side=side,
      volume=lot_size,
      stop_loss=float(broker_levels['stop_loss']),
      take_profit=float(broker_levels['take_profit_1']),
      comment='AI Auto Trader',
    )
    trade_record['mt5'] = mt5_order
    trade_record['status'] = 'open' if mt5_order.get('executed') else 'failed'
    trade_record['ticket'] = (mt5_order.get('result') or {}).get('order') or (mt5_order.get('result') or {}).get('deal')
    trade_record['outcome_source'] = 'broker_fill' if mt5_order.get('executed') else 'broker_rejected'
    message = mt5_order.get('message') or 'MT5 order attempted'
    if not mt5_order.get('executed'):
      http_status = 502
  else:
    # Default to demo simulation
    simulation = simulate_demo_trade(
      symbol=symbol,
      side=side,
      confidence=confidence,
      risk_percent=risk_percent,
    )
    trade_record['entry'] = simulation.get('entry')
    trade_record['pnl_pct'] = simulation.get('pnl_pct')
    trade_record['status'] = simulation.get('outcome')
    # Execution safety item 5: a simulated outcome never feeds the autonomy confidence threshold.
    trade_record['outcome_source'] = 'simulated_demo'
    account_balance = float(session.get('current_balance') or session.get('starting_balance') or 10000)
    session['current_balance'] = round(account_balance * (1 + float(simulation.get('pnl_pct') or 0) / 100), 2)
    message = f"Demo trade {simulation.get('outcome')} with {simulation.get('pnl_pct')}%"

  state['session'] = session
  trades = state.get('trades') if isinstance(state.get('trades'), list) else []
  trades.append(trade_record)
  state['trades'] = trades[-500:]

  approved_request_id = str(payload.get('approval_request_id') or payload.get('request_id') or '').strip()
  if approved_request_id:
    req = _jarvis_find_approval_request(approval, approved_request_id)
    if req:
      req['status'] = 'executed'
      req['executed_at'] = datetime.now(timezone.utc).isoformat()
      req['trade_status'] = trade_record.get('status')

  save_auto_trader_state(state)

  response_payload = {
    'status': 'ok' if http_status == 200 else 'failed',
    'message': message,
    'trade': trade_record,
    'recommendation': readiness,
    'session': state.get('session'),
    'summary': summarize_auto_trader_state(state),
  }
  if http_status != 200:
    response_payload['error'] = message
  return jsonify(response_payload), http_status


@app.route('/api/auto-trade/stop-session', methods=['POST'])
def auto_trade_stop_session_api():
  state = load_auto_trader_state()
  session = state.get('session')
  if session and isinstance(session, dict):
    session['active'] = False
    session['stopped_at'] = datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S')
    state['session'] = session
    save_auto_trader_state(state)
  return jsonify({
    'status': 'ok',
    'message': 'Session stopped',
    'session': state.get('session'),
  })


