@app.route('/tradingview-classic')
def tradingview_classic_page():
  internal_signals = get_internal_signal_map()
  alerts = [build_tradingview_plan(alert, internal_signals) for alert in load_tradingview_alerts()]
  return render_template_string(TRADINGVIEW_TEMPLATE, alerts=alerts, webhook_url=request.url_root.rstrip('/') + '/api/tradingview', theme_css=THEME_CSS)


# TradingView webhook security (13 Sep 2026): every alert must carry a shared secret, created once and
# stored in data/tradingview_webhook.json. The secret is removed before an alert is parsed or stored.
# Alerts are recorded and compared with the model; they never place orders.
TRADINGVIEW_WEBHOOK_CONFIG_PATH = DATA_DIR / "tradingview_webhook.json"
TRADINGVIEW_SECRET_KEYS = ("secret", "passphrase", "token")


def _tradingview_webhook_secret() -> str:
  try:
    config = json.loads(TRADINGVIEW_WEBHOOK_CONFIG_PATH.read_text(encoding="utf-8"))
    if config.get("secret"):
      return str(config["secret"])
  except Exception:
    pass
  import secrets
  secret = secrets.token_urlsafe(18)
  TRADINGVIEW_WEBHOOK_CONFIG_PATH.write_text(json.dumps({
    "secret": secret, "created_at": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")}, indent=1), encoding="utf-8")
  return secret


def _tradingview_message_template(secret: str) -> str:
  return json.dumps({
    "secret": secret, "symbol": "{{ticker}}", "side": "{{strategy.order.action}}", "entry": "{{close}}",
    "stop_loss": 0, "take_profit_1": 0, "confidence": 0.7, "source": "tradingview",
  }, indent=1)


def _store_tradingview_alert(payload: dict) -> dict:
  alert = parse_tradingview_alert(payload)
  internal_signals = get_internal_signal_map()
  plan = build_tradingview_plan(alert, internal_signals)
  alerts = load_tradingview_alerts()
  alerts.append(plan)
  save_tradingview_alerts(alerts[-100:])
  return plan


