@app.route('/api/signals')
def signal_api():
  # Build the live signals first: that records any new ones into the history.
  # The old version returned the stored file whenever it had rows, pushed those
  # rows into the live-signal cache, and rewrote the file with only ten of
  # them - so the history froze and could never grow.
  live = build_signal_payload()
  history = load_signals() or live
  payload = [_enrich_signal_record(signal) for signal in history[-10:]]
  payload = sorted(payload, key=lambda item: float(item.get("strategy_score", 0) or 0), reverse=True)
  return jsonify(payload)


LIVE_SIGNAL_MAX_BAR_AGE_MINUTES = 120  # a closed 1h bar is 60-120 min old when its signal is computed


@app.route('/api/signals/live')
def signal_live_api():
  # Read-only: the live payload (cached ~45 s), not the history file, with each row's signal bar time and age.
  rows = []
  for item in build_signal_payload() or []:
    age = item.get("signal_bar_age_minutes")
    rows.append({
      "symbol": item.get("symbol"),
      "signal": item.get("signal"),
      "ensemble_probability": item.get("ensemble_probability"),
      "signal_bar_time": item.get("signal_bar_time"),
      "signal_bar_age_minutes": age,
      "generated_at": item.get("generated_at"),
      "fresh": bool(item.get("signal_bar_time")) and age is not None and float(age) <= LIVE_SIGNAL_MAX_BAR_AGE_MINUTES,
    })
  return jsonify({
    "signals": rows,
    "all_fresh": bool(rows) and all(row["fresh"] for row in rows),
    "max_bar_age_minutes": LIVE_SIGNAL_MAX_BAR_AGE_MINUTES,
    "checked_at": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S"),
  })


@app.route('/api/quality-monitor')
def quality_monitor_api():
  existing = load_signals() or build_signal_payload()
  enriched = [_enrich_signal_record(signal) for signal in existing[-40:]]
  return jsonify(build_quality_monitor(enriched))


@app.route('/api/quality-retrain', methods=['POST'])
def quality_retrain_api():
  # Retrains: needs the control secret, like /api/train-daily.
  refused = _training_request_refused()
  if refused:
    return refused
  existing = load_signals() or build_signal_payload()
  enriched = [_enrich_signal_record(signal) for signal in existing[-40:]]
  monitor = build_quality_monitor(enriched)
  body = request.get_json(silent=True) or {}
  requested_symbol = str(body.get("symbol", "")).upper().strip()

  if requested_symbol:
    symbol_stat = monitor.get("by_symbol", {}).get(requested_symbol)
    if symbol_stat is None:
      return jsonify({"status": "skipped", "monitor": monitor, "reason": f"No quality stats for {requested_symbol}"})
    if not symbol_stat.get("recommend_retrain"):
      return jsonify({"status": "skipped", "monitor": monitor, "reason": f"{requested_symbol} thresholds not breached"})

  if not monitor.get("recommend_retrain"):
    return jsonify({"status": "skipped", "monitor": monitor, "reason": "Quality thresholds not breached"})

  target_symbols = [requested_symbol] if requested_symbol else monitor.get("recommended_symbols") or ["XAUUSD", "BTCUSD"]
  results = []
  for symbol in target_symbols:
    results.append(DailyLearner(symbol).run_cycle('daily'))
  invalidate_live_caches()
  return jsonify({"status": "retrained", "monitor": monitor, "results": results})


