SHADOW_SIMULATION_CACHE_TTL_SECONDS = 300
_shadow_simulation_cache = {"value": None, "expires_at": 0.0}


@app.route('/api/shadow-simulation')
def shadow_simulation_api():
    # Each run scores every entry through RF+LSTM for both symbols (~15s). The
    # inputs are hourly bars, so a five-minute cache never hides a new bar.
    if not _cache_is_valid(_shadow_simulation_cache):
        _shadow_simulation_cache["value"] = [build_shadow_simulation(symbol) for symbol in ["XAUUSD", "BTCUSD"]]
        _shadow_simulation_cache["expires_at"] = monotonic() + SHADOW_SIMULATION_CACHE_TTL_SECONDS
    return jsonify(_shadow_simulation_cache["value"])


# ===================== Pipeline pages =====================
# /pipeline           live signal pipeline, traced stage by stage (read-only)
# /pipeline/training  walk-forward training & backtest pipeline (evaluation-only)

PIPELINE_TRACE_TTL_SECONDS = 60
_pipeline_trace_cache: dict[str, dict] = {}
_pipeline_trace_lock = threading.Lock()


def _pipeline_stage(key: str, title: str, status: str, started: float, facts=None, detail=None) -> dict:
  from time import perf_counter
  return {
    'key': key,
    'title': title,
    'status': status,
    'ms': int(round((perf_counter() - started) * 1000)),
    'facts': facts or {},
    'detail': detail,
  }


def build_live_pipeline_trace(symbol: str) -> dict:
  """Walk one symbol through the live signal pipeline and report every stage.

  Read-only. It calls the same helpers the live signal path uses (data fetch,
  build_features, the RF and LSTM models, _classify_signal, build_live_plan,
  the risk guardrails and the autonomy/bridge state) and never places,
  modifies or queues an order.
  """
  from time import perf_counter
  import pandas as pd
  from src.data import YAHOO_TICKERS as SRC_YAHOO_TICKERS

  symbol = symbol.upper()
  stages: list[dict] = []
  models_dir = Path(__file__).resolve().parent / 'models'

  def skipped(key, title, reason):
    stages.append({'key': key, 'title': title, 'status': 'skipped', 'ms': None, 'facts': {}, 'detail': reason})

  # 1. Market data
  t = perf_counter()
  data = None
  try:
    data = fetch_real_data(symbol, period="120d", interval="1h")
    source = data.attrs.get('source', 'unknown') if data is not None else 'none'
    if data is None or data.empty:
      stages.append(_pipeline_stage('data', 'Market data', 'error', t, {'source': source}, 'No bars returned.'))
      data = None
    else:
      last_time = pd.Timestamp(data['datetime'].iloc[-1])
      if last_time.tzinfo is None:
        last_time = last_time.tz_localize('UTC')
      age_min = int((datetime.now(timezone.utc) - last_time.to_pydatetime()).total_seconds() // 60)
      facts = {
        'source': source,
        'ticker': SRC_YAHOO_TICKERS.get(symbol, symbol),
        'bars': int(len(data)),
        'last_bar_utc': last_time.strftime('%Y-%m-%d %H:%M'),
        'bar_age_min': age_min,
        'last_close': round(float(data['close'].iloc[-1]), 2),
      }
      status, detail = 'ok', None
      if source == 'synthetic':
        status = 'error'
        detail = 'Yahoo returned nothing, so the pipeline is running on generated prices. Signals from this run are not trustworthy.'
      elif age_min > 180:
        status = 'warn'
        detail = 'Latest bar is over 3 hours old: the market is closed or the feed is stale.'
      if symbol == 'XAUUSD' and status != 'error':
        detail = (detail + ' ' if detail else '') + 'Gold history uses the GC=F future, about 1.4% from broker spot.'
      stages.append(_pipeline_stage('data', 'Market data', status, t, facts, detail))
  except Exception as exc:
    stages.append(_pipeline_stage('data', 'Market data', 'error', t, {}, f'{type(exc).__name__}: {exc}'))
    data = None

  # 2. Features
  features = None
  if data is None:
    skipped('features', 'Features', 'No market data.')
  else:
    t = perf_counter()
    try:
      features = build_features(data)
      missing = [c for c in FEATURE_COLUMNS if c not in features.columns]
      if features.empty or missing:
        stages.append(_pipeline_stage('features', 'Features', 'error', t, {'rows': int(len(features)), 'missing': missing},
                                      'Feature frame is empty or missing model columns.'))
        features = None
      else:
        last = features.iloc[-1]
        nan_cols = [c for c in FEATURE_COLUMNS if pd.isna(last.get(c))]
        stages.append(_pipeline_stage('features', 'Features', 'warn' if nan_cols else 'ok', t, {
          'rows': int(len(features)),
          'model_columns': len(FEATURE_COLUMNS),
          'rsi_14': round(float(last['rsi_14']), 1),
          'volatility_5d_pct': round(float(last['volatility_5d']) * 100, 3),
          'trend_5 / trend_20': f"{int(last['trend_5'])} / {int(last['trend_20'])}",
        }, f'NaN in latest row: {nan_cols}' if nan_cols else None))
    except Exception as exc:
      stages.append(_pipeline_stage('features', 'Features', 'error', t, {}, f'{type(exc).__name__}: {exc}'))
      features = None

  # 3. Random forest
  rf_probability = None
  if features is None:
    skipped('rf', 'Random forest model', 'No features.')
  else:
    t = perf_counter()
    try:
      clf = load_model(symbol)
      metrics = load_metrics(symbol) or {}
      model_path = models_dir / f'{symbol.lower()}_model.joblib'
      if clf is None:
        stages.append(_pipeline_stage('rf', 'Random forest model', 'error', t, {'model_file': model_path.name},
                                      'No trained RF model on disk.'))
      else:
        latest = features.iloc[-1:]
        if hasattr(clf, 'predict_proba'):
          rf_probability = float(clf.predict_proba(latest[FEATURE_COLUMNS])[0, 1])
        else:
          rf_probability = float(clf.predict(latest[FEATURE_COLUMNS])[0])
        accuracy = metrics.get('accuracy')
        trained = datetime.fromtimestamp(model_path.stat().st_mtime).strftime('%Y-%m-%d %H:%M') if model_path.exists() else None
        stages.append(_pipeline_stage('rf', 'Random forest model',
                                      'warn' if accuracy is not None and accuracy < 0.52 else 'ok', t, {
          'rf_probability': round(rf_probability, 4),
          'test_accuracy': round(float(accuracy), 3) if accuracy is not None else None,
          'calibrated': bool(metrics.get('calibration_enabled')),
          'model_saved': trained,
        }, 'Accuracy under 52%: barely better than a coin flip.' if accuracy is not None and accuracy < 0.52 else None))
    except Exception as exc:
      stages.append(_pipeline_stage('rf', 'Random forest model', 'error', t, {}, f'{type(exc).__name__}: {exc}'))

  # 4. LSTM
  lstm_probability = None
  if data is None:
    skipped('lstm', 'LSTM model', 'No market data.')
  else:
    t = perf_counter()
    lstm_metrics = load_lstm_metrics(symbol) or {}
    scaler_path = models_dir / f'{symbol.lower()}_lstm_scaler.joblib'
    facts = {
      'scaler_saved': scaler_path.exists(),
      'test_accuracy': round(float(lstm_metrics['accuracy']), 3) if lstm_metrics.get('accuracy') is not None else None,
      'trained_at': lstm_metrics.get('trained_at'),
    }
    try:
      lstm_probability = LSTMTrader(symbol).predict(data)
      if lstm_probability is None:
        stages.append(_pipeline_stage('lstm', 'LSTM model', 'warn', t, facts, 'LSTM returned no prediction.'))
      else:
        lstm_probability = float(lstm_probability)
        facts = {'lstm_probability': round(lstm_probability, 4), **facts}
        weak = facts['test_accuracy'] is not None and facts['test_accuracy'] < 0.52
        stages.append(_pipeline_stage('lstm', 'LSTM model', 'warn' if weak else 'ok', t, facts,
                                      'Accuracy under 52%.' if weak else None))
    except Exception as exc:
      stages.append(_pipeline_stage('lstm', 'LSTM model', 'error', t, facts, f'{type(exc).__name__}: {exc}'))

  # 5. Ensemble and classification
  ensemble_probability = None
  signal_side = 'HOLD'
  if rf_probability is None:
    skipped('ensemble', 'Ensemble & signal', 'No RF probability.')
  else:
    t = perf_counter()
    if lstm_probability is not None:
      ensemble_probability = round((rf_probability + lstm_probability) / 2, 4)
    else:
      ensemble_probability = round(rf_probability, 4)
    signal_side = _classify_signal(ensemble_probability)
    status = 'ok' if _is_tradeable_side(signal_side) else 'hold'
    if lstm_probability is None:
      status = 'warn'
    stages.append(_pipeline_stage('ensemble', 'Ensemble & signal', status, t, {
      'ensemble_probability': ensemble_probability,
      'formula': '50% RF + 50% LSTM' if lstm_probability is not None else 'RF only (LSTM missing)',
      'buy_at_or_above': SIGNAL_BUY_THRESHOLD,
      'sell_at_or_below': SIGNAL_SELL_THRESHOLD,
      'signal': signal_side,
    }, 'Probability is inside the neutral band: no directional edge, so no trade.' if signal_side == 'HOLD' else None))

  # 6. Live signal record (the cached payload every page reads)
  t = perf_counter()
  live_signal = {}
  try:
    live_signal = next((s for s in build_signal_payload() if str(s.get('symbol') or '').upper() == symbol), {}) or {}
    history_rows = [row for row in (load_signals() or []) if str(row.get('symbol') or '').upper() == symbol]
    last_row = history_rows[-1] if history_rows else {}
    mismatch = []
    if live_signal and ensemble_probability is not None:
      if str(live_signal.get('signal') or '').upper() != signal_side:
        mismatch.append(f"cached side {live_signal.get('signal')} vs traced {signal_side}")
      live_prob = live_signal.get('ensemble_probability')
      if live_prob is not None and abs(float(live_prob) - ensemble_probability) > 0.02:
        mismatch.append(f'cached probability {live_prob} vs traced {ensemble_probability}')
    stages.append(_pipeline_stage('record', 'Live signal & history', 'warn' if mismatch or not live_signal else 'ok', t, {
      'live_signal': live_signal.get('signal'),
      'confidence': live_signal.get('confidence'),
      'strategy_grade': live_signal.get('strategy_grade'),
      'generated_utc': live_signal.get('generated_at'),
      'last_history_row': last_row.get('generated_at'),
      'history_rows': len(history_rows),
    }, ('; '.join(mismatch) + ' (the live cache refreshes every ~45s).') if mismatch else (None if live_signal else 'No live signal in the payload.')))
  except Exception as exc:
    stages.append(_pipeline_stage('record', 'Live signal & history', 'error', t, {}, f'{type(exc).__name__}: {exc}'))

  # 7. Trade plan
  t = perf_counter()
  plan = {}
  try:
    plan = build_live_plan(symbol) or {}
    if not _is_tradeable_side(plan.get('signal')):
      stages.append(_pipeline_stage('plan', 'Trade plan', 'hold', t, {'entry_reference': plan.get('entry'), 'levels': 'none'},
                                    'HOLD never produces stop or target levels.'))
    else:
      rr = plan.get('risk_reward')
      stages.append(_pipeline_stage('plan', 'Trade plan', 'ok' if rr is not None and rr >= 1.5 else 'warn', t, {
        'side': plan.get('signal'),
        'entry': plan.get('entry'),
        'stop_loss': plan.get('stop_loss'),
        'take_profit_1': plan.get('take_profit_1'),
        'risk_reward': rr,
        'grade': plan.get('grade'),
      }, None if rr is not None and rr >= 1.5 else 'Risk:reward below 1.5 fails the smart-entry rule.'))
  except Exception as exc:
    stages.append(_pipeline_stage('plan', 'Trade plan', 'error', t, {}, f'{type(exc).__name__}: {exc}'))

  # 8. Risk guardrails
  t = perf_counter()
  state = {}
  guard = {}
  confidence = float(live_signal.get('confidence') or plan.get('confidence') or 0.0)
  try:
    state = load_auto_trader_state()
    guard = _build_soft_risk_guardrails(state, symbol, confidence, ensemble_probability if ensemble_probability is not None else 0.5)
    stages.append(_pipeline_stage('risk', 'Risk guardrails', 'warn' if guard.get('warnings') else 'ok', t, {
      'recommended_risk_pct': guard.get('recommended_risk_pct'),
      'max_risk_pct': guard.get('max_risk_per_trade_pct'),
      'open_trades': f"{guard.get('open_trades')} / {guard.get('max_open_trades')}",
    }, ' '.join(guard.get('warnings') or []) or None))
  except Exception as exc:
    stages.append(_pipeline_stage('risk', 'Risk guardrails', 'error', t, {}, f'{type(exc).__name__}: {exc}'))

  # 9. Execution gate (reported, never acted on)
  t = perf_counter()
  blockers: list[str] = []
  try:
    autonomy = _jarvis_autonomy_block(state or load_auto_trader_state())
    try:
      mt4 = MT4_ENGINE.status() if MT4_ENGINE else {}
    except Exception as exc:
      mt4 = {'connected': False, 'message': str(exc)}
    try:
      mt5 = MT5_ENGINE.status() if MT5_ENGINE else {}
    except Exception as exc:
      mt5 = {'connected': False, 'message': str(exc)}
    min_conf = float(autonomy.get('min_confidence_pct') or 0.0)
    if not _is_tradeable_side(signal_side):
      blockers.append('signal is HOLD')
    if not autonomy.get('enabled'):
      blockers.append('autonomy is disabled')
    if not autonomy.get('auto_execute'):
      blockers.append('auto-execute is off')
    if confidence * 100 < min_conf:
      blockers.append(f'confidence {confidence * 100:.0f}% is below the {min_conf:.0f}% autonomy minimum')
    if guard.get('warnings'):
      blockers.append('risk guardrail warnings')
    if not (mt4.get('connected') or mt5.get('connected')):
      blockers.append('no broker bridge connected')
    stages.append(_pipeline_stage('execution', 'Execution gate', 'blocked' if blockers else 'ready', t, {
      'autonomy': 'on' if autonomy.get('enabled') else 'off',
      'auto_execute': 'on' if autonomy.get('auto_execute') else 'off',
      'min_confidence_pct': min_conf,
      'mt4_bridge': f"connected ({mt4.get('account')})" if mt4.get('connected') else 'disconnected',
      'mt5_bridge': 'connected' if mt5.get('connected') else 'disconnected',
    }, 'Blocked by: ' + '; '.join(blockers) if blockers else 'All gates pass.'))
  except Exception as exc:
    blockers.append('execution gate could not be evaluated')
    stages.append(_pipeline_stage('execution', 'Execution gate', 'error', t, {}, f'{type(exc).__name__}: {exc}'))

  if blockers:
    decision = f'No order would be placed for {symbol}: ' + '; '.join(blockers) + '.'
  else:
    decision = f'All gates pass for {symbol}: autonomy is allowed to place this order. This page never does.'
  return {
    'symbol': symbol,
    'generated_at': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
    'read_only': True,
    'stages': stages,
    'summary': {'signal': signal_side, 'would_execute': not blockers, 'decision': decision, 'blockers': blockers},
  }


def get_live_pipeline_trace(symbol: str, refresh: bool = False) -> dict:
  symbol = symbol.upper()
  with _pipeline_trace_lock:
    entry = _pipeline_trace_cache.get(symbol)
    if entry and not refresh and _cache_is_valid(entry):
      return {**entry['value'], 'cached': True}
  trace = build_live_pipeline_trace(symbol)
  with _pipeline_trace_lock:
    _pipeline_trace_cache[symbol] = {'value': trace, 'expires_at': monotonic() + PIPELINE_TRACE_TTL_SECONDS}
  return {**trace, 'cached': False}


@app.route('/api/pipeline/live')
def pipeline_live_api():
  requested = str(request.args.get('symbol') or '').upper()
  symbols = [requested] if requested in {'XAUUSD', 'BTCUSD'} else ['XAUUSD', 'BTCUSD']
  refresh = str(request.args.get('refresh') or '') in {'1', 'true', 'yes'}
  return jsonify([get_live_pipeline_trace(symbol, refresh=refresh) for symbol in symbols])


BACKTEST_RUNS_PATH = DATA_DIR / "backtest_runs.json"
_backtest_jobs: dict[str, dict] = {}
_backtest_jobs_lock = threading.Lock()


def _load_backtest_runs() -> list:
  if BACKTEST_RUNS_PATH.exists():
    try:
      runs = json.loads(BACKTEST_RUNS_PATH.read_text(encoding="utf-8"))
      return runs if isinstance(runs, list) else []
    except ValueError:
      return []
  return []


def _append_backtest_run(result: dict) -> None:
  """Every run is kept (append-only) so results stay comparable over time."""
  with _backtest_jobs_lock:
    runs = _load_backtest_runs()
    runs.append(result)
    tmp_path = BACKTEST_RUNS_PATH.with_name(BACKTEST_RUNS_PATH.name + ".tmp")
    tmp_path.write_text(json.dumps(runs, indent=1), encoding="utf-8")
    os.replace(tmp_path, BACKTEST_RUNS_PATH)


def _backtest_comparison(symbol: str, result: dict) -> dict:
  live = get_model_status(symbol)
  oos = (result.get('metrics') or {}).get('oos_direction_accuracy')
  live_acc = live.get('accuracy')
  metrics = result.get('metrics') or {}
  profit_factor = metrics.get('profit_factor')
  total_return = metrics.get('total_return_pct')
  if result.get('evidence') != 'sufficient':
    verdict = 'Insufficient evidence: too few out-of-sample trades to judge the strategy.'
  elif (profit_factor is not None and profit_factor < 1) or (total_return is not None and total_return < 0):
    # Accuracy alone read as good news next to a -60% run; lead with the money.
    verdict = (f'The strategy loses money out of sample (profit factor {profit_factor}, return {total_return}%), '
               'whatever its direction accuracy. Do not enable autonomous trading on it.')
  elif oos is None or live_acc is None:
    verdict = 'Cannot compare: an accuracy figure is missing.'
  elif oos + 1e-9 >= float(live_acc):
    verdict = "Walk-forward accuracy is at or above the live model's reported test accuracy."
  else:
    verdict = "Walk-forward accuracy is below the live model's reported test accuracy."
  return {
    'live_rf_accuracy': live_acc,
    'live_lstm_accuracy': live.get('lstm_accuracy'),
    'backtest_oos_accuracy': oos,
    'verdict': verdict,
    'note': ("The live model's figure comes from one 80/20 split on about 120 days of hourly bars; "
             "the walk-forward figure covers every out-of-sample fold, so it is the more conservative number."),
  }


def _execute_backtest(job_id: str, symbol: str, range_key: str, progress) -> dict:
  result = run_walkforward_backtest(symbol, range_key, buy_threshold=SIGNAL_BUY_THRESHOLD,
                                    sell_threshold=SIGNAL_SELL_THRESHOLD, progress=progress)
  if result.get('available'):
    progress('compare', 97, 'Comparing with the live model')
    result['comparison'] = _backtest_comparison(symbol, result)
    result['promotion'] = {
      'automatic': False,
      'note': ('Walk-forward models are evaluation-only and are never saved. To change the live model, '
               'retrain it, then run this backtest again and confirm it is better on the agreed metric '
               'and not worse on drawdown before relying on it.'),
    }
  result['job_id'] = job_id
  _append_backtest_run(result)
  return result


def _run_backtest_job(job_id: str, symbol: str, range_key: str, combos=None) -> None:
  """Run one backtest, or a queued batch (both symbols and/or every range)."""
  combos = list(combos or [(symbol, range_key)])

  with _backtest_jobs_lock:
    _backtest_jobs[job_id].update({'status': 'running'})
  try:
    results = []
    for index, (combo_symbol, combo_range) in enumerate(combos):
      def progress(stage, pct, message, _index=index, _symbol=combo_symbol, _range=combo_range):
        overall = int((_index + pct / 100.0) / len(combos) * 100)
        text = f'[{_index + 1}/{len(combos)} {_symbol} {_range}] {message}' if len(combos) > 1 else message
        with _backtest_jobs_lock:
          job = _backtest_jobs.get(job_id)
          if job:
            job.update({'stage': stage, 'pct': overall, 'message': text})
      results.append(_execute_backtest(job_id, combo_symbol, combo_range, progress))
    available = [r for r in results if r.get('available')]
    shown = available[-1] if available else results[-1]
    batch = [{
      'symbol': r.get('symbol'), 'range': r.get('range'), 'available': r.get('available'), 'reason': r.get('reason'),
      'trades': (r.get('metrics') or {}).get('trades'), 'win_rate_pct': (r.get('metrics') or {}).get('win_rate_pct'),
      'profit_factor': (r.get('metrics') or {}).get('profit_factor'),
      'max_drawdown_pct': (r.get('metrics') or {}).get('max_drawdown_pct'),
      'total_return_pct': (r.get('metrics') or {}).get('total_return_pct'), 'evidence': r.get('evidence'),
    } for r in results]
    with _backtest_jobs_lock:
      _backtest_jobs[job_id].update({
        'status': 'done' if available else 'unavailable',
        'stage': 'done', 'pct': 100,
        'message': (f'Complete ({len(available)}/{len(results)} runs had data)' if len(results) > 1 else 'Complete')
                   if available else shown.get('reason'),
        'finished_at': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
        'result': shown,
        'batch': batch,
      })
  except Exception as exc:
    logging.getLogger(__name__).exception("backtest job failed")
    with _backtest_jobs_lock:
      _backtest_jobs[job_id].update({
        'status': 'error', 'message': f'{type(exc).__name__}: {exc}',
        'finished_at': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
      })


@app.route('/api/pipeline/backtest/run', methods=['POST'])
def pipeline_backtest_run_api():
  if not WALKFORWARD_AVAILABLE:
    return jsonify({'started': False, 'available': False, 'reason': 'walk-forward backtest module failed to import'}), 200
  payload = request.get_json(silent=True) or {}
  symbol = str(payload.get('symbol') or '').upper()
  range_key = str(payload.get('range') or '')
  if range_key.upper() == 'ALL':
    range_key = 'ALL'
  if symbol not in {'XAUUSD', 'BTCUSD', 'ALL'} or (range_key not in BACKTEST_RANGES and range_key != 'ALL'):
    return jsonify({'started': False, 'reason': 'symbol must be XAUUSD, BTCUSD or ALL and range one of ' + ', '.join(list(BACKTEST_RANGES) + ['ALL'])}), 400
  combos = [
    (combo_symbol, combo_range)
    for combo_symbol in (['XAUUSD', 'BTCUSD'] if symbol == 'ALL' else [symbol])
    for combo_range in (list(BACKTEST_RANGES) if range_key == 'ALL' else [range_key])
  ]
  with _backtest_jobs_lock:
    running = [job for job in _backtest_jobs.values() if job.get('status') in {'queued', 'running'}]
    if running:
      return jsonify({'started': False, 'reason': 'a backtest is already running', 'job_id': running[0]['id']}), 409
    job_id = datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S') + '-' + symbol + '-' + range_key
    _backtest_jobs[job_id] = {
      'id': job_id, 'symbol': symbol, 'range': range_key, 'status': 'queued', 'stage': 'queued', 'pct': 0,
      'message': 'Queued', 'started_at': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
    }
  threading.Thread(target=_run_backtest_job, args=(job_id, symbol, range_key, combos), daemon=True, name=f'backtest-{job_id}').start()
  return jsonify({'started': True, 'job_id': job_id}), 202


@app.route('/api/pipeline/backtest/status')
def pipeline_backtest_status_api():
  job_id = str(request.args.get('job_id') or '')
  with _backtest_jobs_lock:
    if job_id and job_id in _backtest_jobs:
      return jsonify(dict(_backtest_jobs[job_id]))
    if _backtest_jobs:
      latest = sorted(_backtest_jobs.values(), key=lambda job: job.get('started_at') or '')[-1]
      return jsonify(dict(latest))
  return jsonify({'status': 'idle'})


@app.route('/api/pipeline/backtest/runs')
def pipeline_backtest_runs_api():
  limit = _clamp_int_arg(request.args.get('limit'), 10, 1, 50)
  return jsonify(list(reversed(_load_backtest_runs()[-limit:])))


@app.route('/api/pipeline/training-status')
def pipeline_training_status_api():
  keep = ('symbol', 'model_loaded', 'accuracy', 'lstm_accuracy', 'lstm_last_trained_at', 'rf_precision', 'rf_recall', 'rf_f1')
  models = []
  for symbol in ['XAUUSD', 'BTCUSD']:
    status = get_model_status(symbol)
    metrics = load_metrics(symbol) or {}
    model_path = Path(__file__).resolve().parent / 'models' / f'{symbol.lower()}_model.joblib'
    row = {key: status.get(key) for key in keep}
    row['cv_accuracy_mean'] = metrics.get('cv_accuracy_mean')
    row['rf_saved_at'] = datetime.fromtimestamp(model_path.stat().st_mtime).strftime('%Y-%m-%d %H:%M') if model_path.exists() else None
    models.append(row)
  history = {symbol: {'daily': load_daily_history(symbol)[-8:], 'weekly': load_weekly_history(symbol)[-8:]} for symbol in ['XAUUSD', 'BTCUSD']}
  return jsonify({
    'walkforward_available': WALKFORWARD_AVAILABLE,
    'models': models,
    'history': history,
    'ranges': {key: spec.get('label') for key, spec in BACKTEST_RANGES.items()},
    'costs': BACKTEST_COSTS,
    'min_trades_for_evidence': MIN_TRADES_FOR_EVIDENCE,
    'thresholds': {'buy': SIGNAL_BUY_THRESHOLD, 'sell': SIGNAL_SELL_THRESHOLD},
  })


@app.route('/api/pipeline/learning-decisions')
def pipeline_learning_decisions_api():
  try:
    from src.model_promotion import load_decisions
  except Exception as exc:
    return jsonify({'available': False, 'reason': f'{type(exc).__name__}: {exc}', 'decisions': []})
  limit = _clamp_int_arg(request.args.get('limit'), 12, 1, 100)
  return jsonify({'available': True, 'decisions': list(reversed(load_decisions(limit)))})


