# Paper trading (forward test) of the gold 4h research model. The cycle itself runs in a
# separate process (scripts/run_paper_trader.cmd, scheduled hourly as "SmartEntry Paper
# Trader"), so model training never loads into the app. Nothing here reaches an order path.
_APP_DIR = os.path.dirname(os.path.abspath(__file__))
PAPER_TRADING_STATE_FILE = os.path.join(_APP_DIR, 'data', 'paper_trading', 'xauusd_4h_mtf_xgb_tight_q90.json')
PAPER_TRADING_RUNNER = os.path.join(_APP_DIR, 'scripts', 'run_paper_trader.cmd')
PAPER_TRADING_RUN_COOLDOWN_SECONDS = 180
_paper_trading_run_started = {'at': None}


def _paper_trading_running() -> bool:
  started = _paper_trading_run_started['at']
  return started is not None and monotonic() - started < PAPER_TRADING_RUN_COOLDOWN_SECONDS


@app.route('/api/paper-trading')
def paper_trading_api():
  """Forward-test record of the gold 4h research model (read-only; paper trades are never sent)."""
  if not os.path.exists(PAPER_TRADING_STATE_FILE):
    return jsonify({'available': False, 'places_orders': False,
                    'reason': 'No paper-trading check has run yet. The hourly task "SmartEntry Paper Trader" creates it.'})
  try:
    with open(PAPER_TRADING_STATE_FILE, 'r', encoding='utf-8') as handle:
      state = json.load(handle)
  except Exception as exc:
    return jsonify({'available': False, 'places_orders': False, 'reason': f'Could not read the paper-trading file: {exc}'})
  try:
    from src.paper_trader import summarize as paper_trading_summary
    summary = paper_trading_summary(state)
  except Exception as exc:
    summary = {'error': f'summary unavailable: {exc}', 'last_run': state.get('last_run'),
               'last_error': state.get('last_error'), 'metrics': {'trades': len(state.get('closed_trades') or [])}}
  return jsonify({
    'available': True,
    'places_orders': False,
    'running': _paper_trading_running(),
    'summary': summary,
    'setup': state.get('setup'),
    'open_trade': state.get('open_trade'),
    'closed_trades': list(reversed(state.get('closed_trades') or [])),
    'decisions': list(reversed(state.get('decisions') or []))[:120],
  })


@app.route('/api/paper-trading/run', methods=['POST'])
def paper_trading_run_api():
  """Start one paper-trading check in its own process - the same script the hourly task runs. No orders."""
  if _paper_trading_running():
    return jsonify({'started': False, 'reason': 'A check started less than 3 minutes ago; results appear shortly.'}), 429
  if not os.path.exists(PAPER_TRADING_RUNNER):
    return jsonify({'started': False, 'reason': 'scripts/run_paper_trader.cmd is missing.'}), 404
  import subprocess
  try:
    subprocess.Popen(['cmd', '/c', PAPER_TRADING_RUNNER], cwd=_APP_DIR,
                     creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
  except Exception as exc:
    return jsonify({'started': False, 'reason': f'Could not start the check: {exc}'}), 500
  _paper_trading_run_started['at'] = monotonic()
  return jsonify({'started': True, 'message': 'Check started. Results appear in about a minute.'})


