# Daily Report (src/daily_report.py): market analysis for gold and bitcoin plus the system brief and
# the daily schedule, written every morning by the task "SmartEntry Daily Report". Read-only here.
DAILY_REPORT_DIR = os.path.join(_APP_DIR, 'data', 'daily_reports')
DAILY_REPORT_RUNNER = os.path.join(_APP_DIR, 'scripts', 'run_daily_report.cmd')
_daily_report_run_started = {'at': None}


@app.route('/api/daily-report')
def daily_report_api():
  import re as _re
  requested = str(request.args.get('date') or '').strip()
  if requested and not _re.fullmatch(r'\d{4}-\d{2}-\d{2}', requested):
    return jsonify({'available': False, 'reason': 'date must look like YYYY-MM-DD'}), 400
  name = f'{requested}.json' if requested else 'latest.json'
  try:
    dates = sorted((f[:-5] for f in os.listdir(DAILY_REPORT_DIR) if _re.fullmatch(r'\d{4}-\d{2}-\d{2}\.json', f)), reverse=True)
  except OSError:
    dates = []
  try:
    with open(os.path.join(DAILY_REPORT_DIR, name), 'r', encoding='utf-8') as handle:
      report = json.load(handle)
  except Exception:
    return jsonify({'available': False, 'dates': dates,
                    'reason': 'No daily report yet. It is written every day at 06:45 (task "SmartEntry Daily Report").'})
  started = _daily_report_run_started['at']
  return jsonify({'available': True, 'places_orders': False, 'dates': dates[:60], 'report': report,
                  'running': started is not None and monotonic() - started < 180})


@app.route('/api/daily-report/run', methods=['POST'])
def daily_report_run_api():
  """Write a fresh report now in its own process (the same script the 06:45 task runs)."""
  started = _daily_report_run_started['at']
  if started is not None and monotonic() - started < 180:
    return jsonify({'started': False, 'reason': 'A report was started less than 3 minutes ago.'}), 429
  if not os.path.exists(DAILY_REPORT_RUNNER):
    return jsonify({'started': False, 'reason': 'scripts/run_daily_report.cmd is missing.'}), 404
  import subprocess
  try:
    subprocess.Popen(['cmd', '/c', DAILY_REPORT_RUNNER], cwd=_APP_DIR, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
  except Exception as exc:
    return jsonify({'started': False, 'reason': f'Could not start the report: {exc}'}), 500
  _daily_report_run_started['at'] = monotonic()
  return jsonify({'started': True, 'message': 'Report started. It appears in about a minute.'})


