# AI Employee (src/ai_employee.py): a daily read-only Claude Code review on the owner's subscription (task
# "SmartEntry AI Employee", 07:15). The page shows its brief, its proposals (the owner approves or rejects them) and
# its memory. Nothing here trades, changes settings or edits code.
AI_EMPLOYEE_DIR = os.path.join(_APP_DIR, 'data', 'ai_employee')
_ai_employee_run_started = {'at': None}

AI_EMPLOYEE_TEMPLATE = r"""
<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width, initial-scale=1'>
  <title>AI Employee</title>
  {{ theme_css | safe }}
  <style>
    .emp-head { display:flex; flex-wrap:wrap; justify-content:space-between; align-items:flex-end; gap:12px; }
    .chip { display:inline-block; padding:3px 10px; border-radius:999px; font-size:12px; font-weight:700; border:1px solid; white-space:nowrap; }
    .chip.up { color:#a7f3d0; border-color:rgba(52,211,153,.6); background:rgba(52,211,153,.14); }
    .chip.down { color:#fecdd3; border-color:rgba(251,113,133,.6); background:rgba(251,113,133,.14); }
    .chip.mixed { color:#fde68a; border-color:rgba(251,191,36,.6); background:rgba(251,191,36,.14); }
    .chip.src { color:#e0f2fe; border-color:rgba(56,189,248,.55); background:rgba(56,189,248,.12); font-weight:600; }
    .brief-summary { font-size:16px; line-height:1.65; color:#e2e8f0; margin:10px 0 4px; }
    .muted-small { font-size:12px; color:#94a3b8; }
    .grid2 { display:grid; grid-template-columns:repeat(auto-fit, minmax(min(420px, 100%), 1fr)); gap:18px; }
    .finding { border:1px solid rgba(148,176,222,.22); border-left:3px solid #38bdf8; border-radius:10px; padding:10px 12px; margin:8px 0; background:rgba(2,8,18,.35); }
    .finding.warn { border-left-color:#f59e0b; }
    .finding.problem { border-left-color:#fb7185; }
    .finding .ev { font-size:12px; color:#94a3b8; margin-top:4px; }
    .proposal { border:1px solid rgba(148,176,222,.22); border-radius:12px; padding:12px 14px; margin:10px 0; background:rgba(2,8,18,.35); }
    .proposal h3 { margin:0 0 6px; font-size:15px; color:#f1f5f9; }
    .proposal .row { display:grid; grid-template-columns:130px 1fr; gap:8px; font-size:13px; padding:3px 0; }
    .proposal .row span:first-child { color:#94a3b8; }
    .proposal .actions { display:flex; gap:8px; flex-wrap:wrap; margin-top:10px; }
    .proposal .actions button { padding:6px 12px; font-size:12px; }
    .proposal .flag { color:#fcd34d; font-size:12px; font-weight:700; margin:4px 0; }
    .tabs { display:flex; gap:8px; flex-wrap:wrap; margin:6px 0 4px; }
    .tabs button { padding:6px 12px; font-size:12px; background:rgba(51,65,85,.6); }
    .tabs button.active { background:linear-gradient(135deg, #0ea5e9, #0284c7); }
    button.ok-btn { background:linear-gradient(135deg, #22c55e, #16a34a); }
    button.no-btn { background:linear-gradient(135deg, #f87171, #dc2626); }
    button.done-btn { background:linear-gradient(135deg, #64748b, #475569); }
    .notes li { margin:5px 0; color:#cbd5e1; }
    .kv { display:grid; grid-template-columns:170px 1fr; gap:6px 12px; font-size:13px; }
    .kv span:nth-child(odd) { color:#94a3b8; }
  </style>
</head>
<body>
  <div class='nav'>
    {{ main_nav }}
  </div>
  <div class='container'>
    <div class='emp-head'>
      <div>
        <h1>AI Employee</h1>
        <p class='muted'>Every morning at 07:15 Claude Code reviews the whole system from its own reports (health, market report, Strategy Lab and strategy book, SwingTrendPullback, paper trading) and writes a brief with proposals. It can only read: no trades, no settings, no code changes. You decide every proposal.</p>
        <p><span class='chip src'>Read-only</span> <span class='chip src'>No orders</span> <span class='chip src'>Your Claude subscription</span> <span class='chip src'>Proposals need your approval</span></p>
      </div>
      <div><button id='run-btn'>Run review now</button> <button id='refresh-btn'>Refresh</button> <span class='muted' id='status-line'></span></div>
    </div>

    <div class='card' id='brief'><p class='muted'>Loading…</p></div>

    <div class='grid2'>
      <div class='card'><h2>Findings</h2><div id='findings'><p class='muted'>Loading…</p></div></div>
      <div class='card'><h2>Memory</h2><p class='muted-small'>What the employee keeps for the next review, so it builds on earlier days instead of repeating them.</p><ul class='notes' id='memory'><li class='muted'>Loading…</li></ul></div>
    </div>

    <div class='card'>
      <h2>Proposals</h2>
      <p class='muted'>Similar proposals are merged into the first one instead of being added again. Approved and rejected decisions (with your note) are shown to the employee in every later review.</p>
      <div class='tabs' id='proposal-tabs'></div>
      <div id='proposals'><p class='muted'>Loading…</p></div>
    </div>

    <div class='grid2'>
      <div class='card'><h2>Runs</h2><div class='table-wrap' id='runs'><p class='muted'>Loading…</p></div></div>
      <div class='card'><h2>Setup and safety</h2><div id='setup'><p class='muted'>Loading…</p></div></div>
    </div>
  </div>
  <script>
    const API = '/api/ai-employee';
    let current = null;
    let proposalFilter = 'pending';
    function esc(value) { return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
    function chip(text, kind) { return `<span class='chip ${kind}'>${esc(text)}</span>`; }
    const HEALTH = { healthy: 'up', attention: 'mixed', problem: 'down' };
    const STATUS = { pending: 'mixed', approved: 'up', done: 'src', rejected: 'down' };

    function renderBrief(data) {
      const b = data.brief;
      const runningNote = data.running ? ` ${chip('Review running now', 'mixed')}` : '';
      if (!b) {
        return `<h2>Morning brief</h2><p class='muted'>No brief yet. The first review runs at 07:15, or press “Run review now”.${runningNote}</p>`;
      }
      const questions = (b.questions_for_owner || []).length
        ? `<h3>Questions for you</h3><ul class='notes'>${b.questions_for_owner.map(q => `<li>${esc(q)}</li>`).join('')}</ul>` : '';
      const merge = b.proposal_merge || {};
      return `<h2>Morning brief · ${esc(b.date)}</h2>
        <p>${chip('System ' + (b.system_health || 'unknown'), HEALTH[b.system_health] || 'mixed')} <span class='muted-small'>generated ${esc(b.generated_at)} UTC · model ${esc(b.model)} · ${esc(merge.added || 0)} new proposal(s), ${esc(merge.merged || 0)} repeat(s) merged</span>${runningNote}</p>
        <p class='brief-summary'>${esc(b.summary)}</p>${questions}`;
    }

    function renderFindings(b) {
      const rows = (b && b.findings) || [];
      if (!rows.length) return `<p class='muted'>No findings in the latest brief.</p>`;
      return rows.map(f => `<div class='finding ${esc(f.severity)}'>${chip(f.severity, f.severity === 'problem' ? 'down' : f.severity === 'warn' ? 'mixed' : 'src')} <b>${esc(f.area)}</b><div>${esc(f.text)}</div>${f.evidence ? `<div class='ev'>Evidence: ${esc(f.evidence)}</div>` : ''}</div>`).join('');
    }

    function renderTabs(counts) {
      const tabs = ['pending', 'approved', 'done', 'rejected', 'all'];
      return tabs.map(t => `<button type='button' data-filter='${t}' class='${t === proposalFilter ? 'active' : ''}'>${esc(t)}${t === 'all' ? '' : ' (' + esc((counts || {})[t] || 0) + ')'}</button>`).join('');
    }

    function renderProposals(list) {
      const rows = (list || []).filter(p => proposalFilter === 'all' || p.status === proposalFilter);
      if (!rows.length) return `<p class='muted'>No ${proposalFilter === 'all' ? '' : esc(proposalFilter) + ' '}proposals.</p>`;
      return rows.map(p => `<div class='proposal'>
          <h3>${esc(p.title)}</h3>
          <p>${chip(p.status, STATUS[p.status] || 'src')} ${chip(p.category, 'src')} ${chip('effort ' + p.effort, 'src')} <span class='muted-small'>proposed ${esc(p.created_at)} UTC${p.seen_count > 1 ? ' · suggested ' + esc(p.seen_count) + ' times' : ''}${p.decided_at ? ' · decided ' + esc(p.decided_at) + ' UTC' : ''}</span></p>
          ${p.flag ? `<div class='flag'>⚠ ${esc(p.flag)}</div>` : ''}
          <div class='row'><span>What to do</span><span>${esc(p.detail)}</span></div>
          <div class='row'><span>Evidence</span><span>${esc(p.evidence)}</span></div>
          <div class='row'><span>Expected benefit</span><span>${esc(p.expected_benefit)}</span></div>
          <div class='row'><span>Risk</span><span>${esc(p.risk)}</span></div>
          ${p.owner_note ? `<div class='row'><span>Your note</span><span>${esc(p.owner_note)}</span></div>` : ''}
          <div class='actions'>
            ${p.status !== 'approved' ? `<button type='button' class='ok-btn' data-id='${esc(p.id)}' data-status='approved'>Approve</button>` : ''}
            ${p.status !== 'rejected' ? `<button type='button' class='no-btn' data-id='${esc(p.id)}' data-status='rejected'>Reject</button>` : ''}
            ${p.status !== 'done' ? `<button type='button' class='done-btn' data-id='${esc(p.id)}' data-status='done'>Mark done</button>` : ''}
            ${p.status !== 'pending' ? `<button type='button' data-id='${esc(p.id)}' data-status='pending'>Back to pending</button>` : ''}
          </div>
        </div>`).join('');
    }

    function renderRuns(runs) {
      if (!(runs || []).length) return `<p class='muted'>No runs yet.</p>`;
      return `<table><thead><tr><th>Started (UTC)</th><th>Status</th><th class='num'>Seconds</th><th class='num'>Turns</th><th>Proposals</th><th>Note</th></tr></thead><tbody>${runs.map(r => `<tr>
        <td>${esc(r.started_at)}</td><td>${chip(r.status, r.status === 'ok' ? 'up' : 'down')}</td>
        <td class='num'>${esc(r.seconds ?? '—')}</td><td class='num'>${esc(r.num_turns ?? '—')}</td>
        <td>${r.status === 'ok' ? esc((r.proposals_added || 0) + ' new, ' + (r.proposals_merged || 0) + ' merged') : '—'}</td>
        <td class='muted-small'>${esc(r.error || (r.system_health ? 'system ' + r.system_health : ''))}</td></tr>`).join('')}</tbody></table>`;
    }

    function renderSetup(data) {
      const t = data.tools || {};
      const sources = Object.entries(data.context_sources || {}).map(([k, v]) => `${chip(k.replace(/_/g, ' ') + ': ' + v, v === 'ok' ? 'up' : 'mixed')}`).join(' ');
      return `<div class='kv'>
        <span>Schedule</span><span>${esc(data.schedule)}</span>
        <span>Model</span><span>${esc(data.model)}</span>
        <span>Billing</span><span>${esc(t.billing)}</span>
        <span>Tools allowed</span><span>${esc((t.allowed || []).join(', '))}</span>
        <span>Tools blocked</span><span>${esc((t.denied || []).join(', '))}</span>
        <span>Safety flags</span><span>${esc((t.flags || []).join(' · '))}</span>
        <span>Can place orders</span><span>${data.places_orders ? chip('YES', 'down') : chip('No', 'up')}</span>
        <span>Last context</span><span>${esc(data.context_generated_at || '—')} UTC</span>
      </div><p style='margin-top:10px'>${sources || "<span class='muted-small'>No context built yet.</span>"}</p>`;
    }

    async function load() {
      try {
        const data = await (await fetch(API, { cache: 'no-store' })).json();
        if (!data.available) {
          document.getElementById('brief').innerHTML = `<p class='negative'>${esc(data.reason)}</p>`;
          return;
        }
        current = data;
        document.getElementById('brief').innerHTML = renderBrief(data);
        document.getElementById('findings').innerHTML = renderFindings(data.brief);
        document.getElementById('memory').innerHTML = (data.memory_notes || []).length
          ? data.memory_notes.map(n => `<li>${esc(n.text)} <span class='muted-small'>${esc((n.date || '').slice(0, 10))}</span></li>`).join('')
          : `<li class='muted'>Nothing remembered yet.</li>`;
        document.getElementById('proposal-tabs').innerHTML = renderTabs(data.proposal_counts);
        document.getElementById('proposals').innerHTML = renderProposals(data.proposals);
        document.getElementById('runs').innerHTML = renderRuns(data.runs);
        document.getElementById('setup').innerHTML = renderSetup(data);
        document.getElementById('status-line').textContent = `Loaded ${new Date().toLocaleTimeString()}`;
      } catch (error) {
        document.getElementById('brief').innerHTML = `<p class='negative'>Could not load the AI employee: ${esc(error.message || error)}</p>`;
      }
    }

    document.getElementById('proposal-tabs').addEventListener('click', (event) => {
      const button = event.target.closest('button[data-filter]');
      if (!button) return;
      proposalFilter = button.dataset.filter;
      document.getElementById('proposal-tabs').innerHTML = renderTabs((current || {}).proposal_counts);
      document.getElementById('proposals').innerHTML = renderProposals((current || {}).proposals);
    });
    document.getElementById('proposals').addEventListener('click', async (event) => {
      const button = event.target.closest('button[data-id]');
      if (!button) return;
      const status = button.dataset.status;
      let note = '';
      if (status === 'approved' || status === 'rejected') {
        note = window.prompt(status === 'approved' ? 'Note for the employee (optional):' : 'Why reject? (optional, the employee will see it):') || '';
      }
      button.disabled = true;
      try {
        const response = await fetch('/api/ai-employee/proposal', { method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: button.dataset.id, status, note }) });
        const body = await response.json();
        if (!response.ok) document.getElementById('status-line').textContent = body.reason || 'Could not save the decision.';
      } finally {
        load();
      }
    });
    document.getElementById('refresh-btn').addEventListener('click', load);
    document.getElementById('run-btn').addEventListener('click', async () => {
      const line = document.getElementById('status-line');
      try {
        const body = await (await fetch('/api/ai-employee/run', { method: 'POST' })).json();
        line.textContent = body.started ? body.message : body.reason;
        if (body.started) setTimeout(load, 5000);
      } catch (error) {
        line.textContent = `Could not start: ${error.message || error}`;
      }
    });
    load();
    setInterval(load, 30000);
  </script>
</body>
</html>
"""


@app.route('/ai-employee')
def ai_employee_page():
  return render_template_string(AI_EMPLOYEE_TEMPLATE, theme_css=THEME_CSS)


@app.route('/api/ai-employee')
def ai_employee_api():
  try:
    from src import ai_employee
    summary = ai_employee.employee_summary(AI_EMPLOYEE_DIR)
  except Exception as exc:  # optional feature: report it, never a 500
    return jsonify({'available': False, 'places_orders': False, 'reason': f'AI employee unavailable: {exc}'})
  started = _ai_employee_run_started['at']
  return jsonify({'available': True, **summary, 'run_requested_recently': started is not None and monotonic() - started < 600})


@app.route('/api/ai-employee/proposal', methods=['POST'])
def ai_employee_proposal_api():
  """Record the owner's decision on one proposal (local calls only)."""
  if not _local_request_only():
    return jsonify({'ok': False, 'reason': 'local calls only'}), 403
  payload = request.get_json(silent=True) or {}
  try:
    from src import ai_employee
    item = ai_employee.set_proposal_status(str(payload.get('id') or ''), str(payload.get('status') or ''),
                                           str(payload.get('note') or ''), AI_EMPLOYEE_DIR)
  except KeyError as exc:
    return jsonify({'ok': False, 'reason': str(exc)}), 404
  except ValueError as exc:
    return jsonify({'ok': False, 'reason': str(exc)}), 400
  return jsonify({'ok': True, 'proposal': {k: v for k, v in item.items() if k != 'title_words'}})


@app.route('/api/ai-employee/run', methods=['POST'])
def ai_employee_run_api():
  """Start one review now in its own process (local calls only, at most every 10 minutes)."""
  if not _local_request_only():
    return jsonify({'started': False, 'reason': 'local calls only'}), 403
  started = _ai_employee_run_started['at']
  if started is not None and monotonic() - started < 600:
    return jsonify({'started': False, 'reason': 'A review was started less than 10 minutes ago.'}), 429
  import subprocess
  import sys
  try:
    subprocess.Popen([sys.executable, '-m', 'src.ai_employee', 'run', '--force'], cwd=_APP_DIR,
                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                     creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
  except Exception as exc:
    return jsonify({'started': False, 'reason': f'Could not start the review: {exc}'}), 500
  _ai_employee_run_started['at'] = monotonic()
  return jsonify({'started': True, 'message': 'Review started; it usually takes 1-5 minutes. The page refreshes itself.'})


@app.route('/paper-trading')
def paper_trading_page():
  return render_template_string(PAPER_TRADING_TEMPLATE, theme_css=THEME_CSS)


# Demo-account execution of the gold 4h model. Every guard (enabled flag, demo account only,
# fresh signal, one position, stops attached) is in src/demo_executor.py. The paper-trading
# process posts its fresh signals here because only this process may use the MT5 connection.
_demo_model_lock = threading.Lock()


def _demo_model_files():
  from src import demo_executor
  return demo_executor, os.path.join(_APP_DIR, str(demo_executor.CONFIG_PATH)), os.path.join(_APP_DIR, str(demo_executor.JOURNAL_PATH))


def _local_request_only():
  return request.remote_addr in {'127.0.0.1', '::1'}


@app.route('/api/demo-model/execute', methods=['POST'])
def demo_model_execute_api():
  """Open one demo position for a fresh gold 4h model signal; refuses anything but the configured demo account."""
  if not _local_request_only():
    return jsonify({'event': 'refused', 'reason': 'local calls only'}), 403
  if MT5_ENGINE is None:
    return jsonify({'event': 'refused', 'reason': 'MT5 engine unavailable'}), 503
  demo_executor, config_path, journal_path = _demo_model_files()
  signal = request.get_json(silent=True) or {}
  with _demo_model_lock:
    config = demo_executor.load_config(config_path)
    journal = demo_executor.load_journal(journal_path)
    event = demo_executor.execute_signal(MT5_ENGINE, signal, config, journal)
    demo_executor.save_journal(journal, journal_path)
  return jsonify(event)


@app.route('/api/demo-model/sync', methods=['POST'])
def demo_model_sync_api():
  """Record positions the broker closed and close model positions that reached the time limit."""
  if not _local_request_only():
    return jsonify({'events': [], 'reason': 'local calls only'}), 403
  if MT5_ENGINE is None:
    return jsonify({'events': [], 'reason': 'MT5 engine unavailable'}), 503
  demo_executor, config_path, journal_path = _demo_model_files()
  with _demo_model_lock:
    config = demo_executor.load_config(config_path)
    journal = demo_executor.load_journal(journal_path)
    events = demo_executor.sync_positions(MT5_ENGINE, config, journal)
    demo_executor.save_journal(journal, journal_path)
  return jsonify({'events': events})


@app.route('/api/demo-model/status')
def demo_model_status_api():
  demo_executor, config_path, journal_path = _demo_model_files()
  config = demo_executor.load_config(config_path)
  journal = demo_executor.load_journal(journal_path)
  positions = None
  if MT5_ENGINE is not None and hasattr(MT5_ENGINE, 'positions'):
    positions = MT5_ENGINE.positions(symbol=config['symbol'], magic=int(config['magic']))
  attempts = list((journal.get('attempts') or {}).values())
  return jsonify({
    'config': config,
    'open_positions': positions,
    'attempts': list(reversed(attempts))[:50],
    'events': list(reversed(journal.get('events') or []))[:100],
  })


# Gold session pullback on the demo account 11581419 (src/demo_session_pullback.py): the only strategy that trades that
# account. The hourly task "SmartEntry Demo Pullback" calls the cycle; every order and refusal is logged with its reason.
# Control calls (cycle, STOP, resume) need a request from this PC and the control secret.
_demo_pullback_lock = threading.Lock()


def _demo_pullback_refused():
  from src import execution_guard
  if not _local_request_only():
    return jsonify({'ok': False, 'reason': 'local calls only'}), 403
  if not execution_guard.secret_matches(request.headers.get(execution_guard.SECRET_HEADER),
                                        execution_guard.load_or_create_secret()):
    return jsonify({'ok': False, 'reason': 'the control secret (X-Control-Secret header) is required'}), 403
  return None


@app.route('/api/demo-trading/cycle', methods=['POST'])
def demo_trading_cycle_api():
  refused = _demo_pullback_refused()
  if refused:
    return refused
  from src import demo_session_pullback, economic_calendar
  if MT5_ENGINE is None:
    return jsonify({'decision': 'refused', 'reason': 'MT5 engine unavailable'}), 503
  try:
    calendar_events = economic_calendar.load_calendar(datetime.now(timezone.utc)).get('events') or []
  except Exception:
    calendar_events = []
  with _demo_pullback_lock:
    summary = demo_session_pullback.run_cycle(MT5_ENGINE, get_bars, calendar_events)
  return jsonify(summary)


@app.route('/api/demo-trading/stop', methods=['POST'])
def demo_trading_stop_api():
  refused = _demo_pullback_refused()
  if refused:
    return refused
  from src import demo_session_pullback
  with _demo_pullback_lock:
    event = demo_session_pullback.owner_stop(MT5_ENGINE)
  return jsonify(event)


@app.route('/api/demo-trading/resume', methods=['POST'])
def demo_trading_resume_api():
  refused = _demo_pullback_refused()
  if refused:
    return refused
  from src import demo_session_pullback
  with _demo_pullback_lock:
    event = demo_session_pullback.owner_resume()
  return jsonify(event)


@app.route('/api/demo-trading/status')
def demo_trading_status_api():
  from src import demo_session_pullback
  return jsonify(demo_session_pullback.status_payload(MT5_ENGINE))


# Volatility Trend Breakout (4H) on the same demo account, beside the pullback (src/demo_volatility_breakout.py, magic
# 440603). Same guards: local request plus control secret for cycle / STOP / resume; the hourly task calls the cycle.
_demo_breakout_lock = threading.Lock()


@app.route('/api/demo-breakout/cycle', methods=['POST'])
def demo_breakout_cycle_api():
  refused = _demo_pullback_refused()
  if refused:
    return refused
  from src import demo_volatility_breakout, economic_calendar
  if MT5_ENGINE is None:
    return jsonify({'decision': 'refused', 'reason': 'MT5 engine unavailable'}), 503
  try:
    calendar_events = economic_calendar.load_calendar(datetime.now(timezone.utc)).get('events') or []
  except Exception:
    calendar_events = []
  with _demo_breakout_lock:
    summary = demo_volatility_breakout.breakout_cycle(MT5_ENGINE, get_bars, calendar_events)
  return jsonify(summary)


@app.route('/api/demo-breakout/stop', methods=['POST'])
def demo_breakout_stop_api():
  refused = _demo_pullback_refused()
  if refused:
    return refused
  from src import demo_volatility_breakout
  with _demo_breakout_lock:
    event = demo_volatility_breakout.stop_breakout(MT5_ENGINE)
  return jsonify(event)


@app.route('/api/demo-breakout/resume', methods=['POST'])
def demo_breakout_resume_api():
  refused = _demo_pullback_refused()
  if refused:
    return refused
  from src import demo_volatility_breakout
  with _demo_breakout_lock:
    event = demo_volatility_breakout.resume_breakout()
  return jsonify(event)


@app.route('/api/i40-pilot')
def i40_pilot_api():
  """The i40 Pilot brief: identity, signature rules, memory, live context, schedule, skills, tools and the loop.

  Read-only. The cached brief on disk is the hourly one; ``?live=1`` rebuilds it now, which costs a few seconds
  because it reads the scheduled tasks and the running strategies."""
  from src import i40_pilot
  from src.runtime_paths import read_latest_json

  if request.args.get('live') == '1':
    return jsonify(i40_pilot.build_brief(url_map=app.url_map))
  brief = read_latest_json(i40_pilot.pilot_dir() / 'latest.json',
                           'the brief has not been written yet (task SmartEntry i40 Pilot)')
  if brief.get('available') and not (brief.get('tools') or {}).get('api_endpoints'):
    brief.setdefault('tools', {})['api_endpoints'] = sorted({str(rule) for rule in app.url_map.iter_rules()
                                                             if str(rule).startswith('/api/')})
    brief['tools']['api_endpoint_count'] = len(brief['tools']['api_endpoints'])
  return jsonify(brief)


@app.route('/i40-pilot')
def i40_pilot_page():
  return render_template_string(I40_PILOT_TEMPLATE, theme_css=THEME_CSS)


I40_PILOT_TEMPLATE = r"""
<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width, initial-scale=1'>
  <title>i40 Pilot</title>
  {{ theme_css | safe }}
  <style>
    /* the shared container is sized for a desktop; on a phone the page must fit the screen, not scroll sideways */
    html, body { max-width:100%; overflow-x:hidden; }
    .wrap { max-width:1180px; margin:0 auto; box-sizing:border-box; }
    @media (max-width: 720px) {
      .container.wrap { padding-left:14px; padding-right:14px; width:100%; min-width:0; }
      .nav { overflow-x:auto; }
      h1 { font-size:26px; }
      .verdict { font-size:15px; padding:12px 13px; }
    }
    .wrap * { min-width:0; }
    .topline { display:flex; flex-wrap:wrap; align-items:baseline; justify-content:space-between; gap:8px; margin-bottom:4px; }
    .topline h1 { margin:0; }
    .sub { color:#8fa6c4; font-size:13px; margin:2px 0 0; }
    .verdict { display:flex; align-items:center; gap:12px; border-radius:14px; padding:14px 16px; margin:14px 0;
               border:1px solid; font-size:17px; font-weight:700; }
    .verdict .dot { width:12px; height:12px; border-radius:50%; flex:0 0 auto; }
    .v-ok   { border-color:rgba(52,211,153,.55); background:rgba(16,185,129,.10); color:#d1fae5; }
    .v-ok .dot { background:#34d399; box-shadow:0 0 12px #34d399; }
    .v-info { border-color:rgba(96,165,250,.55); background:rgba(59,130,246,.10); color:#dbeafe; }
    .v-info .dot { background:#60a5fa; box-shadow:0 0 12px #60a5fa; }
    .v-warn { border-color:rgba(251,191,36,.6); background:rgba(251,191,36,.10); color:#fde68a; }
    .v-warn .dot { background:#fbbf24; box-shadow:0 0 12px #fbbf24; }
    .v-bad  { border-color:rgba(251,113,133,.65); background:rgba(225,29,72,.14); color:#fecdd3; }
    .v-bad .dot { background:#fb7185; box-shadow:0 0 12px #fb7185; }

    .band { display:grid; grid-template-columns:repeat(auto-fit,minmax(190px,1fr)); gap:10px; margin:0 0 16px; }
    @media (max-width: 720px) { .band { grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; } .stat .v { font-size:17px; } }
    @media (max-width: 380px) { .band { grid-template-columns:1fr; } }
    .stat { border-radius:12px; padding:11px 13px; background:rgba(15,23,42,.72); border:1px solid rgba(148,176,222,.22);
            border-left:3px solid #38bdf8; }
    .stat.ok { border-left-color:#34d399; } .stat.warn { border-left-color:#fbbf24; } .stat.bad { border-left-color:#fb7185; }
    .stat .k { font-size:10.5px; letter-spacing:.07em; text-transform:uppercase; color:#8fa6c4; }
    .stat .v { font-size:19px; font-weight:800; color:#f8fafc; margin-top:3px; line-height:1.15; font-variant-numeric:tabular-nums; }
    .stat .s { font-size:11.5px; color:#9fb3d1; margin-top:3px; }

    .cols { display:grid; grid-template-columns:1.25fr .95fr; gap:14px; align-items:start; }
    @media (max-width: 860px) { .cols { grid-template-columns:1fr; } }
    .panel { border-radius:14px; border:1px solid rgba(148,176,222,.22); background:rgba(15,23,42,.6); padding:14px 16px; margin-bottom:14px; }
    .panel h2 { margin:0 0 4px; font-size:17px; }
    .panel .lead { color:#8fa6c4; font-size:12.5px; margin:0 0 10px; }

    .att { display:flex; gap:10px; padding:9px 0; border-bottom:1px solid rgba(148,176,222,.14); }
    .att:last-child { border-bottom:0; }
    .att .sev { font-size:10px; font-weight:800; letter-spacing:.06em; padding:2px 7px; border-radius:999px; height:fit-content; }
    .sev.bad { color:#fecdd3; background:rgba(225,29,72,.2); } .sev.warn { color:#fde68a; background:rgba(251,191,36,.18); }
    .sev.info { color:#bfdbfe; background:rgba(59,130,246,.18); }
    .att b { display:block; color:#f1f5f9; font-size:13.5px; } .att span { color:#9fb3d1; font-size:12px; }

    .feed { max-height:420px; overflow:auto; }
    .ev { display:grid; grid-template-columns:132px 1fr; gap:10px; padding:7px 0; border-bottom:1px solid rgba(148,176,222,.12); font-size:12.5px; }
    .ev:last-child { border-bottom:0; }
    .ev time { color:#8fa6c4; font-variant-numeric:tabular-nums; }
    .ev .who { color:#93c5fd; }
    .ev .what { color:#e2e8f0; } .ev .why { color:#8fa6c4; }
    @media (max-width: 560px) { .ev { grid-template-columns:1fr; gap:2px; } }

    .strat { border-radius:12px; border:1px solid rgba(148,176,222,.2); padding:11px 13px; margin-bottom:10px; background:rgba(2,6,23,.4); }
    .strat .row { display:flex; flex-wrap:wrap; align-items:center; gap:8px; }
    .strat .name { font-weight:700; color:#f8fafc; }
    .pill { display:inline-block; padding:2px 8px; border-radius:999px; font-size:10.5px; font-weight:700; border:1px solid; white-space:nowrap; }
    .pill.live { color:#a7f3d0; border-color:rgba(52,211,153,.6); background:rgba(16,185,129,.12); }
    .pill.dry  { color:#fde68a; border-color:rgba(251,191,36,.55); background:rgba(251,191,36,.10); }
    .pill.halt { color:#fecdd3; border-color:rgba(251,113,133,.6); background:rgba(225,29,72,.14); }
    .pill.flat { color:#cbd5e1; border-color:rgba(148,176,222,.4); }
    .kv { font-size:12px; color:#9fb3d1; margin-top:5px; font-variant-numeric:tabular-nums; }

    details.more { border-radius:12px; border:1px solid rgba(148,176,222,.2); background:rgba(15,23,42,.5); padding:0 14px; margin-bottom:10px; }
    details.more > summary { cursor:pointer; padding:12px 0; font-weight:700; color:#e2e8f0; list-style:none; display:flex; justify-content:space-between; gap:10px; }
    details.more > summary::-webkit-details-marker { display:none; }
    details.more > summary .hint { font-weight:500; color:#8fa6c4; font-size:12px; }
    details.more[open] > summary { border-bottom:1px solid rgba(148,176,222,.16); }
    details.more .body { padding:12px 0 14px; }
    .rule { padding:9px 0; border-bottom:1px solid rgba(148,176,222,.12); }
    .rule:last-child { border-bottom:0; }
    .rule b { color:#f1f5f9; font-size:13.5px; } .rule span { display:block; color:#9fb3d1; font-size:12px; margin-top:2px; }
    .rule .since { color:#7f96b5; font-size:10.5px; }
    ul.tight { margin:4px 0 0; padding-left:17px; font-size:13px; } ul.tight li { margin:3px 0; }
    code.mono { font-family:ui-monospace,Consolas,monospace; font-size:11.5px; color:#bfdbfe; }
    td.num, th.num { text-align:right; font-variant-numeric:tabular-nums; }
    table { font-size:12.5px; }
    .btn-row { display:flex; gap:8px; align-items:center; flex-wrap:wrap; }
  </style>
</head>
<body>
  <div class='nav'>{{ main_nav }}</div>
  <div class='container wrap'>
    <div class='topline'>
      <div>
        <h1>i40 Pilot</h1>
        <p class='sub' id='ident'>Loading…</p>
      </div>
      <div class='btn-row'><button id='refresh-btn'>Rebuild now</button><span class='sub' id='status-line'></span></div>
    </div>

    <div class='verdict v-info' id='verdict'><span class='dot'></span><span id='verdict-text'>Reading the system…</span></div>
    <div class='band' id='band'></div>

    <div class='cols'>
      <div>
        <div class='panel'>
          <h2>Needs attention</h2>
          <p class='lead'>Anything stopped, late, missing or misdirected. An empty list is the answer, not a blank space.</p>
          <div id='attention'><p class='sub'>Loading…</p></div>
        </div>
        <div class='panel'>
          <h2>Strategies</h2>
          <p class='lead'>What is running against the demo account, and what it last decided.</p>
          <div id='strategies'><p class='sub'>Loading…</p></div>
        </div>
      </div>
      <div class='panel'>
        <h2>Activity</h2>
        <p class='lead' id='activity-note'>What the system actually did, newest first.</p>
        <div class='feed' id='activity'><p class='sub'>Loading…</p></div>
      </div>
    </div>

    <details class='more' id='rules-box'><summary>Signature rules <span class='hint' id='rules-hint'></span></summary>
      <div class='body'><p class='lead'>The owner's standing decisions. They are not defaults, and nothing here is relaxed without the owner saying so.</p>
      <div id='rules'></div></div></details>
    <details class='more'><summary>Schedule <span class='hint' id='schedule-hint'></span></summary>
      <div class='body'><div class='table-wrap' id='schedule'></div></div></details>
    <details class='more'><summary>Memory <span class='hint' id='memory-hint'></span></summary>
      <div class='body' id='memory'></div></details>
    <details class='more'><summary>Skills and instructions <span class='hint' id='skills-hint'></span></summary>
      <div class='body'><div id='skills'></div><h3>Instructions</h3><div id='instructions'></div></div></details>
    <details class='more'><summary>Tools <span class='hint' id='tools-hint'></span></summary>
      <div class='body' id='tools'></div></details>
    <details class='more'><summary>Context detail <span class='hint'>models, learning, positioning</span></summary>
      <div class='body' id='context'></div></details>
  </div>
<script>
const esc = v => String(v === null || v === undefined ? '—' : v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gap = s => `<p class='sub'>${esc((s || {}).reason || 'not available')}</p>`;
const shortTime = t => String(t || '').slice(5, 16);

function setVerdict(attention, loop) {
  const worst = (attention || {}).worst || 'info';
  const box = document.getElementById('verdict');
  box.className = 'verdict v-' + worst;
  const extra = attention && attention.count ? ` — ${attention.count} item${attention.count > 1 ? 's' : ''} below` : '';
  document.getElementById('verdict-text').textContent = ((attention || {}).headline || 'Reading the system…') + extra;
}

function band(d) {
  const c = d.context || {}, strategies = Object.values(c.strategies || {});
  const running = strategies.filter(s => s.available);
  const sending = running.filter(s => s.sending_orders && !s.halted).length;
  const halted = running.filter(s => s.halted).length;
  const sched = d.schedule || {}, tasks = sched.tasks || [];
  const late = (sched.missing || []).length;
  const account = (running.find(s => (s.account || {}).available) || {}).account || {};
  const mem = d.memory || {}, loop = d.loop || {};
  const learn = c.learning || {};
  const learned = Object.keys(learn.per_symbol || {}).length;
  const tiles = [
    {k: 'Strategies', v: `${sending} sending · ${running.length - sending - halted} dry`,
     s: halted ? `${halted} halted` : `${running.length} of ${strategies.length} readable`,
     cls: halted ? 'bad' : running.length === strategies.length ? 'ok' : 'warn'},
    {k: 'Demo account', v: account.available ? `${Number(account.equity).toLocaleString('en-GB')} ${esc(account.currency || '')}` : '—',
     s: account.available ? `equity · balance ${Number(account.balance).toLocaleString('en-GB')}` : 'MT5 not readable', cls: account.available ? 'ok' : 'warn'},
    {k: 'Scheduled tasks', v: `${tasks.length - late} / ${tasks.length}`, s: late ? `${late} missing` : 'all registered',
     cls: late ? 'bad' : 'ok'},
    {k: 'Learning', v: learn.available ? `${learned} symbol${learned === 1 ? '' : 's'}` : '—',
     s: learn.available ? `${learn.decisions} decisions recorded` : (learn.reason || ''), cls: learn.available ? 'ok' : 'warn'},
    {k: 'Recorded results', v: mem.available ? mem.baseline_rows : '—',
     s: mem.available ? `${mem.open_backlog_count} open backlog items` : (mem.reason || ''), cls: 'ok'},
    {k: 'Brief age', v: loop.available ? `${loop.age_minutes} min` : 'not written',
     s: loop.available ? `refreshes every ${loop.every_minutes} min` : (loop.reason || ''), cls: loop.stale ? 'warn' : 'ok'},
  ];
  document.getElementById('band').innerHTML = tiles.map(t =>
    `<div class='stat ${t.cls}'><div class='k'>${esc(t.k)}</div><div class='v'>${esc(t.v)}</div><div class='s'>${esc(t.s)}</div></div>`).join('');
}

function renderAttention(a) {
  const box = document.getElementById('attention');
  if (!a || !a.count) { box.innerHTML = "<p class='sub'>Nothing is stuck: no strategy halted, no task missing, no cycle late.</p>"; return; }
  box.innerHTML = (a.items || []).map(i => `<div class='att'><span class='sev ${esc(i.severity)}'>${esc(i.severity)}</span>
    <div><b>${esc(i.what)}</b><span>${esc(i.why)}</span><span><a href='${esc(i.where)}'>${esc(i.where)}</a></span></div></div>`).join('');
}

function renderStrategies(c) {
  const box = document.getElementById('strategies');
  const entries = Object.entries((c || {}).strategies || {});
  if (!entries.length) { box.innerHTML = "<p class='sub'>No strategy could be read.</p>"; return; }
  box.innerHTML = entries.map(([name, s]) => {
    if (!s.available) return `<div class='strat'><div class='row'><span class='name'>${esc(name)}</span><span class='pill halt'>unreadable</span></div><div class='kv'>${esc(s.reason)}</div></div>`;
    const mode = s.halted ? "<span class='pill halt'>halted</span>" : s.sending_orders ? "<span class='pill live'>sending orders</span>" : "<span class='pill dry'>dry run</span>";
    const cycle = s.cycle_health || {};
    const cyclePill = cycle.available ? (cycle.late ? `<span class='pill halt'>cycle ${esc(cycle.age_minutes)} min late</span>` : `<span class='pill flat'>ran ${esc(cycle.age_minutes)} min ago</span>`) : '';
    const last = (s.recent_decisions || [])[0] || {};
    const ex = s.expectancy && s.expectancy.demo_broker_fills ? s.expectancy.demo_broker_fills : s.expectancy || {};
    return `<div class='strat'>
      <div class='row'><span class='name'>${esc(name)}</span>${mode}${cyclePill}</div>
      <div class='kv'>${esc(s.symbol)} · magic ${esc(s.magic)} · ${s.open_trade ? 'position open' : 'flat'} · ${esc(s.today_trades)} trade(s) today · ${ex.trades || 0} settled, expectancy ${ex.expectancy_r === null || ex.expectancy_r === undefined ? '—' : esc(ex.expectancy_r) + 'R'}</div>
      <div class='kv'>last: <strong>${esc(last.event || '—')}</strong> ${esc(last.reason || '')}</div></div>`;
  }).join('');
}

function renderActivity(a) {
  const box = document.getElementById('activity');
  if (!a || !(a.events || []).length) { box.innerHTML = "<p class='sub'>No activity recorded yet.</p>"; return; }
  document.getElementById('activity-note').textContent = a.note || '';
  box.innerHTML = a.events.map(e => `<div class='ev'><time>${esc(shortTime(e.at))} <span class='who'>${esc(e.source)}</span></time>
    <div><span class='what'>${esc(e.what)}</span> <span class='why'>${esc(e.detail || '')}</span></div></div>`).join('');
}

function renderRules(rules) {
  document.getElementById('rules-hint').textContent = `${(rules || {}).count || 0} standing rules`;
  document.getElementById('rules').innerHTML = ((rules || {}).signature_rules || []).map(r =>
    `<div class='rule'><b>${esc(r.rule)}</b><span>${esc(r.why)}</span><span class='since'>standing since ${esc(r.since)}</span></div>`).join('');
}

function renderSchedule(s) {
  document.getElementById('schedule-hint').textContent = s && s.available
    ? `${s.count} tasks${(s.missing || []).length ? ', ' + s.missing.length + ' missing' : ', none missing'}` : 'unavailable';
  const box = document.getElementById('schedule');
  if (!s || !s.available) { box.innerHTML = gap(s); return; }
  box.innerHTML = `<table><tr><th>Task</th><th>Runs</th><th>Last run</th><th>Next run</th><th>Result</th></tr>` +
    (s.tasks || []).map(t => `<tr><td>${esc(t.task)}</td><td>${esc(t.schedule)}</td><td>${esc(t.last_run)}</td>
      <td>${esc(t.next_run)}</td><td>${t.registered ? esc(t.last_result) : "<span class='pill halt'>not registered</span>"}</td></tr>`).join('') + '</table>';
}

function renderMemory(m) {
  document.getElementById('memory-hint').textContent = m && m.available
    ? `${m.baseline_rows} recorded results · ${m.open_backlog_count} open` : 'unavailable';
  const box = document.getElementById('memory');
  if (!m || !m.available) { box.innerHTML = gap(m); return; }
  box.innerHTML = `<p class='lead'>${esc(m.note)}</p>
    <h3>Latest recorded results</h3><ul class='tight'>${(m.latest_results || []).map(row => {
      const cells = row.split('|').filter(c => c.trim());
      return `<li><strong>${esc((cells[0] || '').trim())}</strong> ${esc((cells[1] || '').trim())} — ${esc((cells[2] || '').trim().slice(0, 160))}</li>`;
    }).join('')}</ul>
    <h3>Recent notes</h3><ul class='tight'>${(m.recent_notes || []).map(n => `<li>${esc(n.slice(0, 220))}</li>`).join('')}</ul>`;
}

function renderSkills(s, instructions) {
  document.getElementById('skills-hint').textContent = s && s.available ? `${s.count} skills` : 'unavailable';
  document.getElementById('skills').innerHTML = s && s.available
    ? `<ul class='tight'>${(s.skills || []).map(k => `<li><code class='mono'>/${esc(k.name)}</code> ${esc(k.description)}</li>`).join('')}</ul>`
    : gap(s);
  document.getElementById('instructions').innerHTML = `<ul class='tight'>${(instructions || []).map(i => `<li>${esc(i)}</li>`).join('')}</ul>`;
}

function renderTools(t) {
  document.getElementById('tools-hint').textContent = `${((t || {}).commands || []).length} commands · ${esc((t || {}).api_endpoint_count)} endpoints`;
  document.getElementById('tools').innerHTML = `<ul class='tight'>${((t || {}).commands || []).map(c =>
      `<li><code class='mono'>${esc(c.command)}</code> — ${esc(c.does)}</li>`).join('')}</ul>
    <details style='margin-top:10px'><summary class='sub'>every HTTP endpoint</summary>
      <ul class='tight'>${((t || {}).api_endpoints || []).map(e => `<li><code class='mono'>${esc(e)}</code></li>`).join('')}</ul></details>`;
}

function renderContext(c) {
  const box = document.getElementById('context');
  if (!c) { box.innerHTML = gap(c); return; }
  const learn = c.learning || {}, models = c.models || {}, pos = c.positioning || {};
  box.innerHTML = `<h3>Learning</h3>${learn.available
      ? `<ul class='tight'>${Object.entries(learn.per_symbol || {}).map(([sym, d]) =>
          `<li>${esc(sym)}: ${esc(d.status)} · RF ${d.rf_promoted ? 'promoted' : 'kept'} · LSTM ${d.lstm_promoted ? 'promoted' : 'kept'} · accuracy ${d.accuracy === null || d.accuracy === undefined ? '—' : Number(d.accuracy).toFixed(3)}</li>`).join('')}</ul>`
      : gap(learn)}
    <h3>Models</h3>${models.available ? `<p class='lead'>${esc(models.count)} file(s), newest written ${esc(models.newest_written)} UTC — ${esc(models.folder)}</p>` : gap(models)}
    <h3>Positioning</h3>${pos.available ? `<p class='lead'>CFTC report as of ${esc(pos.as_of)} — <a href='/positioning'>open the page</a></p>` : gap(pos)}`;
}

async function load(live) {
  const line = document.getElementById('status-line');
  line.textContent = live ? 'rebuilding…' : 'loading…';
  let d;
  try { d = await (await fetch('/api/i40-pilot' + (live ? '?live=1' : ''))).json(); }
  catch (e) { line.textContent = 'unavailable: ' + e; return; }
  const id = d.identity || {};
  document.getElementById('ident').textContent = `${id.role || ''}`;
  setVerdict(d.attention, d.loop);
  band(d);
  renderAttention(d.attention);
  renderStrategies(d.context);
  renderActivity(d.activity);
  renderRules(d.rules);
  renderSchedule(d.schedule);
  renderMemory(d.memory);
  renderSkills(d.skills, d.instructions);
  renderTools(d.tools);
  renderContext(d.context);
  const loop = d.loop || {};
  line.textContent = `${esc(id.branch || '')} @ ${esc(id.commit || '')} · brief ${esc(d.generated_at)} UTC`
    + (loop.available ? ` · ${loop.age_minutes} min old` : '') + (d.available === false ? ` · ${esc(d.reason)}` : '');
}
document.getElementById('refresh-btn').addEventListener('click', () => load(true));
load(false);
setInterval(() => load(false), 120000);
</script>
</body>
</html>
"""


@app.route('/api/positioning')
def positioning_api():
  """Speculative positioning from the CFTC Commitments of Traders report (weekly, days old, context only)."""
  from src import positioning
  from src.runtime_paths import read_latest_json
  return jsonify(read_latest_json(positioning.positioning_dir() / 'latest.json',
                                  'positioning has not been downloaded yet (task SmartEntry Positioning)'))


@app.route('/positioning')
def positioning_page():
  return render_template_string(POSITIONING_TEMPLATE, theme_css=THEME_CSS)


POSITIONING_TEMPLATE = r"""
<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width, initial-scale=1'>
  <title>Positioning</title>
  {{ theme_css | safe }}
  <style>
    .po-head { display:flex; flex-wrap:wrap; justify-content:space-between; align-items:flex-end; gap:12px; }
    .banner { border-radius:12px; padding:10px 14px; margin:10px 0 14px; border:1px solid rgba(251,191,36,.6); background:rgba(251,191,36,.12); color:#fde68a; }
    td.num, th.num { text-align:right; font-variant-numeric:tabular-nums; }
    .long { color:#a7f3d0; } .short { color:#fecdd3; } .flat { color:#cbd5e1; }
    .bar { position:relative; height:12px; border-radius:999px; background:rgba(148,176,222,.18); min-width:120px; }
    .bar > i { position:absolute; top:-2px; bottom:-2px; width:3px; background:#f8fafc; border-radius:2px; }
    .bar > b { position:absolute; top:0; bottom:0; left:0; border-radius:999px; background:linear-gradient(90deg,#38bdf8,#a78bfa); opacity:.6; }
    .bar.idx > b { background:linear-gradient(90deg,#34d399,#fbbf24,#f43f5e); }
    .tag { display:inline-block; padding:2px 8px; border-radius:999px; font-size:11px; font-weight:700; }
    .tag.hot { color:#fecdd3; background:rgba(225,29,72,.18); border:1px solid rgba(251,113,133,.6); }
    .tag.flip { color:#bfdbfe; background:rgba(59,130,246,.16); border:1px solid rgba(96,165,250,.6); }
    .tag.thin { color:#fde68a; background:rgba(251,191,36,.14); border:1px solid rgba(251,191,36,.5); }
    .mine td:first-child { box-shadow: inset 3px 0 0 #38bdf8; }
    .focus { display:grid; grid-template-columns:repeat(auto-fit,minmax(340px,1fr)); gap:14px; }
    .focus .card { margin:0; }
    .big { font-size:30px; font-weight:800; letter-spacing:-.5px; line-height:1.1; }
    .kv { display:grid; grid-template-columns:auto 1fr; gap:4px 10px; font-size:13px; margin:10px 0 0; }
    .kv dt { color:#9fb3d1; } .kv dd { margin:0; font-variant-numeric:tabular-nums; }
    .spark { display:block; width:100%; height:44px; }
    .spark.sm { width:120px; height:22px; }
    .glossary { columns:2; column-gap:26px; font-size:13px; }
    .glossary p { margin:0 0 8px; break-inside:avoid; }
    @media (max-width:760px) { .glossary { columns:1; } }
    .subtle { font-size:12px; color:#8fa6c4; }
  </style>
</head>
<body>
  <div class='nav'>{{ main_nav }}</div>
  <div class='container'>
    <div class='po-head'>
      <div>
        <h1>Positioning</h1>
        <p class='muted'>Who is holding what, from the CFTC Commitments of Traders report (Legacy, futures only). Large speculators are trend followers with no commercial exposure; commercials are producers and hedgers on the other side. Net = long minus short. Positions are reported for a Tuesday and published the Friday after, so this page is always days old and is context, never a trigger.</p>
      </div>
      <div><button id='refresh-btn'>Refresh</button> <span class='muted' id='status-line'></span></div>
    </div>
    <div class='banner' id='asof'>Loading...</div>
    <h2>Gold and bitcoin, the two markets this system trades</h2>
    <div class='focus' id='focus'><div class='card'><p class='muted'>Loading...</p></div></div>
    <div class='card'><h2>Every market in the report</h2>
      <div class='table-wrap' id='table'><p class='muted'>Loading...</p></div></div>
    <div class='card'><h2>Dollar proxy</h2><div id='usd'><p class='muted'>Loading...</p></div></div>
    <div class='card'><h2>How to read this page</h2>
      <div class='glossary'>
        <p><strong>Net</strong> - large speculators' long contracts minus their short contracts. Positive means the crowd of speculators is leaning long.</p>
        <p><strong>% of open interest</strong> - the net as a share of all open contracts, so markets of different sizes can be compared.</p>
        <p><strong>COT index</strong> - where this net sits inside its own three-year range: 0 = the most short it has been, 100 = the most long. A crowded reading says the fuel for more of the same is used up, not that a turn is due.</p>
        <p><strong>Percentile</strong> - the same idea over the full history on this page, ranking today's % of open interest against every past week.</p>
        <p><strong>1w / 4w / 13w</strong> - how many net contracts were added or cut over the last week, month and quarter. The direction of the change is often more informative than the level.</p>
        <p><strong>Commercials</strong> - producers, miners and dealers. They are usually on the opposite side of the speculators; an unusually large commercial short is the mirror of a crowded speculative long.</p>
        <p><strong>Small traders</strong> - the non-reportable accounts, too small to file. Useful only as a crowd read.</p>
        <p><strong>What happened next</strong> - this market's own history: for every past week the index is recomputed from the data available then, and the move over the following four weeks is measured on broker candles. Descriptive, after the fact, and never a prediction.</p>
        <p class='subtle'>The report itself is weekly and late; it explains the background a move happens against, so nothing on this page opens, closes or sizes a trade.</p>
      </div>
    </div>
  </div>
<script>
const esc = v => String(v === null || v === undefined ? '-' : v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = v => (v === null || v === undefined) ? '-' : Number(v).toLocaleString('en-GB');
const signed = v => (v === null || v === undefined) ? '-' : (v > 0 ? '+' : '') + Number(v).toLocaleString('en-GB');
const cls = stance => stance === 'net long' ? 'long' : stance === 'net short' ? 'short' : 'flat';
const pct = v => (v === null || v === undefined) ? 0 : Math.max(0, Math.min(100, Number(v)));

function spark(values, small) {
  if (!values || values.length < 4) return "<span class='muted'>-</span>";
  const w = small ? 120 : 320, h = small ? 22 : 44, lo = Math.min(...values, 0), hi = Math.max(...values, 0);
  const span = (hi - lo) || 1;
  const x = i => (i / (values.length - 1)) * (w - 2) + 1;
  const y = v => h - 1 - ((v - lo) / span) * (h - 2);
  const line = values.map((v, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');
  const zero = (lo < 0 && hi > 0) ? `<line x1='0' x2='${w}' y1='${y(0).toFixed(1)}' y2='${y(0).toFixed(1)}' stroke='rgba(148,176,222,.45)' stroke-dasharray='3 3'/>` : '';
  const last = values[values.length - 1];
  return `<svg class='spark${small ? ' sm' : ''}' viewBox='0 0 ${w} ${h}' preserveAspectRatio='none' role='img'>${zero}
    <path d='${line}' fill='none' stroke='${last >= 0 ? '#34d399' : '#fb7185'}' stroke-width='1.6'/>
    <circle cx='${x(values.length - 1).toFixed(1)}' cy='${y(last).toFixed(1)}' r='2' fill='#f8fafc'/></svg>`;
}

function barCell(value, label, extraClass) {
  return `<div class='bar ${extraClass || ''}'><b style='width:${pct(value)}%'></b><i style='left:${Math.min(99, pct(value))}%'></i></div>
          <span class='muted'>${esc(value)} ${esc(label)}</span>`;
}

function nextTable(study) {
  if (!study || !study.available) return `<p class='muted'>What happened next: ${esc(study && study.reason || 'no price history')}</p>`;
  const order = ['crowded short (index <= 20)', 'middle (20-80)', 'crowded long (index >= 80)'];
  const entries = Object.entries(study.buckets || {}).sort((a, b) => order.indexOf(a[0]) - order.indexOf(b[0]));
  const rows = entries.map(([name, b]) =>
    `<tr><td>${esc(name)}</td><td class='num'>${esc(b.weeks)}</td>
     <td class='num ${b.avg_move_pct > 0 ? 'long' : b.avg_move_pct < 0 ? 'short' : 'flat'}'>${b.avg_move_pct === null ? '-' : (b.avg_move_pct > 0 ? '+' : '') + b.avg_move_pct + ' %'}</td>
     <td class='num'>${esc(b.up_share_pct)} %</td>
     <td>${b.evidence === 'sufficient' ? "<span class='muted'>enough weeks</span>" : "<span class='tag thin'>thin</span>"}</td></tr>`).join('');
  return `<h3 style='margin:14px 0 6px'>What happened next, ${esc(study.weeks_ahead)} weeks on</h3>
    <div class='table-wrap'><table><tr><th>Reading at the time</th><th class='num'>Weeks</th><th class='num'>Average move</th><th class='num'>Share up</th><th>Evidence</th></tr>${rows}</table></div>
    <p class='subtle'>${esc(study.note)}</p>`;
}

function focusCard(symbol, m) {
  const tags = [m.extreme ? `<span class='tag hot'>${esc(m.extreme)}</span>` : '',
                m.flipped ? `<span class='tag flip'>${esc(m.flipped)}</span>` : ''].join(' ');
  return `<div class='card'>
    <div style='display:flex;justify-content:space-between;align-items:baseline;gap:8px'>
      <h2 style='margin:0'>${esc(symbol)}</h2><span class='muted'>as of ${esc(m.as_of)}</span></div>
    <p class='big ${cls(m.stance)}' style='margin:8px 0 0'>${signed(m.net)}<span class='muted' style='font-size:14px;font-weight:500'> contracts, ${esc(m.stance)}</span></p>
    <p class='muted' style='margin:2px 0 0'>${esc(m.net_pct_of_open_interest)} % of open interest ${tags}</p>
    <div style='margin:10px 0 0'>${spark(m.sparkline)}<span class='subtle'>net contracts, last ${esc(m.sparkline_weeks)} weeks</span></div>
    <dl class='kv'>
      <dt>COT index (3 years)</dt><dd>${barCell(m.cot_index, 'of 100', 'idx')}</dd>
      <dt>Percentile of history</dt><dd>${barCell(m.percentile_net_pct, 'of 100')}</dd>
      <dt>Change 1w / 4w</dt><dd>${signed(m.week_change_net)} / ${signed(m.change_4w)}</dd>
      <dt>Commercials (other side)</dt><dd class='${m.commercial_net < 0 ? 'short' : 'long'}'>${signed(m.commercial_net)}</dd>
      <dt>Small traders</dt><dd class='${m.small_trader_net < 0 ? 'short' : 'long'}'>${signed(m.small_trader_net)}</dd>
      <dt>Open interest</dt><dd>${num(m.open_interest)} <span class='subtle'>(${signed(m.open_interest_change)} on the week)</span></dd>
    </dl>
    ${nextTable(m.what_happened_next)}</div>`;
}

async function load() {
  let d;
  try { d = await (await fetch('/api/positioning')).json(); } catch (e) { document.getElementById('asof').textContent = 'Unavailable: ' + e; return; }
  if (!d.available) { document.getElementById('asof').textContent = d.reason || 'No positioning data yet.'; return; }
  const r = d.report || {};
  document.getElementById('asof').innerHTML = `<strong>Not live.</strong> Positions as of <strong>${esc(r.as_of_tuesday)}</strong> (Tuesday), published ${esc(r.released)} - <strong>${esc(r.age_days)} days old</strong>. Next release about ${esc(r.next_release_estimate)}. Source: ${esc(d.source)}.<div class='muted' style='margin-top:4px;font-size:12px'>${esc(d.note)}</div>`;
  const rows = (d.markets || []).filter(m => m.available);
  document.getElementById('table').innerHTML = `<table><tr><th>Market</th><th>Stance</th><th class='num'>Net</th><th class='num'>% of OI</th>
      <th class='num'>1w</th><th class='num'>4w</th><th class='num'>13w</th><th class='num'>Commercials</th><th>COT index</th><th>Percentile</th><th>Net, 2 years</th></tr>` +
    rows.map(m => `<tr class='${m.symbol ? 'mine' : ''}'>
      <td>${esc(m.market)}${m.symbol ? " <span class='muted'>" + esc(m.symbol) + "</span>" : ''}</td>
      <td class='${cls(m.stance)}'>${esc(m.stance)}${m.extreme ? " <span class='tag hot'>" + esc(m.extreme.split('(')[0].trim()) + "</span>" : ''}${m.flipped ? " <span class='tag flip'>" + esc(m.flipped) + "</span>" : ''}</td>
      <td class='num ${cls(m.stance)}'>${signed(m.net)}</td>
      <td class='num'>${esc(m.net_pct_of_open_interest)} %</td>
      <td class='num'>${signed(m.week_change_net)}</td><td class='num'>${signed(m.change_4w)}</td><td class='num'>${signed(m.change_13w)}</td>
      <td class='num ${m.commercial_net < 0 ? 'short' : 'long'}'>${signed(m.commercial_net)}</td>
      <td>${barCell(m.cot_index, 'of 100', 'idx')}</td>
      <td>${barCell(m.percentile_net_pct, '· ' + esc(m.weeks_of_history) + ' weeks')}</td>
      <td>${spark(m.sparkline, true)}</td></tr>`).join('') + '</table>';
  const u = d.usd_proxy || {};
  document.getElementById('usd').innerHTML = u.available ? `<p><strong class='${u.net_of_currencies < 0 ? 'long' : 'short'}'>${esc(u.stance)}</strong> · summed currency net ${signed(u.net_of_currencies)} contracts (${esc((u.components || []).join(', '))})</p><p class='muted'>${esc(u.note)}</p>` : `<p class='muted'>${esc(u.reason)}</p>`;
  const mine = d.system_markets || {};
  const bySymbol = {}; rows.forEach(m => { if (m.symbol) bySymbol[m.symbol] = m; });
  document.getElementById('focus').innerHTML = Object.keys(mine).length
    ? Object.entries(mine).map(([sym, m]) => focusCard(sym, Object.assign({}, bySymbol[sym] || {}, m))).join('')
    : "<div class='card'><p class='muted'>Neither traded market is in this report yet.</p></div>";
  document.getElementById('status-line').textContent = 'updated ' + esc(d.generated_at) + ' UTC';
}
document.getElementById('refresh-btn').addEventListener('click', load);
load();
setInterval(load, 300000);
</script>
</body>
</html>
"""


@app.route('/api/atomic-analyst')
def atomic_analyst_api():
  """The owner's MT5 ATOMIC ANALYST V85 panel as read-only evidence, with how it lines up with the system's plans.
  It never feeds the signal engine, the execution gate, position size or a stop (src/atomic_analyst.py)."""
