@app.route('/api/ai/chat', methods=['POST'])
def ai_chat_api():
  payload = request.get_json(silent=True) or {}
  message = str(payload.get('message', '') or '').strip()
  if not message:
    return jsonify({'error': 'message is required'}), 400

  AI_CHAT_MEMORY.add('user', message)
  reply = AI_CHAT_ENGINE.reply(message, market_snapshot=_ai_market_snapshot())
  
  # Handle dictionary response (new format with formatting)
  if isinstance(reply, dict):
    reply_content = reply.get('content', str(reply))
    reply_format = reply.get('format', 'text')
    AI_CHAT_MEMORY.add('assistant', reply_content, metadata={
      'format': reply_format,
      'topic': reply.get('topic'),
      'symbol': reply.get('symbol'),
      'has_code': reply.get('has_code', False)
    })
  else:
    # Fallback for string responses (backward compatibility)
    reply_content = str(reply)
    AI_CHAT_MEMORY.add('assistant', reply_content)
  
  return jsonify({
    'reply': reply if isinstance(reply, dict) else {'content': reply, 'format': 'text'},
    'messages': AI_CHAT_MEMORY.recent(limit=30),
  })


def _to_bool(value):
  if isinstance(value, bool):
    return value
  raw = str(value or '').strip().lower()
  return raw in {'1', 'true', 'yes', 'on'}


def _voice_enrich_result(result: dict):
  enriched = dict(result or {})
  if enriched.get('intent') in ['market_data', 'analysis', 'trading', 'performance']:
    enriched['snapshot'] = _ai_market_snapshot()
  if enriched.get('action') == 'check_health':
    enriched['mt5'] = MT5_ENGINE.status()
  return enriched


def _voice_reply_text(result: dict) -> str:
  if not isinstance(result, dict):
    return "I processed your command."
  for key in ('speech', 'response', 'message', 'reply'):
    value = result.get(key)
    if isinstance(value, str) and value.strip():
      return value.strip()
  intent = str(result.get('intent') or 'general')
  action = str(result.get('action') or 'completed')
  return f"Intent {intent} processed with action {action}."


def _voice_build_speak_payload(reply_text: str, use_external_tts: bool, tts_provider: str | None = None) -> dict:
  text = str(reply_text or "").strip()
  if not text:
    return {'provider': 'browser_speech_synthesis', 'text': ''}
  if not bool(use_external_tts):
    return {'provider': 'browser_speech_synthesis', 'text': text}
  try:
    synthesized = VOICE_EXTERNAL_PROVIDERS.synthesize(text=text, provider=tts_provider)
    if synthesized.get('audio_base64'):
      return synthesized
    return {'provider': 'browser_speech_synthesis', 'text': text}
  except (ValueError, RuntimeError) as exc:
    return {
      'provider': 'browser_speech_synthesis',
      'text': text,
      'fallback_reason': str(exc),
    }


def _voice_process_transcript_safe(transcript: str) -> dict:
  clean = str(transcript or '').strip()
  if not clean:
    raise ValueError('transcript is required')
  try:
    dynamic_ai = get_dynamic_voice_ai()
    result = dynamic_ai.understand_command(clean)
    return _voice_enrich_result(result)
  except Exception as exc:
    fallback = VOICE_ENGINE.process_text(clean)
    fallback = dict(fallback) if isinstance(fallback, dict) else {'accepted': False, 'raw': fallback}
    fallback['fallback_used'] = True
    fallback['fallback_reason'] = str(exc)
    return fallback


