@app.route('/api/voice/process', methods=['POST'])
def voice_process_api():
  try:
    # Try to get JSON data
    payload = request.get_json(force=True, silent=False)
  except Exception:
    # Fallback to form data
    payload = request.form.to_dict() or {}
  
  # Get transcript from payload
  transcript = str(payload.get('transcript') or payload.get('message') or '').strip()
  
  if not transcript:
    return jsonify({'error': 'transcript is required', 'received_payload': payload}), 400

  result = _voice_process_transcript_safe(transcript)
   
  return jsonify(result)


