def _mt_terminal_log_dirs() -> list[Path]:
  """Every MetaQuotes terminal data folder that holds an MQL4 expert log."""
  root = Path(os.environ.get('APPDATA', '')) / 'MetaQuotes' / 'Terminal'
  if not root.exists():
    return []
  return [path for path in root.glob('*/MQL4/Logs') if path.is_dir()]


def _ea_log_tail(limit: int = 25) -> dict:
  """Most recent expert-log lines, so the panel shows what the EA is saying."""
  newest_file = None
  newest_mtime = None
  for log_dir in _mt_terminal_log_dirs():
    for candidate in log_dir.glob('*.log'):
      try:
        mtime = candidate.stat().st_mtime
      except OSError:
        continue
      if newest_mtime is None or mtime > newest_mtime:
        newest_mtime, newest_file = mtime, candidate
  if newest_file is None:
    return {'available': False, 'reason': 'no MetaTrader expert logs found', 'lines': []}
  try:
    raw = newest_file.read_text(encoding='utf-8', errors='replace')
  except Exception as exc:
    return {'available': False, 'reason': str(exc), 'lines': []}
  # MT4 writes these logs with bare CR separators.
  rows = [row.strip() for row in raw.replace('\r', '\n').splitlines() if row.strip()]
  errors = sum(1 for row in rows if 'ERROR' in row.upper())
  return {
    'available': True,
    'file': newest_file.name,
    'terminal': newest_file.parents[2].name,
    'updated_at': datetime.fromtimestamp(newest_mtime, timezone.utc).isoformat(),
    'total_lines': len(rows),
    'error_lines': errors,
    'lines': rows[-int(limit):],
  }


@app.route('/api/ea/overview')
def ea_overview_api():
  """Everything the EA panel needs: bridge health, quotes, account, EA log."""
  symbols = ['XAUUSD', 'BTCUSD']
  bridges = {}
  for key, engine in (('mt4', MT4_ENGINE), ('mt5', MT5_ENGINE)):
    try:
      status = engine.status()
    except Exception as exc:
      status = {'connected': False, 'message': str(exc)}
    quotes = {}
    if status.get('connected'):
      for symbol in symbols:
        try:
          quotes[symbol] = engine.check_symbol(symbol)
        except Exception as exc:
          quotes[symbol] = {'valid': False, 'reason': str(exc)}
    bridges[key] = {'status': status, 'quotes': quotes}

  # Compare the broker feed against Yahoo: a wide basis means plans are being
  # priced off an instrument the account does not actually trade.
  comparison = {}
  for symbol in symbols:
    broker_price, broker_source = fetch_broker_quote(symbol)
    reference = None
    try:
      ticker = YAHOO_TICKERS.get(symbol, [symbol])[0]
      history = yf.Ticker(ticker).history(period='1d', interval='1m')
      closes = history['Close'].dropna() if history is not None and not history.empty else None
      reference = round(float(closes.iloc[-1]), 4) if closes is not None and not closes.empty else None
    except Exception:
      reference = None
    entry = {
      'broker_price': broker_price,
      'broker_source': broker_source,
      'reference_price': reference,
      'basis': None,
      'basis_pct': None,
    }
    if broker_price and reference:
      entry['basis'] = round(broker_price - reference, 4)
      entry['basis_pct'] = round((broker_price - reference) / reference * 100, 4)
    comparison[symbol] = entry

  account = {}
  try:
    if bridges['mt5']['status'].get('connected'):
      account = MT5_ENGINE.account_info()
    elif bridges['mt4']['status'].get('connected'):
      account = MT4_ENGINE.account_info()
  except Exception as exc:
    account = {'error': str(exc)}

  return jsonify({
    'generated_at': datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
    'bridges': bridges,
    'price_comparison': comparison,
    'account': account,
    'ea_log': _ea_log_tail(limit=25),
    'active_feed': _market_get_quote_source('XAUUSD'),
  })


