@app.route('/api/chart-data/<symbol>')
def chart_data_api(symbol: str):
  """Returns live OHLC candle data for Lightweight Charts"""
  symbol = symbol.upper()
  timeframe = str(request.args.get('timeframe', '1h') or '1h').strip().lower()
  tf_map = {
    '15m': {'interval': '15m', 'period': '5d', 'bars': 160},
    '1h': {'interval': '1h', 'period': '7d', 'bars': 120},
    '4h': {'interval': '4h', 'period': '30d', 'bars': 160},
    '1d': {'interval': '1d', 'period': '120d', 'bars': 220},
  }
  profile = tf_map.get(timeframe, tf_map['1h'])
  
  try:
    # Fetch live data from MT5
    data = fetch_real_data(symbol, period=profile['period'], interval=profile['interval'])
    if data.empty:
      data = generate_synthetic_data(symbol, n=profile['bars'])
    
    # Format for Lightweight Charts (OHLCV format)
    candles = []
    for idx, row in data.tail(int(profile['bars'])).iterrows():
      timestamp = int(row['datetime'].timestamp()) if hasattr(row['datetime'], 'timestamp') else int(idx)
      candles.append({
        "time": timestamp,
        "open": round(float(row['open']), 4),
        "high": round(float(row['high']), 4),
        "low": round(float(row['low']), 4),
        "close": round(float(row['close']), 4),
        "volume": float(row.get('volume', 0)) if 'volume' in data.columns else 0
      })
    
    return jsonify({
      "symbol": symbol,
      "timeframe": profile['interval'],
      "status": "ok",
      "candles": candles,
      "count": len(candles),
      "timestamp": datetime.now(timezone.utc).isoformat()
    })
  except Exception as e:
    return jsonify({
      "symbol": symbol,
      "status": "error",
      "message": str(e),
      "candles": []
    }), 500


@app.route('/api/analyze-chart/<symbol>')
def analyze_chart_api(symbol: str):
  """AI-powered chart analysis with pattern recognition and JARVIS voice response"""
  symbol = symbol.upper()
  timeframe = str(request.args.get('timeframe', '1h') or '1h').strip().lower()
  tf_map = {
    '15m': {'interval': '15m', 'period': '10d'},
    '1h': {'interval': '1h', 'period': '30d'},
    '4h': {'interval': '4h', 'period': '90d'},
    '1d': {'interval': '1d', 'period': '180d'},
  }
  profile = tf_map.get(timeframe, tf_map['1h'])
  time_label = {
    '15m': '15 minutes',
    '1h': '1 hour',
    '4h': '4 hours',
    '1d': '1 day',
  }.get(profile['interval'], profile['interval'])
  
  try:
    # Get chart data
    data = fetch_real_data(symbol, period=profile['period'], interval=profile['interval'])
    if data.empty:
      data = generate_synthetic_data(symbol, n=500)
    
    # Extract features for analysis
    features = build_features(data)
    latest = features.iloc[-1] if not features.empty else None
    
    # Get current price and signals
    current_price, change_pct = fetch_yahoo_quote(symbol)
    if current_price is None:
      current_price = float(data['close'].iloc[-1])
    
    # Get current model signal
    signals = build_signal_payload()
    current_signal = next((s for s in signals if s['symbol'] == symbol), {})
    plan = build_live_plan(symbol)
    confluence = _jarvis_multi_timeframe_confluence(symbol)
    regime = _jarvis_market_regime(features, data)
    calibration = _jarvis_confidence_calibration(symbol, profile['interval'], float(plan.get('confidence') or current_signal.get('confidence') or 0.55))
    calibrated_plan = dict(plan)
    calibrated_plan['confidence'] = calibration.get('calibrated_confidence')
    probabilistic = _jarvis_probabilistic_outlook(calibrated_plan, confluence, regime)
    event_risk_gate = _jarvis_event_risk_gate(data, features, profile['interval'], confluence, regime)
    entry_zone = _jarvis_entry_zone_and_invalidation(plan, profile['interval'], regime)
    execution_signal = str(current_signal.get('signal', 'HOLD') or 'HOLD').upper()

    confluence_score = float(confluence.get('score') or 50.0)
    tp1_prob = float(probabilistic.get('tp1_hit_probability') or 0.5)
    calibrated_conf = float(calibration.get('calibrated_confidence') or 0.55)
    risk_level = str(event_risk_gate.get('risk_level') or 'low')

    gate_action = 'open'
    risk_multiplier = 1.0
    allow_trade = True

    if risk_level == 'high':
      high_quality_override = confluence_score >= 78.0 and tp1_prob >= 0.68 and calibrated_conf >= 0.58
      if high_quality_override:
        gate_action = 'caution_high_quality_override'
        risk_multiplier = 0.72
        event_risk_gate['notes'] = list(event_risk_gate.get('notes') or []) + ['high-quality signal override applied']
      else:
        gate_action = 'block_extreme_risk'
        risk_multiplier = 0.0
        allow_trade = False
    elif risk_level == 'medium':
      gate_action = 'caution'
      risk_multiplier = 0.82

    event_risk_gate['gate_action'] = gate_action
    event_risk_gate['risk_multiplier'] = round(risk_multiplier, 2)
    event_risk_gate['allow_trade'] = allow_trade
    event_risk_gate['learning_mode_active'] = True
    event_risk_gate['learning_capture'] = True

    if not allow_trade:
      execution_signal = 'HOLD'

    def compact_plan(asset_symbol: str):
      try:
        p = build_live_plan(asset_symbol)
      except Exception:
        p = {}
      return {
        'symbol': asset_symbol,
        'entry': p.get('entry'),
        'stop_loss': p.get('stop_loss'),
        'take_profit_1': p.get('take_profit_1'),
        'take_profit_2': p.get('take_profit_2'),
        'take_profit_3': p.get('take_profit_3'),
        'confidence': p.get('confidence'),
        'grade': p.get('grade'),
        'risk_reward': p.get('risk_reward'),
        'signal': p.get('signal'),
      }

    core_asset_plans = {
      'XAUUSD': compact_plan('XAUUSD'),
      'BTCUSD': compact_plan('BTCUSD'),
    }
    
    # Detect chart patterns
    if latest is not None:
      trend_5 = float(latest.get('trend_5', 0) or 0)
      trend_20 = float(latest.get('trend_20', 0) or 0)
      rsi_14 = float(latest.get('rsi_14', 50) or 50)
      volatility = float(latest.get('volatility_5d', 0) or 0)
      
      # Pattern analysis
      if trend_5 > trend_20 and rsi_14 > 60:
        pattern = "Strong Uptrend with Momentum"
        sentiment = "Bullish"
        confidence = min(0.95, 0.6 + volatility * 0.1)
      elif trend_5 < trend_20 and rsi_14 < 40:
        pattern = "Strong Downtrend with Weakness"
        sentiment = "Bearish"
        confidence = min(0.95, 0.6 + volatility * 0.1)
      elif abs(trend_5 - trend_20) < 0.01 and 40 <= rsi_14 <= 60:
        pattern = "Consolidation Zone"
        sentiment = "Neutral"
        confidence = 0.5
      elif trend_5 > trend_20 and 40 <= rsi_14 <= 60:
        pattern = "Uptrend in Development"
        sentiment = "Bullish"
        confidence = 0.7
      else:
        pattern = "Mixed Signals"
        sentiment = "Neutral"
        confidence = 0.55
      
      # Support and Resistance
      support = round(data['low'].tail(50).min(), 4)
      resistance = round(data['high'].tail(50).max(), 4)
      
      # Generate JARVIS-friendly analysis text
      analysis_text = (
        f"{symbol} chart shows {pattern}. Price at {current_price}. "
        f"RSI reading {rsi_14:.0f}. Volatility {volatility*100:.1f} percent. "
        f"Entry {plan.get('entry')}, stop loss {plan.get('stop_loss')}, take profit one {plan.get('take_profit_1')}. "
        f"Support level {support}. Resistance level {resistance}. "
        f"Sentiment {sentiment}. Recommendation: {execution_signal}. "
        f"Confidence {confidence*100:.0f} percent. Grade {plan.get('grade', '--')} with risk reward {plan.get('risk_reward', '--')}. "
        f"Confluence score {confluence.get('score')} with {confluence.get('alignment')}. "
        f"Market regime {regime.get('name')} ({regime.get('bias')}). "
        f"TP1 probability {round(float(probabilistic.get('tp1_hit_probability', 0))*100)} percent. "
        f"Calibrated confidence {round(float(calibration.get('calibrated_confidence', 0))*100)} percent from {int(float(calibration.get('historical_win_rate', 0))*100)} percent historical win rate. "
        f"Event risk is {event_risk_gate.get('risk_level')} with action {event_risk_gate.get('gate_action')} and multiplier {event_risk_gate.get('risk_multiplier')}. "
        f"Learning mode remains active for all outcomes."
      )
      
      return jsonify({
        "symbol": symbol,
        "timeframe": profile['interval'],
        "status": "ok",
        "price": current_price,
        "change_pct": change_pct,
        "pattern": pattern,
        "sentiment": sentiment,
        "confidence": round(confidence, 2),
        "rsi": round(rsi_14, 1),
        "volatility": round(volatility * 100, 1),
        "support": support,
        "resistance": resistance,
        "signal": current_signal.get('signal', 'HOLD'),
        "execution_signal": execution_signal,
        "model_confidence": current_signal.get('confidence', 0.55),
        "entry": plan.get('entry'),
        "stop_loss": plan.get('stop_loss'),
        "take_profit_1": plan.get('take_profit_1'),
        "take_profit_2": plan.get('take_profit_2'),
        "take_profit_3": plan.get('take_profit_3'),
        "grade": plan.get('grade'),
        "risk_reward": plan.get('risk_reward'),
        "plan_confidence": plan.get('confidence'),
        "confidence_calibration": calibration,
        "confluence": confluence,
        "market_regime": regime,
        "probabilistic_outlook": probabilistic,
        "event_risk_gate": event_risk_gate,
        "entry_zone": entry_zone,
        "core_asset_plans": core_asset_plans,
        "analysis_text": analysis_text,
        "chart_metadata": {
          "bars_analyzed": len(data),
          "time_period": time_label,
          "analysis_time": datetime.now(timezone.utc).isoformat()
        }
      })
    else:
      return jsonify({
        "symbol": symbol,
        "status": "error",
        "message": "Insufficient data for analysis"
      }), 400
      
  except Exception as e:
    return jsonify({
      "symbol": symbol,
      "status": "error",
      "message": str(e)
    }), 500



# ============================================================================
