@app.route('/api/system-health')
def system_health_api():
  """System health with fast cache-backed lite mode for responsive UI startup."""
  full_mode = str(request.args.get('full', '0') or '0').strip().lower() in {'1', 'true', 'yes'}
  refresh = str(request.args.get('refresh', '0') or '0').strip().lower() in {'1', 'true', 'yes'}
  cache_key = 'full' if full_mode else 'lite'
  now_mono = monotonic()

  with SYSTEM_HEALTH_LOCK:
    cached = SYSTEM_HEALTH_CACHE.get(cache_key, {})
    cached_payload = cached.get('payload')
    cached_at = float(cached.get('generated_at') or 0.0)
    if (not refresh) and cached_payload and (now_mono - cached_at) <= SYSTEM_HEALTH_CACHE_TTL_SECONDS:
      payload = dict(cached_payload)
      payload['cached'] = True
      payload['mode'] = cache_key
      return jsonify(payload)

  health = {}

  # ── MT5 connection ─────────────────────────────────────────────────────────
  try:
    mt5_stat = MT5_ENGINE.status()
    health['mt5'] = {
      'status': 'connected' if mt5_stat.get('connected') else 'disconnected',
      'detail': mt5_stat
    }
  except Exception as e:
    health['mt5'] = {'status': 'error', 'detail': str(e)}

  # ── ML models ──────────────────────────────────────────────────────────────
  models = {}
  for sym in ['XAUUSD', 'BTCUSD']:
    m = get_model_status(sym)
    models[sym] = {
      'loaded': m.get('model_loaded', False),
      'accuracy': m.get('accuracy'),
      'last_trained': m.get('last_trained_at')
    }
  health['models'] = models

  # ── Prices (lite uses cache only; full can fetch live quotes) ─────────────
  prices = {}
  for sym in ['XAUUSD', 'BTCUSD']:
    cached_quote = _market_get_cached_quote(sym) or {}
    p = cached_quote.get('price')
    chg = cached_quote.get('change_pct')
    source = 'cached'
    if full_mode:
      live_p, live_chg = fetch_yahoo_quote(sym)
      if live_p is not None:
        p, chg = live_p, live_chg
        source = 'live'
      elif p is None:
        source = 'unavailable'
    elif p is None:
      source = 'unavailable'
    prices[sym] = {'price': p, 'change_pct': chg, 'source': source}
  health['prices'] = prices

  # ── Signals (skip expensive build in lite mode) ───────────────────────────
  if full_mode:
    try:
      sigs = build_signal_payload()
      health['signals'] = {s['symbol']: {'signal': s['signal'], 'confidence': s['confidence']} for s in sigs}
    except Exception as e:
      health['signals'] = {'error': str(e)}
  else:
    health['signals'] = {'status': 'skipped-lite-mode'}

  # ── Auto-trader session ────────────────────────────────────────────────────
  try:
    state = load_auto_trader_state()
    session = state.get('session') or {}
    summary = summarize_auto_trader_state(state)
    health['trading'] = {
      'session_active': bool(session.get('active')),
      'balance': session.get('current_balance', 0),
      'win_rate': summary.get('win_rate', 0),
      'trades': summary.get('closed_trades', 0)
    }
  except Exception as e:
    health['trading'] = {'error': str(e)}

  # ── Voice engine ───────────────────────────────────────────────────────────
  try:
    vs = VOICE_ENGINE.status()
    health['voice'] = {'enabled': vs.get('enabled', True), 'wakeword': vs.get('wakeword')}
  except Exception:
    health['voice'] = {'enabled': True, 'wakeword': 'hey jarvis'}

  # ── Overall score ──────────────────────────────────────────────────────────
  live_prices_ok = all(v.get('price') is not None for v in prices.values())
  signals_ok = bool(health.get('signals')) and not (isinstance(health.get('signals'), dict) and health['signals'].get('error'))
  ok_count = sum([
    health['mt5']['status'] == 'connected',
    all(v['loaded'] for v in models.values()),
    live_prices_ok,
    signals_ok,
    health['voice']['enabled'],
  ])
  health['score'] = ok_count
  health['score_max'] = 5
  health['overall'] = 'healthy' if ok_count >= 4 else 'degraded' if ok_count >= 2 else 'critical'
  health['timestamp'] = datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S')
  health['cached'] = False
  health['mode'] = cache_key

  with SYSTEM_HEALTH_LOCK:
    SYSTEM_HEALTH_CACHE[cache_key] = {
      'generated_at': monotonic(),
      'payload': dict(health),
    }

  return jsonify(health)


@app.route('/api/morning-briefing')
def morning_briefing_api():
  """JARVIS morning briefing — spoken on startup."""
  from jarvis_voice_response import get_voice_engine
  
  health_resp = system_health_api()
  h = health_resp.get_json()

  tz_offset_min_raw = request.args.get('tz_offset_min')
  local_now = datetime.now(timezone.utc)
  try:
    if tz_offset_min_raw is not None:
      tz_offset_min = int(str(tz_offset_min_raw).strip())
      local_now = local_now - timedelta(minutes=tz_offset_min)
  except Exception:
    pass

  lines = ["JARVIS system is online."]

  # Overall
  lines.append(f"System health is {h.get('overall', 'unknown')}. Score {h.get('score')}/{h.get('score_max')}.")

  # MT5
  mt5_status = h.get('mt5', {}).get('status', 'unknown')
  lines.append(f"MetaTrader 5 is {mt5_status}.")

  # Prices
  for sym, info in (h.get('prices') or {}).items():
    if info.get('price'):
      chg = info.get('change_pct', 0) or 0
      direction = 'up' if chg >= 0 else 'down'
      lines.append(f"{sym} is at {info['price']}, {direction} {abs(chg):.2f} percent.")

  # Signals
  for sym, info in (h.get('signals') or {}).items():
    if isinstance(info, dict):
      lines.append(f"{sym} signal: {info.get('signal', 'N/A')} with {int((info.get('confidence',0))*100)} percent confidence.")

  # Trading session
  trading = h.get('trading', {})
  if trading.get('session_active'):
    lines.append(f"Auto-trader is active. Balance {trading.get('balance', 0):.2f}. Win rate {trading.get('win_rate', 0)} percent.")
  else:
    lines.append("No active trading session. Say start session to begin.")

  # Models
  for sym, info in (h.get('models') or {}).items():
    if info.get('loaded'):
      acc = info.get('accuracy')
      acc_str = f"Accuracy {acc:.2f}." if acc else ""
      lines.append(f"{sym} model loaded. {acc_str}")
    else:
      lines.append(f"Warning: {sym} model not loaded. Consider retraining.")

  lines.append("JARVIS is ready. Say hey JARVIS followed by your command.")

  briefing_text = " ".join(lines)
  
  # The browser speaks this briefing itself, in the voice the page picked. Speaking it here as well - through the PC's
  # own Windows voice - meant two different voices reading the same words a fraction of a second apart, which is what
  # the owner heard. The server now speaks only when a caller explicitly asks (?speak=1), for callers with no browser.
  spoken_here = False
  if str(request.args.get('speak') or '').strip() in ('1', 'true', 'yes'):
    try:
      voice_engine = get_voice_engine()
      if voice_engine and voice_engine.engine:
        voice_engine.speak(briefing_text, wait=False)
        spoken_here = True
    except Exception as e:
      logger.warning(f"Could not speak briefing: {e}")
  
  return jsonify({
    "spoken_by_server": spoken_here,
    "briefing": briefing_text,
    "lines": lines,
    "health": h,
    "timestamp": datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S'),
    "voice_enabled": True
  })


