@app.route('/api/camera-analyze', methods=['POST'])
def camera_analyze_api():
  """
  Accepts a base64-encoded JPEG frame from JARVIS camera and
  runs the same OCR + powerful-analysis pipeline used for screenshots.
  """
  import base64, io

  payload = request.get_json(silent=True) or {}
  b64_image = str(payload.get('image', '')).strip()
  symbol    = str(payload.get('symbol', 'XAUUSD')).upper()
  if symbol not in {'XAUUSD', 'BTCUSD'}:
    symbol = 'XAUUSD'

  if not b64_image:
    return jsonify({'error': 'image is required'}), 400

  try:
    # Strip data-URL prefix if present
    if ',' in b64_image:
      b64_image = b64_image.split(',', 1)[1]

    image_bytes = base64.b64decode(b64_image)
    screenshots_dir = DATA_DIR / 'screenshots'
    screenshots_dir.mkdir(exist_ok=True)
    ts = datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')
    save_path = screenshots_dir / f"camera_{symbol.lower()}_{ts}.jpg"
    save_path.write_bytes(image_bytes)

    # OCR + AI analysis (same pipeline as screenshot-learn)
    ocr_result   = extract_ocr_from_screenshot(save_path)
    ocr_text     = str(ocr_result.get('text') or '').strip()
    parsed_levels = ocr_result.get('parsed_levels') or {}

    analysis = build_powerful_strategy_analysis(
      symbol,
      screenshot_notes='Camera capture from JARVIS',
      ocr_text=ocr_text,
      parsed_levels=parsed_levels,
    )

    # Build JARVIS voice response
    lines = [f"Camera analysis for {symbol}."]
    if analysis.get('signal'):
      lines.append(f"Signal is {analysis['signal']} with {int(analysis.get('confidence',0)*100)} percent confidence.")
    if analysis.get('entry'):
      lines.append(f"Entry at {analysis['entry']}.")
    if analysis.get('take_profit_1'):
      lines.append(f"Take profit at {analysis['take_profit_1']}.")
    if analysis.get('stop_loss'):
      lines.append(f"Stop loss at {analysis['stop_loss']}.")
    if parsed_levels:
      lines.append(f"Detected price levels: {', '.join(f'{k} {v}' for k,v in parsed_levels.items())}.")
    voice_text = ' '.join(lines)

    return jsonify({
      'symbol': symbol,
      'status': 'ok',
      'analysis': analysis,
      'ocr': ocr_result,
      'voice_text': voice_text,
      'image_saved': str(save_path),
    })

  except Exception as e:
    return jsonify({'status': 'error', 'message': str(e)}), 500


