@app.route('/api/jarvis/voice-verify', methods=['POST'])
def jarvis_voice_verify():
    """Verify user's voice - speaker authentication"""
    data = request.json or {}
    confidence = data.get('confidence', 0.7)
    
    # If no voice profile yet, accept with warning
    if not voice_auth.profile['voice_fingerprint']:
        return jsonify({
            'verified': True,
            'reason': 'Voice profile learning mode',
            'confidence': confidence,
            'status': 'enrollment_ready'
        })
    
    # Check confidence threshold
    if confidence < voice_auth.profile['confidence_threshold']:
        voice_auth.profile['rejected_voices'] += 1
        voice_auth.save_profile()
        return jsonify({
            'verified': False,
            'reason': f'Low confidence: {(confidence*100):.0f}% < {(voice_auth.profile["confidence_threshold"]*100):.0f}%',
            'confidence': confidence
        })
    
    voice_auth.profile['last_verified'] = datetime.now(timezone.utc).isoformat()
    voice_auth.save_profile()
    return jsonify({
        'verified': True,
        'reason': 'Voice recognized',
        'confidence': confidence,
        'status': 'authenticated'
    })


