@app.route('/api/jarvis/recommendations/trading', methods=['GET'])
def get_trading_recommendations():
    """Trading recommendations built from the live signals and trade plans.

    This used to return jarvis_recommendation_engine's hard-coded strategy table
    (BTC entry 43,000 with BTC near 77,000, S&P 4,780, "96% accurate" models, a
    2,450 daily profit target) as if it were live. Those numbers were never
    derived from market data, so they are no longer served.
    """
    try:
        signals = {str(item.get('symbol') or '').upper(): item for item in build_signal_payload()}
        recommendations = []
        for symbol, signal in signals.items():
            if not symbol:
                continue
            side = str(signal.get('signal') or 'HOLD').upper()
            rec = {
                'symbol': symbol,
                'strategy': signal.get('strategy_label'),
                'status': side,
                'confidence': signal.get('confidence'),
                'ensemble_probability': signal.get('ensemble_probability'),
                'generated_at': signal.get('generated_at'),
                'source': 'live RF+LSTM signal',
            }
            if _is_tradeable_side(side):
                plan = build_live_plan(symbol) or {}
                rec.update({
                    'description': f"{symbol} {side} setup (grade {plan.get('grade') or '-'})",
                    'entry_price': plan.get('entry'),
                    'stop_loss': plan.get('stop_loss'),
                    'take_profit_1': plan.get('take_profit_1'),
                    'take_profit_2': plan.get('take_profit_2'),
                    'take_profit_3': plan.get('take_profit_3'),
                    'risk_reward': plan.get('risk_reward'),
                })
            else:
                rec['description'] = f"{symbol}: no directional edge right now (HOLD)"
            recommendations.append(rec)
        return jsonify({
            'date': datetime.now(timezone.utc).strftime('%A, %B %d, %Y'),
            'available': bool(recommendations),
            'trading_recommendations': recommendations,
            'daily_profit_target': None,
            'daily_profit_target_available': False,
            'win_rate_target': None,
            'win_rate_target_available': False,
        })
    except Exception as e:
        return jsonify({'available': False, 'trading_recommendations': [], 'error': str(e)}), 200


