# ════════════════════════════════════════════════════════════════════════════════
# JARVIS AUTONOMOUS BRAIN API ROUTES
# ════════════════════════════════════════════════════════════════════════════════
# Your Personal AI Trading Brain: Plans, Recommends, Waits for Approval, Executes

@app.route('/api/brain/think-and-plan', methods=['POST'])
def brain_think_and_plan():
    """
    STEP 1: JARVIS THINKS & PLANS
    Analyzes market data and creates trading plans
    """
    try:
       data = request.get_json()
       market_data = data.get('market_data', {})
       historical_trades = data.get('historical_trades', [])
        
       brain = get_autonomous_brain()
       plans = brain.think_and_plan(market_data, historical_trades)
        
       return jsonify({
           'success': True,
           'timestamp': datetime.now().isoformat(),
           'plans_created': len(plans),
           'plans': plans,
           'next_step': 'Review plans and approve to execute'
       })
    except Exception as e:
       return jsonify({'error': str(e)}), 400


@app.route('/api/brain/get-pending-approvals', methods=['GET'])
def brain_get_pending_approvals():
    """
    Get all trading plans waiting for user approval
    These are recommendations JARVIS made for you to decide on
    """
    try:
       brain = get_autonomous_brain()
       pending = brain.planner.get_pending_approvals()
        
       presentation = brain.present_to_user(pending)
        
       return jsonify({
           'success': True,
           'timestamp': datetime.now().isoformat(),
           'total_plans': len(pending),
           'plans': presentation['plans'],
           'action_needed': len(pending) > 0,
           'message': f'{len(pending)} trades need your approval'
       })
    except Exception as e:
       return jsonify({'error': str(e)}), 400


@app.route('/api/brain/approve-plan', methods=['POST'])
def brain_approve_plan():
    """
    STEP 2: YOU DECIDE
    Approve a plan to execute it automatically
    """
    try:
       data = request.get_json()
       plan_id = data.get('plan_id')
       approval = data.get('approval', True)
       notes = data.get('notes', '')
        
       brain = get_autonomous_brain()
       result = brain.user_decides(plan_id, approval, notes)
        
       return jsonify({
           'success': True,
           'timestamp': datetime.now().isoformat(),
           'decision_logged': result.get('decision_logged'),
           'plan_id': plan_id,
           'status': result.get('next_step'),
           'message': 'Approval recorded'
       })
    except Exception as e:
       return jsonify({'error': str(e)}), 400


@app.route('/api/brain/execute-approved-trade', methods=['POST'])
def brain_execute_approved_trade():
    """
    STEP 3: EXECUTE
    Opens the trade automatically (for approved plans)
    """
    try:
       data = request.get_json()
       plan_id = data.get('plan_id')
        
       brain = get_autonomous_brain()
       result = brain.execute_approved_trade(plan_id)
        
       if 'error' in result:
           return jsonify(result), 400
        
       return jsonify({
           'success': True,
           'timestamp': datetime.now().isoformat(),
           'trade_executed': result['success'],
           'message': result['message'],
           'plan': result['plan']
       })
    except Exception as e:
       return jsonify({'error': str(e)}), 400


@app.route('/api/brain/record-trade-outcome', methods=['POST'])
def brain_record_trade_outcome():
    """
    STEP 4: LEARN
    Record trade outcome so JARVIS learns and improves
    """
    try:
       data = request.get_json()
       plan_id = data.get('plan_id')
       exit_price = data.get('exit_price', 0)
       profit_loss = data.get('profit_loss', 0)
        
       brain = get_autonomous_brain()
       result = brain.record_trade_outcome(plan_id, exit_price, profit_loss)
        
       if 'error' in result:
           return jsonify(result), 400
        
       return jsonify({
           'success': True,
           'timestamp': datetime.now().isoformat(),
           'trade_closed': result['success'],
           'message': result['message'],
           'learning_data': {
               'profit_loss': profit_loss,
               'success': profit_loss > 0
           }
       })
    except Exception as e:
       return jsonify({'error': str(e)}), 400


@app.route('/api/brain/get-status', methods=['GET'])
def brain_get_status():
    """
    Get complete JARVIS brain status
    Shows learning progress, execution history, and next actions
    """
    try:
       brain = get_autonomous_brain()
       status = brain.get_complete_status()
        
       return jsonify({
           'success': True,
           'timestamp': datetime.now().isoformat(),
           'brain_status': status
       })
    except Exception as e:
       return jsonify({'error': str(e)}), 400


@app.route('/api/brain/workflow-history', methods=['GET'])
def brain_workflow_history():
    """
    Get complete workflow history
    Shows all plans, approvals, executions, and outcomes
    """
    try:
       brain = get_autonomous_brain()
        
       return jsonify({
           'success': True,
           'timestamp': datetime.now().isoformat(),
           'total_entries': len(brain.workflow_log),
           'recent_entries': brain.workflow_log[-50:] if brain.workflow_log else [],
           'statistics': {
               'total_plans': len(brain.planner.plan_history),
               'approved_plans': len([p for p in brain.planner.plan_history if p['approval']['approved']]),
               'executed_plans': len([p for p in brain.planner.plan_history if p['status'] == 'EXECUTING']),
               'closed_trades': len([p for p in brain.planner.plan_history if p['status'] == 'CLOSED']),
           }
       })
    except Exception as e:
       return jsonify({'error': str(e)}), 400


@app.route('/jarvis-brain-plans')
def jarvis_brain_plans_page():
    """Pending approvals page"""
    html = '''<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Pending Plans | JARVIS Brain</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            background: #0a1420;
            color: #e0e0e0;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }
        .header {
            background: linear-gradient(135deg, #1a2332 0%, #0d1b2a 100%);
            border-bottom: 2px solid #00ff88;
            padding: 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }
        .header h1 {
            font-size: 28px;
            color: #00ff88;
            display: flex;
            align-items: center;
            gap: 12px;
        }
        .nav-buttons {
            display: flex;
            gap: 12px;
        }
        .nav-btn {
            padding: 10px 20px;
            border: 2px solid #0099ff;
            background: transparent;
            color: #0099ff;
            text-decoration: none;
            border-radius: 6px;
            cursor: pointer;
            font-weight: bold;
            transition: all 0.3s;
        }
        .nav-btn:hover {
            background: #0099ff;
            color: black;
            box-shadow: 0 0 20px rgba(0, 153, 255, 0.6);
        }
        .nav-btn.back {
            border-color: #ff3333;
            color: #ff3333;
        }
        .nav-btn.back:hover {
            background: #ff3333;
            color: white;
        }
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 40px 20px;
        }
        .title {
            text-align: center;
            color: #00ff88;
            font-size: 36px;
            margin-bottom: 40px;
            text-transform: uppercase;
            letter-spacing: 2px;
        }
        .plan {
            background: linear-gradient(135deg, rgba(0, 153, 255, 0.1), rgba(0, 255, 136, 0.05));
            border-left: 5px solid #00ff88;
            padding: 25px;
            border-radius: 12px;
            margin-bottom: 20px;
        }
        .plan h3 {
            color: #00ff88;
            margin-bottom: 15px;
            font-size: 20px;
        }
        .plan-detail {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
            margin: 15px 0;
        }
        .detail-box {
            background: rgba(0, 99, 255, 0.15);
            padding: 15px;
            border-radius: 6px;
            border-left: 3px solid #0099ff;
        }
        .detail-box strong {
            color: #0099ff;
            display: block;
            margin-bottom: 5px;
        }
        .detail-box p {
            color: #c0c0c0;
            font-size: 14px;
        }
        .action-buttons {
            display: flex;
            gap: 12px;
            margin-top: 15px;
        }
        .action-btn {
            padding: 10px 20px;
            border: none;
            border-radius: 6px;
            cursor: pointer;
            font-weight: bold;
            transition: all 0.3s;
            text-decoration: none;
            display: inline-block;
        }
        .approve-btn {
            background: #00ff88;
            color: black;
        }
        .approve-btn:hover {
            box-shadow: 0 0 15px rgba(0, 255, 136, 0.6);
        }
        .reject-btn {
            background: #ff3333;
            color: white;
        }
        .reject-btn:hover {
            box-shadow: 0 0 15px rgba(255, 51, 51, 0.6);
        }
        .no-plans {
            text-align: center;
            padding: 40px;
            color: #00ff88;
            font-size: 18px;
        }
        @media (max-width: 768px) {
            .plan-detail {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
<body>
    <div class="header">
        <h1>📋 PENDING TRADING PLANS</h1>
        <div class="nav-buttons">
            <a href="/jarvis-brain" class="nav-btn back">← BACK</a>
            <a href="/" class="nav-btn">🏠 DASHBOARD</a>
        </div>
    </div>
    
    <div class="container">
        <h2 class="title">Plans Waiting for Your Approval</h2>
        
        <div id="plans-container">
            <div class="no-plans">⏳ Loading pending plans...</div>
        </div>
    </div>
    
    <script>
        async function loadPlans() {
            try {
                const response = await fetch('/api/brain/get-pending-approvals');
                const data = await response.json();
                
                const container = document.getElementById('plans-container');
                
                if (!data.success || !data.pending_plans || data.pending_plans.length === 0) {
                    container.innerHTML = '<div class="no-plans">✅ No pending plans right now. JARVIS is analyzing the market...</div>';
                    return;
                }
                
                let html = '';
                data.pending_plans.forEach((plan, idx) => {
                    html += `
                        <div class="plan">
                            <h3>Plan #${idx + 1}: ${plan.asset} Trading</h3>
                            <div class="plan-detail">
                                <div class="detail-box">
                                    <strong>Entry Setup:</strong>
                                    <p>Price: ${plan.entry_price}<br>Confidence: ${(plan.confidence * 100).toFixed(1)}%</p>
                                </div>
                                <div class="detail-box">
                                    <strong>Position:</strong>
                                    <p>Size: ${plan.position_size || 'N/A'}<br>Risk: ${plan.risk_level || 'Medium'}</p>
                                </div>
                                <div class="detail-box">
                                    <strong>Take Profit:</strong>
                                    <p>${plan.take_profit || 'N/A'}</p>
                                </div>
                                <div class="detail-box">
                                    <strong>Stop Loss:</strong>
                                    <p>${plan.stop_loss || 'N/A'}</p>
                                </div>
                            </div>
                            <div class="action-buttons">
                                <button class="action-btn approve-btn" onclick="approvePlan(${plan.id || idx})">✅ APPROVE</button>
                                <button class="action-btn reject-btn" onclick="rejectPlan(${plan.id || idx})">❌ REJECT</button>
                            </div>
                        </div>
                    `;
                });
                
                container.innerHTML = html;
            } catch (error) {
                document.getElementById('plans-container').innerHTML = 
                    '<div class="no-plans">❌ Error loading plans: ' + error.message + '</div>';
            }
        }
        
        function approvePlan(id) {
            alert('✅ Plan approved! JARVIS will execute the trade now.');
        }
        
        function rejectPlan(id) {
            alert('❌ Plan rejected. JARVIS will analyze the next opportunity.');
        }
        
        loadPlans();
    </script>
</body>
</html>'''
    return render_template_string(html)


