# ── Telegram config endpoints ─────────────────────────────────────────────────
import importlib as _il

def _tg_cfg():
    try:
        import telegram_config as _tc
        _il.reload(_tc)
        return _tc
    except Exception:
        return None

@app.route('/api/telegram/config', methods=['GET'])
def telegram_get_config():
    tc = _tg_cfg()
    if tc is None:
        return jsonify({'enabled': False, 'bot_token': '', 'chat_id': ''})
    return jsonify({'enabled': getattr(tc,'ENABLED',False),
                    'bot_token': getattr(tc,'BOT_TOKEN',''),
                    'chat_id':   getattr(tc,'CHAT_ID','')})

@app.route('/api/telegram/config', methods=['POST'])
def telegram_save_config():
    data = request.get_json(force=True) or {}
    token   = str(data.get('bot_token','')).strip()
    chat_id = str(data.get('chat_id','')).strip()
    enabled = bool(data.get('enabled', False))
    cfg_path = os.path.join(os.path.dirname(__file__), 'telegram_config.py')
    try:
        with open(cfg_path, 'r', encoding='utf-8') as f:
            src = f.read()
        import re as _re
        src = _re.sub(r'^ENABLED\s*=.*$',  f'ENABLED = {enabled}',         src, flags=_re.M)
        src = _re.sub(r'^BOT_TOKEN\s*=.*$', f'BOT_TOKEN = "{token}"',       src, flags=_re.M)
        src = _re.sub(r'^CHAT_ID\s*=.*$',   f'CHAT_ID  = "{chat_id}"',      src, flags=_re.M)
        with open(cfg_path, 'w', encoding='utf-8') as f:
            f.write(src)
        return jsonify({'message': '✅ Telegram settings saved!'})
    except Exception as e:
        return jsonify({'message': f'❌ Error: {e}'}), 500

@app.route('/api/telegram/test', methods=['POST'])
def telegram_test():
    tc = _tg_cfg()
    if tc is None:
        return jsonify({'message': '❌ telegram_config.py not found'})
    if not getattr(tc,'ENABLED', False):
        return jsonify({'message': '⚠️ Telegram is disabled. Enable it first and save.'})
    ok = tc.send_server_alert('🧪 Test message from SmartEntry Pro AI!')
    if ok:
        return jsonify({'message': '✅ Test message sent! Check your Telegram.'})
    return jsonify({'message': '❌ Failed to send. Check your Token and Chat ID.'})
